def _parse_kv_file(path: Path) -> Dict[str, str]:
    values: Dict[str, str] = {}
    try:
        with open(path, "r", encoding="utf-8") as f:
            for raw_line in f:
                line = raw_line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, val = line.split("=", 1)
                values[key.strip()] = val.strip().strip('"').strip("'")
    except Exception as exc:
        print(f"[Config] Could not read {path}: {exc}")
    return values


def _load_secrets():
    """Load config from secrets files, .env and process env without letting partial files shadow Gmail config."""
    secrets = {}
    paths = [
        Path.home() / ".streamlit" / "secrets.toml",
        Path(__file__).parent / ".streamlit" / "secrets.toml",
        Path(__file__).parent / ".env",
    ]
    for sp in paths:
        if sp.exists():
            secrets.update(_parse_kv_file(sp))
    for key in (
        "POLYGON_KEY",
        "BPIQ_API_KEY",
        "ANTHROPIC_API_KEY",
        "FINNHUB_KEY",
        *_EMAIL_CONFIG_KEYS,
    ):
        if os.environ.get(key):
            secrets[key] = os.environ[key]
    return secrets

_SECRETS = _load_secrets()


def _config_flag(name: str, default: bool = False) -> bool:
    raw = os.environ.get(name)
    if raw is None:
        raw = _SECRETS.get(name)
    if raw is None:
        return default
    return str(raw).strip().lower() in {"1", "true", "yes", "on"}


def _validated_public_https_origin(value: Any) -> Optional[str]:
    """Return a production-safe HTTPS origin or None for placeholders/raw IPs."""
    raw = str(value or "").strip().rstrip("/")
    try:
        parsed = urlparse(raw)
    except Exception:
        return None
    hostname = str(parsed.hostname or "").strip().lower()
    if parsed.scheme != "https" or not hostname or parsed.username or parsed.password:
        return None
    if parsed.query or parsed.fragment or parsed.path not in {"", "/"}:
        return None
    if hostname == "localhost" or hostname.endswith((".localhost", ".example", ".invalid", ".test")):
        return None
    try:
        ipaddress.ip_address(hostname)
        return None
    except ValueError:
        pass
    port = f":{parsed.port}" if parsed.port else ""
    return f"https://{hostname}{port}"


