def _stock_trade_email_status(now_utc: Optional[datetime] = None) -> Dict[str, Any]:
    """Return whether actionable US-stock trade mails may be sent now.

    `get_current_trading_session()` intentionally returns "Regular" at night so
    the UI can show last regular-session data. Mail gates need the stricter
    exchange-calendar truth: only regular NYSE/Nasdaq hours count.
    """
    try:
        if now_utc is None:
            now_utc = datetime.now(timezone.utc)
        elif now_utc.tzinfo is None:
            now_utc = now_utc.replace(tzinfo=timezone.utc)

        # Prefer the existing official exchange calendar, including holidays
        # and early closes, when it is available in the fully loaded module.
        calendar_fn = globals().get("_build_exchange_calendar_status")
        if callable(calendar_fn):
            for exchange in calendar_fn(now_utc):
                if exchange.get("code") == "US":
                    if exchange.get("is_open"):
                        return {
                            "allowed": True,
                            "session": "US_REGULAR",
                            "reason": f"US regular session open ({exchange.get('now_local')} ET)",
                            "market_time": exchange.get("now_local"),
                        }
                    reason = exchange.get("closed_reason") or "US market closed"
                    next_open = exchange.get("next_open_zurich") or exchange.get("next_open_local")
                    if next_open:
                        reason = f"{reason}; next open {next_open}"
                    return {
                        "allowed": False,
                        "session": "CLOSED",
                        "reason": reason,
                        "market_time": exchange.get("now_local"),
                    }

        from zoneinfo import ZoneInfo
        now_et = now_utc.astimezone(ZoneInfo("America/New_York"))
        market_open = now_et.replace(hour=9, minute=30, second=0, microsecond=0)
        market_close = now_et.replace(hour=16, minute=0, second=0, microsecond=0)
        allowed = now_et.weekday() < 5 and market_open <= now_et < market_close
        return {
            "allowed": allowed,
            "session": "US_REGULAR" if allowed else "CLOSED",
            "reason": f"{'US regular session open' if allowed else 'US market closed'} ({now_et.strftime('%H:%M')} ET)",
            "market_time": now_et.strftime("%H:%M"),
        }
    except Exception as exc:
        return {
            "allowed": False,
            "session": "UNKNOWN",
            "reason": f"US market-session check failed: {exc}",
            "market_time": None,
        }


def _stock_trade_email_allowed(scanner_name: str) -> Tuple[bool, str]:
    status = _stock_trade_email_status()
    if status.get("allowed"):
        return True, str(status.get("reason") or "US regular session open")
    reason = str(status.get("reason") or "US market closed")
    _record_email_event(f"{scanner_name} Stock Alert", "skipped", f"us_market_closed:{reason}")
    print(f"[Alert] {scanner_name}: SKIP stock trade mail outside US regular session ({reason})")
    return False, reason


def _us_equity_expected_volume_fraction(now_utc: Optional[datetime] = None) -> float:
    """Expected cumulative regular-session volume using a conservative U-curve.

    Comparing a partial trading day with completed daily bars understates RVOL
    early in the session. Outside regular hours the snapshot is treated as a
    completed session and therefore is not projected.
    """
    try:
        from zoneinfo import ZoneInfo

        current = now_utc or datetime.now(timezone.utc)
        if current.tzinfo is None:
            current = current.replace(tzinfo=timezone.utc)
        now_et = current.astimezone(ZoneInfo("America/New_York"))
        if now_et.weekday() >= 5:
            return 1.0
        minutes_open = (now_et.hour * 60 + now_et.minute) - (9 * 60 + 30)
        if minutes_open <= 0 or minutes_open >= 390:
            return 1.0
        # NACHAUDIT N8 (re-audit): In den ersten 15 Handelsminuten NICHT
        # projizieren. Polygons Tagesvolumen enthaelt Premarket-Prints, die
        # U-Kurve modelliert nur die Regular Session — sonst manufacturiert
        # ein PM-lastiger Mover in Minute 1-14 riesige projizierte RVOL. Diese
        # Regel gehoert hier in die zentrale Fraction-Funktion, damit sie fuer
        # ALLE Projektions-Callsites gilt (Strategy-Scan, Volume-Spikes, Bear/
        # Turtle via _project_us_equity_rvol, ORB laeuft ohnehin erst ab Min 15).
        # Gleiches Muster wie der bereits vorhandene Penny-Guard.
        if minutes_open < 15:
            return 1.0

        anchors = (
            (0.0, 0.0),
            (5.0, 0.08),
            (15.0, 0.15),
            (30.0, 0.22),
            (60.0, 0.30),
            (120.0, 0.40),
            (240.0, 0.62),
            (330.0, 0.79),
            (390.0, 1.0),
        )
        for (left_min, left_fraction), (right_min, right_fraction) in zip(anchors, anchors[1:]):
            if minutes_open <= right_min:
                progress = (minutes_open - left_min) / max(right_min - left_min, 1.0)
                fraction = left_fraction + (right_fraction - left_fraction) * progress
                return round(max(0.01, min(fraction, 1.0)), 6)
    except Exception:
        pass
    return 1.0


def _project_us_equity_rvol(raw_rvol: Any, now_utc: Optional[datetime] = None) -> float:
    """Project partial-session US volume to a full-session RVOL pace.

    Der 15-Minuten-Guard (keine Projektion in Minute 1-14) sitzt zentral in
    `_us_equity_expected_volume_fraction`, damit er fuer alle Projektions-
    Callsites gilt. Hier wird nur noch delegiert.
    """
    try:
        value = max(0.0, float(raw_rvol or 0.0))
    except (TypeError, ValueError):
        return 0.0
    expected_fraction = _us_equity_expected_volume_fraction(now_utc)
    return project_partial_rvol(value, expected_fraction)


# ── AUDIT 2026-07-29 (Punkt C / RITM+NVST): Pre-Market-Radar + Opening-Takt ──
# Root-Cause des Blindfensters: vorbörsliche Explosionen (z.B. NVST ab 8:00 ET)
# wurden strukturell nie gemailt — (1) Mail-Session-Gate sperrt alles vor 9:30
# ET, (2) RVOL-Filter vergleicht duennes PM-Volumen mit dem 20-Tage-GANZTAGES-
# Schnitt und rejected jeden PM-Mover, (3) 30-Min-Takt. Die PM-Logik ersetzt
# RVOL deshalb durch ABSOLUTE PM-Liquiditaet + Spread-Guard + ATR-Extensions-
# Decke und schickt eine eigene, abschaltbare Fruehwarn-Mail.
_PREMARKET_WINDOW_START_ET = (7, 0)    # Frueheste PM-Mail: 7:00 ET
_PREMARKET_WINDOW_END_ET = (9, 25)     # Spaeteste PM-Mail: 9:25 ET (vor Open)
_PREMARKET_MIN_DOLLAR_VOLUME = 500_000.0   # Absoluter PM-Liquiditaets-Floor
_PREMARKET_MAX_SPREAD_PCT = 7.0            # Spread-Guard (PM-Spreizen)
_PREMARKET_MAX_EXTENSION_ATR = 3.0         # >3 ATR PM-Move = schon gelaufen
_PREMARKET_MIN_SCORE = 85                  # Strenger als Regular (80)
_OPENING_WINDOW_START_ET = (9, 25)   # Verdichteter Scan-Takt ab 9:25 ET
_OPENING_WINDOW_END_ET = (11, 30)    # ... bis 11:30 ET
_STRATEGY_SCAN_OPENING_INTERVAL_MIN = 10.0


def _et_wallclock_minutes(now_utc: Optional[datetime] = None) -> Optional[float]:
    """US-Eastern-Wanduhr in Minuten seit Mitternacht; None bei Fehler/WE."""
    try:
        from zoneinfo import ZoneInfo

        current = now_utc or datetime.now(timezone.utc)
        if current.tzinfo is None:
            current = current.replace(tzinfo=timezone.utc)
        now_et = current.astimezone(ZoneInfo("America/New_York"))
        if now_et.weekday() >= 5:
            return None
        return now_et.hour * 60 + now_et.minute + now_et.second / 60.0
    except Exception:
        return None


def _et_window_active(window: Tuple[Tuple[int, int], Tuple[int, int]], now_utc: Optional[datetime] = None) -> bool:
    minutes = _et_wallclock_minutes(now_utc)
    if minutes is None:
        return False
    start = window[0][0] * 60 + window[0][1]
    end = window[1][0] * 60 + window[1][1]
    return start <= minutes < end


def _premarket_window_active(now_utc: Optional[datetime] = None) -> bool:
    """True im PM-Mail-Fenster (7:00–9:25 ET, Mo–Fr)."""
    return _et_window_active((_PREMARKET_WINDOW_START_ET, _PREMARKET_WINDOW_END_ET), now_utc)


def _opening_window_active(now_utc: Optional[datetime] = None) -> bool:
    """True im Opening-Fenster (9:25–11:30 ET, Mo–Fr) — verdichteter Takt."""
    return _et_window_active((_OPENING_WINDOW_START_ET, _OPENING_WINDOW_END_ET), now_utc)


def _premarket_rvol_proxy(dollar_vol: Any) -> float:
    """Absolutes PM-Dollar-Volumen → RVOL-aequivalenter Intensitaets-Proxy.

    PM-RVOL (PM-Volumen vs. 20-Tage-Ganztages-Schnitt) ist mathematisch nicht
    vergleichbar — der ehrliche Proxy ist absolute PM-Liquiditaet: >$500k PM
    ist fuer die meisten Ticker aussergewoehnlich, >$5M extrem. Nur fuer
    Scoring/Gates; die Row behaelt den Roh-Wert als RVOL_PM_Raw.
    """
    try:
        dv = float(dollar_vol or 0.0)
    except (TypeError, ValueError):
        return 0.0
    if dv >= 5_000_000:
        return 3.0
    if dv >= 2_000_000:
        return 2.5
    if dv >= 1_000_000:
        return 2.0
    if dv >= 500_000:
        return 1.5
    return 0.0


def _premarket_scan_gate_reason(
    *,
    dollar_vol: Any,
    spread_pct: Optional[float],
    min_dollar_vol: float = _PREMARKET_MIN_DOLLAR_VOLUME,
    max_spread_pct: float = _PREMARKET_MAX_SPREAD_PCT,
) -> str:
    """Fruehe PM-Gates im Strategy-Scan (pure, testbar).

    Ersetzt im Pre-Market das Dollar-Vol-/RVOL-Filter-Paar: absolute
    PM-Liquiditaet + harte Spread-Obergrenze. Rueckgabe "" = passiert,
    sonst der Reject-Grund fuer die Scan-Diagnostik.
    """
    try:
        dv = float(dollar_vol or 0.0)
    except (TypeError, ValueError):
        dv = 0.0
    if dv < float(min_dollar_vol):
        return "premarket_dollar_volume_filter"
    if spread_pct is None:
        return "premarket_missing_quote"
    if spread_pct > float(max_spread_pct):
        return "premarket_spread_guard"
    return ""


def _effective_scan_interval_min(scan_name: str, now_utc: Optional[datetime] = None) -> float:
    """Dynamischer Scan-Takt (AUDIT 2026-07-29, Punkt C).

    strategy_scan laeuft im Opening-Fenster (9:25–11:30 ET) alle 10 statt 60
    Minuten — Moves, die direkt am Open starten (RITM/NVST-Muster), werden
    ~50 Minuten frueher erfasst. Alle anderen Scanner unveraendert.
    """
    try:
        base = float((_scan_status.get(scan_name) or {}).get("interval_min", 0) or 0)
    except Exception:
        base = 0.0
    if base <= 0:
        base = 1.0
    if scan_name == "strategy_scan" and _opening_window_active(now_utc):
        return min(base, _STRATEGY_SCAN_OPENING_INTERVAL_MIN)
    return base


def _normalize_trade_horizon_value(value: Any) -> str:
    raw = str(value or "swing").strip().lower().replace("-", "_")
    aliases = {
        "swing": "swing",
        "swingtrading": "swing",
        "swing_trading": "swing",
        "daily": "swing",
        "intraday": "intraday",
        "daytrade": "intraday",
        "daytrading": "intraday",
        "day_trading": "intraday",
        "5m": "intraday",
        "both": "both",
        "beides": "both",
        "all": "both",
        "alle": "both",
    }
    return aliases.get(raw, raw if raw in _TRADE_HORIZON_OPTIONS else "swing")


def _scanner_uses_swing_horizon(scanner_name: str) -> bool:
    """Default scanner/mail horizon.

    The product default is swing trading. ORB remains intraday-only by design:
    opening-range edge is not a swing setup.
    """
    if scanner_name in _INTRADAY_ONLY_SCANNERS:
        return False
    return _normalize_trade_horizon_value(_DEFAULT_TRADE_HORIZON) in {"swing", "both"}


def _scanner_uses_intraday_horizon(scanner_name: str) -> bool:
    if scanner_name in _INTRADAY_ONLY_SCANNERS:
        return True
    return _normalize_trade_horizon_value(_DEFAULT_TRADE_HORIZON) in {"intraday", "both"}

