def _email_has_blocked_etf_content(subject: str, body_html: str) -> bool:
    """Hard guard: this app mails trade candidates, not ETF/ETP hedge watchlists."""
    content = f"{subject or ''} {body_html or ''}".upper()
    if any(marker in content for marker in (
        "INVERSE ETF",
        "INVERSE ETFS",
        "LEVERAGED ETF",
        "LEVERAGED ETFS",
        "3X SHORT",
        "2X SHORT",
    )):
        return True
    tokens = set(re.findall(r"\b[A-Z]{2,6}\b", content))
    if tokens & _EMAIL_BLOCKED_ETF_TICKERS:
        return True
    return any(_looks_like_non_stock_etp_symbol(token) for token in tokens)


def _alert_float(value: Any, default: Optional[float] = None) -> Optional[float]:
    try:
        val = float(value)
    except (TypeError, ValueError):
        return default
    if math.isnan(val) or math.isinf(val):
        return default
    return val


def _score_grade_for_value(score_value: Any) -> Tuple[str, str]:
    """Zentrale Score→Grade-Leiter: S≥88, A≥80, B≥65, C≥50, sonst D.

    AUDIT-Fix Label-Inflation: A = mail-würdig ab 80, konsistent mit dem
    _ALERT-Score-Gate (_ALERT_MIN_SCORE=80, _ALERT_TOP_GRADES enthält S/A).
    Die alte Leiter (S≥80/A≥60) vergab "A" ab 60 — ein A mit Score 62 war
    aber nie mailbar, weil das Mail-Gate Score≥80 verlangt. Jetzt identisch
    kalibriert mit der (vorher separaten) crypto_explosion-Leiter S≥88/A≥80.
    NICHT für BI-patterns (85/71/57/55), Cup&Handle (S ab 90) oder
    _bi_trade_grade_for_score — das sind eigene Scoring-Systeme.
    """
    score = _alert_float(score_value, 0) or 0
    if score >= 88:
        return "S", "Excellent"
    if score >= 80:
        return "A", "Stark"
    if score >= 65:
        return "B", "Solide"
    if score >= 50:
        return "C", "Schwach"
    return "D", "Uninteressant"


def _bi_trade_grade_for_score(score_value: Any) -> Tuple[str, str]:
    """BI needs a stricter action-grade than the generic scanner ladder.

    The raw BI grade can stay visible as setup interest, but the user-facing
    trade grade must answer "is this actionable enough?", not "is this worth
    a look?". Otherwise a 66-74 trade score looks like an A setup.
    """
    score = _alert_float(score_value, 0) or 0
    if score >= 90:
        return "S", "Elite Trade"
    if score >= 80:
        return "A", "Stark Trade"
    if score >= 70:
        return "B", "Kandidat"
    if score >= 60:
        return "C", "Watch"
    return "D", "Schwach"


def _bi_release_grade(trade_grade: Any, setup_grade: Any) -> str:
    """Return the weaker of BI setup quality and current trade quality."""
    grade_rank = {"D": 0, "C": 1, "B": 2, "A": 3, "A+": 4, "S": 5}
    normalized_trade = str(trade_grade or "").strip().upper()
    normalized_setup = str(setup_grade or "").strip().upper()
    valid_trade = normalized_trade if normalized_trade in grade_rank else ""
    valid_setup = normalized_setup if normalized_setup in grade_rank else ""
    if not valid_setup:
        return valid_trade or "D"
    if not valid_trade:
        return valid_setup
    return valid_trade if grade_rank[valid_trade] <= grade_rank[valid_setup] else valid_setup


def _alert_bool(value: Any, default: bool = False) -> bool:
    if isinstance(value, bool):
        return value
    if value is None:
        return default
    if isinstance(value, (int, float)):
        return value != 0
    text = str(value).strip().lower()
    if text in ("1", "true", "yes", "y", "ja"):
        return True
    if text in ("0", "false", "no", "n", "nein", "none", "null", ""):
        return False
    return default


def _extract_alert_grade(row: Dict[str, Any]) -> str:
    for key in ("BI_Grade", "Grade", "grade", "rating", "ExhGrade", "base_grade"):
        value = row.get(key)
        if value is not None and str(value).strip():
            return str(value).strip().upper()
    return ""


def _extract_alert_score(row: Dict[str, Any]) -> Any:
    nested = row.get("signal") if isinstance(row.get("signal"), dict) else {}
    pump_data = nested.get("pump_data") if isinstance(nested.get("pump_data"), dict) else {}
    keys = (
        "BI_Score", "Score", "score", "Alpha", "Setup_Score",
        "exhaustion_score", "ExhScore", "exh_score", "raw_score",
        "SellProb", "micro_score", "MicroScore",
    )
    for source in (row, nested, pump_data):
        for key in keys:
            value = source.get(key)
            if value not in (None, ""):
                return value
    return 0


def _extract_alert_rvol(row: Dict[str, Any]) -> Optional[float]:
    for key in ("RVOL", "rvol", "relative_volume"):
        if key in row:
            return _alert_float(row.get(key))
    return None


def _alert_min_rvol_for_row(scanner_name: str, row: Dict[str, Any]) -> float:
    """AUDIT S-1: Scanner-/Strategie-abhaengiger RVOL-Mindestwert fuers Mail-Gate.

    Default 0.7 (Pre-Breakout-Pfade wie bi_long). Breakout-Signalpfade
    (turtle sowie stock_strategy/strategy_scan-Rows mit "Breakout"/"Momentum"
    im Strategie-Namen) verlangen hart RVOL >= 1.5.
    """
    min_rvol = float(_ALERT_MIN_RVOL_BY_SCANNER.get(scanner_name, _ALERT_MIN_RVOL))
    if scanner_name in _ALERT_BREAKOUT_STRATEGY_SCANNERS:
        strategy = str(
            row.get("strategy") or row.get("Strategy") or row.get("Strategie") or ""
        ).lower()
        # AUDIT H-1: Pattern-Rows (z.B. Cup & Handle) trugen keinen Strategy-Key
        # und fielen auf den 0.7-Default zurueck. Token-Matching deshalb
        # zusaetzlich auf pattern/pattern_type, damit die Geschaeftsregel
        # (Breakout-Signal => Mail-Floor RVOL >= 1.5) nicht am Feldnamen haengt.
        pattern_text = str(
            row.get("pattern") or row.get("pattern_type") or row.get("Pattern") or ""
        ).lower()
        haystack = f"{strategy} {pattern_text}"
        if any(token in haystack for token in _ALERT_BREAKOUT_STRATEGY_TOKENS):
            min_rvol = max(min_rvol, _ALERT_BREAKOUT_MIN_RVOL)
    return min_rvol


def _extract_alert_ticker(row: Dict[str, Any]) -> str:
    for key in ("ticker", "Ticker", "symbol", "Symbol", "contract"):
        value = row.get(key)
        if value:
            return str(value).strip().upper()
    return ""


def _extract_alert_price(row: Dict[str, Any]) -> Any:
    for key in ("Preis", "Price", "price", "current", "current_price", "entry"):
        value = row.get(key)
        if value not in (None, ""):
            return value
    return 0


def _alert_get_any(row: Dict[str, Any], *keys: str, default: Any = None) -> Any:
    """Read scanner rows safely across old UI/cache column names."""
    for key in keys:
        if key in row and row.get(key) not in (None, ""):
            return row.get(key)
    return default


def _extract_new_listing_signal_fields(row: Dict[str, Any]) -> Dict[str, Any]:
    sig = row.get("signal", {}) if isinstance(row, dict) else {}
    nested = sig if isinstance(sig, dict) else {}
    pump_data = nested.get("pump_data", {}) if isinstance(nested.get("pump_data", {}), dict) else {}
    timing_text = str(nested.get("timing", sig if not isinstance(sig, dict) else row.get("timing", "")) or "")
    row_source = str(row.get("source", "") or "").lower()
    listing_source = str(
        nested.get("listing_source", pump_data.get("listing_source", row.get("listing_source", ""))) or ""
    ).lower()
    return {
        "grade": str(nested.get("grade", row.get("grade", "")) or "").strip().upper(),
        "timing": timing_text,
        "timing_quality": _alert_float(nested.get("timing_quality", row.get("timing_quality")), 0) or 0,
        "rr_effective": _alert_float(
            nested.get("rr_effective", nested.get("rr1", row.get("rr_effective", row.get("rr1")))),
            0,
        ) or 0,
        "safety_ok": _alert_bool(nested.get("safety_ok", row.get("safety_ok", False))),
        "tp1_missed": _alert_bool(nested.get("tp1_missed", row.get("tp1_missed", False))),
        "tp2_missed": _alert_bool(nested.get("tp2_missed", row.get("tp2_missed", False))),
        "confirmation_ok": _alert_bool(nested.get("confirmation_ok", row.get("confirmation_ok", False))),
        "continuation_risk": _alert_bool(nested.get("continuation_risk", row.get("continuation_risk", False))),
        "risk_pct": _alert_float(nested.get("risk_pct", row.get("risk_pct")), 999) or 999,
        "signal_quality": str(nested.get("signal_quality", row.get("signal_quality", "")) or "").lower(),
        "row_source": row_source,
        "listing_source": listing_source,
        "listing_trade_ok": _alert_bool(nested.get("listing_trade_ok", pump_data.get("listing_trade_ok", row.get("listing_trade_ok", False)))),
        "listing_age_hours": _alert_float(nested.get("listing_age_hours", pump_data.get("listing_age_hours", row.get("listing_age_hours")))),
        "trade_category": str(nested.get("trade_category", row.get("trade_category", "")) or ""),
        "micro_required": _alert_bool(nested.get("micro_required", row.get("micro_required", True)), True),
        "micro_trigger_ok": _alert_bool(
            nested.get("micro_trigger_ok", row.get("micro_trigger_ok", pump_data.get("micro_trigger_ok", False)))
        ),
    }


def _new_listing_rule_reasons(row: Dict[str, Any]) -> List[str]:
    fields = _extract_new_listing_signal_fields(row)
    reasons: List[str] = []
    timing_upper = fields["timing"].upper()
    row_source = fields["row_source"]
    listing_source = fields["listing_source"]
    if row_source and row_source not in ("signals", "new_listing"):
        reasons.append("not_active_short_signal")
    if not listing_source:
        reasons.append("listing_source_unknown")
    elif listing_source != "new_listing":
        reasons.append("not_new_listing_dump")
    if not fields["listing_trade_ok"]:
        reasons.append("listing_age_not_tradeable")
    if fields["timing_quality"] < 4 or "SHORT" not in timing_upper:
        reasons.append("not_active_short_timing")
    if not fields["safety_ok"]:
        reasons.append("safety_not_ok")
    if fields["tp1_missed"] or fields["tp2_missed"]:
        reasons.append("target_already_missed")
    if fields["rr_effective"] < _NEW_LISTING_MIN_ALERT_RR:
        reasons.append("rr_below_alert_threshold")
    if not fields["confirmation_ok"]:
        reasons.append("turn_not_confirmed")
    if fields["continuation_risk"]:
        reasons.append("pump_continuation_risk")
    if fields["micro_required"] and not fields["micro_trigger_ok"]:
        reasons.append("micro_trigger_missing")
    if fields["risk_pct"] > 35:
        reasons.append("risk_too_wide")
    if fields["signal_quality"] and fields["signal_quality"] != "tradeable":
        reasons.append("not_tradeable_signal_quality")
    return reasons


def _extract_early_mover_fields(row: Dict[str, Any]) -> Dict[str, Any]:
    setup = row.get("trade_setup", {}) if isinstance(row.get("trade_setup"), dict) else {}
    btc = row.get("btc_context", setup.get("btc_context", {}))
    btc_context = btc if isinstance(btc, dict) else {}
    risk_flags = row.get("risk_flags", setup.get("risk_flags", []))
    if not isinstance(risk_flags, list):
        risk_flags = [str(risk_flags)] if risk_flags else []
    distance_to_entry_r = _alert_float(row.get("distance_to_entry_r", setup.get("distance_to_entry_r")))
    btc_24h = _alert_float(btc_context.get("btc_24h"), 0) or 0
    btc_7d = _alert_float(btc_context.get("btc_7d"), 0) or 0
    btc_status = str(btc_context.get("data_status") or btc_context.get("status") or "ok").lower()
    btc_context_known = bool(
        btc_context
        and ("btc_24h" in btc_context or "btc_7d" in btc_context)
        and btc_status not in {"error", "unknown", "missing", "stale"}
    )
    alpha_24h = _alert_float(row.get("BtcRelative24h", btc_context.get("alpha_24h")), 0) or 0
    change24 = _alert_float(row.get("Change24h", row.get("change_24h", row.get("change24h"))), 0) or 0
    return {
        "direction": str(row.get("direction", setup.get("direction", "")) or "").upper(),
        "trade_action": str(row.get("trade_action", setup.get("trade_action", "")) or "").upper(),
        "entry_status": str(row.get("entry_status", setup.get("entry_status", "")) or "").upper(),
        "entry_quality": str(row.get("entry_quality", setup.get("entry_quality", "")) or "").upper(),
        "signal_quality": str(row.get("signal_quality", "") or "").lower(),
        "live_rr": _alert_float(row.get("live_rr_ratio", setup.get("live_rr")), 0) or 0,
        "distance_to_entry_r": distance_to_entry_r if distance_to_entry_r is not None else 999,
        "late_to_tp1": _alert_bool(row.get("late_to_tp1", setup.get("late_to_tp1", False))),
        "execution_trigger_ok": _alert_bool(row.get("execution_trigger_ok", False)),
        "partial_data": _alert_bool(row.get("partial_data", row.get("data_partial", False))),
        "data_warning": row.get("data_warning"),
        "btc_tailwind": bool(btc_context_known and _alert_bool(btc_context.get("tailwind"), False)),
        "btc_context_known": btc_context_known,
        "btc_24h": btc_24h,
        "btc_7d": btc_7d,
        "btc_hard_headwind": bool(btc_24h <= -3.0 or btc_7d <= -7.0),
        "change24": change24,
        "vol_mcap": _alert_float(row.get("VolMCapRatio", row.get("vol_mcap", row.get("Vol/MCap"))), 0) or 0,
        "alpha_24h": alpha_24h,
        "risk_flags": [str(flag).lower() for flag in risk_flags],
    }


def _early_mover_btc_allows_long(fields: Dict[str, Any]) -> bool:
    """BTC may be neutral/choppy, but not in a hard dump unless the setup is only watched."""
    if not fields.get("btc_context_known"):
        return False
    if fields.get("btc_hard_headwind"):
        return False
    if fields.get("btc_tailwind"):
        return True
    return (fields.get("alpha_24h") or 0) >= 1.0 and (fields.get("change24") or 0) >= 1.0


def _early_mover_mail_trigger_age_seconds(row: Dict[str, Any], now: Optional[float] = None) -> Optional[float]:
    """AUDIT Q-2: Alter des Trigger-/Scan-Zustands einer Crypto-Row fuer Mails.

    Bevorzugt den echten Trigger-Pruefzeitpunkt (trigger_checked_at bzw.
    intraday_trigger.checked_at). Fehlt ein Row-Zeitstempel, dient das vom
    Mail-Pfad gestempelte Scan-/Cache-Alter (_mail_scan_age_sec) als
    konservativer Proxy. None = Alter unbekannt (kein Gate).
    """
    now_value = float(now if now is not None else time.time())
    checked_at = _alert_float(row.get("trigger_checked_at"), None)
    if checked_at is None:
        trigger = row.get("intraday_trigger")
        if isinstance(trigger, dict):
            checked_at = _alert_float(trigger.get("checked_at"), None)
    if checked_at is not None and checked_at > 0:
        return max(0.0, now_value - checked_at)
    scan_age = _alert_float(row.get("_mail_scan_age_sec"), None)
    if scan_age is not None and scan_age >= 0:
        return scan_age
    return None


def _early_mover_alert_key(row: Dict[str, Any], ticker: Optional[str] = None) -> str:
    symbol = (ticker or _extract_alert_ticker(row)).upper()
    action = str(row.get("trade_action", row.get("entry_status", "long")) or "long").lower()
    action = re.sub(r"[^a-z0-9_]+", "_", action).strip("_") or "long"
    return f"early_movers_{symbol}_{action}" if symbol else ""


def _early_mover_long_rule_reasons(row: Dict[str, Any]) -> List[str]:
    """Only mail Early-Mover crypto rows that are close to an actual long decision."""
    fields = _extract_early_mover_fields(row)
    reasons: List[str] = []
    action = fields["trade_action"]
    risk_flags = set(fields["risk_flags"])
    row_horizon_value = row.get("_alert_horizon")
    row_horizon_explicit = row_horizon_value not in (None, "")
    horizon = _normalize_trade_horizon_value(row_horizon_value if row_horizon_explicit else _DEFAULT_TRADE_HORIZON)
    require_intraday_trigger = horizon in {"intraday", "both"} and (
        row_horizon_explicit or _scanner_uses_intraday_horizon("early_movers")
    )

    if fields["direction"] and fields["direction"] != "LONG":
        reasons.append("early_mover_not_long")
    # AUDIT Q-1: Nur LONG_TRIGGER ist mailbar. WAIT_FOR_RETEST ist ein
    # Watch-Zustand und gehoert in die separate Watch-Mail, nicht in die
    # JETZT-Trade-Mail.
    if action != "LONG_TRIGGER":
        reasons.append("early_mover_action_not_alertable")
    if fields["signal_quality"] == "no_chase" or "overheated_phase3" in risk_flags:
        reasons.append("early_mover_no_chase")
    if not _early_mover_btc_allows_long(fields):
        reasons.append("early_mover_btc_headwind")
    if fields["partial_data"] or fields["data_warning"] or "data_warning" in risk_flags:
        reasons.append("early_mover_data_warning")
    if fields["late_to_tp1"] or "tp1_already_reached" in risk_flags:
        reasons.append("early_mover_late_to_tp1")
    if "chased_from_entry" in risk_flags:
        reasons.append("early_mover_chased_from_entry")
    if "very_high_volume_turnover" in risk_flags:
        reasons.append("early_mover_blowoff_turnover")
    raw_turnover_churn = (
        fields["vol_mcap"] >= _EARLY_MOVER_TURNOVER_CHURN_BLOCK_PCT
        and fields["alpha_24h"] <= 0
        and fields["change24"] < 2.0
    )
    if raw_turnover_churn or risk_flags.intersection({"turnover_without_alpha", "extreme_turnover_churn"}):
        reasons.append("early_mover_turnover_without_alpha")
    if risk_flags.intersection({"thin_perp_liquidity", "thin_orderbook", "market_impact_risk", "no_perp_execution_market"}):
        reasons.append("early_mover_execution_liquidity_too_thin")
    if risk_flags.intersection({"weak_structural_targets", "duplicate_targets", "targets_too_close", "invalid_target_plan"}) or _early_mover_target_plan_issues(row):
        reasons.append("early_mover_weak_targets")
    if fields["live_rr"] < _EARLY_MOVER_MIN_ALERT_RR:
        reasons.append("early_mover_live_rr_below_threshold")
    if require_intraday_trigger and risk_flags.intersection({"no_market_entry", "no_intraday_execution_trigger", "micro_trigger_missing"}):
        reasons.append("early_mover_wait_entry_confirmation")
    # Swing mails do not require 5m. Intraday mode performs a fresh exchange
    # trigger check before sending and only then treats missing 5m as a blocker.
    if action == "WAIT_FOR_RETEST" and fields["distance_to_entry_r"] > _EARLY_MOVER_RETEST_MAX_DISTANCE_R:
        reasons.append("early_mover_retest_not_near_entry")
    return reasons


def _flatten_early_mover_rows(payload_or_rows: Any) -> List[Dict[str, Any]]:
    containers = payload_or_rows if isinstance(payload_or_rows, list) else [payload_or_rows]
    rows: List[Dict[str, Any]] = []
    for container in containers:
        if not isinstance(container, dict):
            continue
        coins = container.get("coins")
        if isinstance(coins, list):
            rows.extend([coin for coin in coins if isinstance(coin, dict)])
        elif _extract_alert_ticker(container):
            rows.append(container)
    return rows


def _format_alert_price(value: Any) -> str:
    price = _alert_float(value)
    if price is None:
        return "-"
    if abs(price) >= 100:
        return f"${price:,.2f}"
    if abs(price) >= 1:
        return f"${price:,.4f}".rstrip("0").rstrip(".")
    return f"${price:.8f}".rstrip("0").rstrip(".")


def _first_trade_level(row: Dict[str, Any], keys: Tuple[str, ...]) -> Optional[float]:
    """Read a positive trade level from top-level or nested scanner payloads."""
    sources: List[Dict[str, Any]] = [row]
    for nested_key in ("trade_setup", "setup", "signal"):
        nested = row.get(nested_key)
        if isinstance(nested, dict):
            sources.append(nested)
            pump_data = nested.get("pump_data")
            if isinstance(pump_data, dict):
                sources.append(pump_data)
    for source in sources:
        for key in keys:
            if key not in source:
                continue
            value = _alert_float(source.get(key))
            if value is not None and value > 0:
                return value
    return None


def _infer_alert_direction(row: Dict[str, Any]) -> str:
    setup = row.get("trade_setup", {}) if isinstance(row.get("trade_setup"), dict) else {}
    text = " ".join(str(value or "") for value in (
        row.get("Signal_Direction"),
        row.get("BI_Direction"),
        row.get("direction"),
        row.get("_direction"),
        row.get("side"),
        row.get("trade_action"),
        setup.get("direction"),
        setup.get("trade_action"),
    )).upper()
    if "SHORT" in text or text == "SELL":
        return "SHORT"
    if "LONG" in text or "BUY" in text:
        return "LONG"
    return ""


def _alert_trade_levels(row: Dict[str, Any]) -> Dict[str, Any]:
    """Normalize Entry/Stop/TP1/TP2 for every mail path.

    If a legacy scanner row has Entry/Stop but no targets, derive conservative
    R-multiple targets so alerts never show an idealized price without a plan.
    """
    return normalize_alert_trade_levels(
        row,
        price_fallback=_extract_alert_price(row),
        allow_estimated=True,
    )


def _alert_trade_plan_quality(levels: Dict[str, Any]) -> Dict[str, Any]:
    """Return alert-facing R:R quality without letting a far runner dominate."""
    return trade_plan_quality(
        levels,
        min_primary_tp_rr=_ALERT_MIN_PRIMARY_TP_RR,
        min_tp_gap_r=_ALERT_MIN_TP_GAP_R,
        min_tp_gap_pct=_ALERT_MIN_TP_GAP_PCT,
        runner_rr_cap=_ALERT_RUNNER_RR_CAP,
        max_runner_to_tp1_ratio=_ALERT_MAX_RUNNER_TO_TP1_RATIO,
    )


def _alert_move_warning_line(row: Dict[str, Any], levels: Dict[str, Any]) -> str:
    direction = str(levels.get("direction") or _alert_trade_direction(row) or "").upper()
    change = _alert_float(_alert_get_any(row, "change_pct", "Change_Pct", "Change%", "Change %", "change", default=None), None)
    rvol = _extract_alert_rvol(row)
    notes = []
    if direction == "LONG" and change is not None:
        if change >= 12:
            notes.append("Move stark erweitert: Retest/saubere Struktur statt FOMO.")
        elif change >= 8 and (rvol is None or rvol < 1.5):
            notes.append("Move schon weit, RVOL nicht stark genug: Retest bevorzugen.")
    elif direction == "SHORT" and change is not None:
        if change <= -12:
            notes.append("Drop schon weit: Short nur nach failed reclaim/weak bounce.")
        elif change <= -8:
            notes.append("Drop laeuft bereits: keine spaete Market-Order ohne Rejection.")
    # AUDIT 2026-07-28 (BELFB): Stop naeher als ~0.9xATR liegt im Tagesrauschen
    # — Stop-out-Wahrscheinlichkeit ist erhoeht und das gedruckte R:R schoent.
    atr = _alert_atr_value(row)
    entry = levels.get("entry")
    stop = levels.get("stop")
    if atr and isinstance(entry, (int, float)) and isinstance(stop, (int, float)):
        stop_atr_mult = abs(stop - entry) / atr
        if stop_atr_mult < 0.9:
            notes.append(
                f"Stop nur {stop_atr_mult:.1f}×ATR entfernt — liegt im Tagesrauschen (erhoehtes Stop-out-Risiko)."
            )
    if not notes:
        return ""
    safe = html.escape(" ".join(notes))
    return f'<br><span style="color:#b45309;font-size:11px">{safe}</span>'


def _humanize_alert_level_source(value: Any) -> str:
    """Short user-facing label for where mail levels came from."""
    raw = str(value or "").strip()
    if not raw:
        return ""
    text = raw.replace("_", " ").replace("-", " ")
    normalized = text.lower()
    specific = {
        "vrvp hvn low": "VRVP HVN-Unterkante (naechste Volumen-Zone)",
        "vrvp hvn high": "VRVP HVN-Oberkante (naechste Volumen-Zone)",
        "vrvp lvn lower edge": "VRVP LVN-Unterkante (Invalidation/Gap)",
        "vrvp lvn upper edge": "VRVP LVN-Oberkante (Rejection/Target)",
        "vrvp poc": "VRVP POC (meistgehandelter Preis)",
        "vrvp vah": "VRVP VAH (Value-Area-High)",
        "vrvp val": "VRVP VAL (Value-Area-Low)",
        "s1 invalidation": "S1-Invalidation",
        "r1 invalidation": "R1-Invalidation",
    }
    for key, label in specific.items():
        if key in normalized:
            return label[:90]
    replacements = {
        "vrvp": "VRVP",
        "poc": "POC",
        "vah": "VAH",
        "val": "VAL",
        "hvn": "HVN",
        "lvn": "LVN",
        "atr": "ATR",
        "vwap": "VWAP",
        "ema": "EMA",
        "ma20": "MA20",
        "ma50": "MA50",
        "tp1": "TP1",
        "tp2": "TP2",
    }
    for src, dst in replacements.items():
        text = re.sub(rf"\b{re.escape(src)}\b", dst, text, flags=re.IGNORECASE)
    if "measured move" in normalized:
        text = "Measured Move"
    elif "fallback" in normalized and "measured" not in normalized:
        text = text.replace("fallback", "Fallback")
    elif "range" in normalized:
        text = text.replace("range", "Range")
    elif "invalidation" in normalized:
        text = text.replace("invalidation", "Invalidation")
    return text[:90]


def _alert_level_source_line(row: Dict[str, Any]) -> str:
    setup = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}
    stop_source = setup.get("stop_source") or row.get("stop_source")
    tp1_source = setup.get("tp1_source") or row.get("tp1_source")
    tp2_source = setup.get("tp2_source") or row.get("tp2_source")
    parts = []
    if stop_source:
        parts.append(f"Stop: {_humanize_alert_level_source(stop_source)}")
    if tp1_source:
        parts.append(f"TP1: {_humanize_alert_level_source(tp1_source)}")
    if tp2_source:
        parts.append(f"TP2: {_humanize_alert_level_source(tp2_source)}")
    if not parts:
        return ""
    safe = html.escape(" | ".join(parts))
    return f'<br><span style="color:#64748b;font-size:11px">Level-Quelle: {safe}</span>'


def _biotech_binary_event_days(row: Dict[str, Any]) -> Optional[float]:
    """H-2 (Audit 10.06.2026): Tage bis zum naechsten binaeren Event oder None.

    Quellen in Prioritaetsreihenfolge: explizite days-Felder der Row, dann
    die Readout-Listen (Readout_Details[*].days_until_readout,
    BPIQ_Catalysts[*].days_until). Negative Werte (overdue) zaehlen nicht —
    das Event ist vorbei, kein bevorstehendes Gap-Risiko.
    """
    if not isinstance(row, dict):
        return None
    for key in ("days_until", "Days_Until", "Catalyst_Days", "catalyst_days", "days_until_readout"):
        val = _alert_float(row.get(key), None)
        if val is not None and val >= 0:
            return val
    best = None
    for list_key in ("Readout_Details", "readout_details", "BPIQ_Catalysts", "bpiq_catalysts"):
        items = row.get(list_key)
        if not isinstance(items, list):
            continue
        for item in items:
            if not isinstance(item, dict):
                continue
            for k in ("days_until_readout", "days_until"):
                val = _alert_float(item.get(k), None)
                if val is not None and val >= 0 and (best is None or val < best):
                    best = val
    return best


def _biotech_near_binary_event(row: Dict[str, Any]) -> bool:
    """H-2 (Audit 10.06.2026): True wenn die Row vor einem binaeren Event steht.

    Binaer = PDUFA/Readout <= T-3: Gap-Risiko ±40-80%, ein Stop schuetzt NICHT
    ueber ein Gap. Erkennung ueber near_binary_event-Feld/-Risk-Flag,
    Bio_Trade_Mode == NEAR_BINARY_EVENT (Event-Risk-Zweig) oder days <= 3.
    """
    if not isinstance(row, dict):
        return False
    if row.get("near_binary_event"):
        return True
    mode = str(row.get("Bio_Trade_Mode", row.get("bio_trade_mode", "")) or "").upper()
    if mode == "NEAR_BINARY_EVENT":
        return True
    flags_raw = row.get("Bio_Risk_Flags") or row.get("bio_risk_flags") or []
    flags = {
        str(flag).lower()
        for flag in (flags_raw if isinstance(flags_raw, list) else [flags_raw])
        if flag
    }
    if "near_binary_event" in flags:
        return True
    days = _biotech_binary_event_days(row)
    return days is not None and 0 <= days <= 3


def _biotech_binary_warning_html(row: Dict[str, Any]) -> str:
    """H-2: Rote Binary-Event-Warnzeile fuer Plan-HTML und Mail-Rows."""
    if not _biotech_near_binary_event(row):
        return ""
    days = _biotech_binary_event_days(row)
    days_txt = f"{int(days)}d" if isinstance(days, (int, float)) and days >= 0 else "&le;3d"
    return (
        '<br><span style="color:#dc2626;font-weight:bold;font-size:12px">'
        f'⚠ Binäres Event in {days_txt} — Stop schützt NICHT über ein Gap. '
        'Kein Neueinstieg, Run-up-Trades vor T-3 schließen.</span>'
    )


def _alert_atr_value(row: Dict[str, Any]) -> Optional[float]:
    """ATR fuer Abstands-Annotationen: erst der Bau-ATR aus dem Setup,
    dann Row-Keys (atr_14/ATR/atr). None => keine Annotation."""
    setup = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}
    for container in (setup, row):
        for key in ("atr", "atr_14", "ATR", "ATR14", "atr14"):
            value = _alert_float(container.get(key), None)
            if value is not None and value > 0:
                return value
    return None


def _atr_distance_annotations(row: Dict[str, Any], levels: Dict[str, Any]) -> Dict[str, str]:
    """Pro Level '+/-x.x% ≈ y.y×ATR' (Stop/TP1/TP2 vs. Entry).

    AUDIT 2026-07-28: ATR-Einheiten machen die Enge eines Levels ohne
    Taschenrechner lesbar — < 1xATR liegt im Tagesrauschen. Shorts zeigen
    TP negativ / Stop positiv (Vorzeichen = Richtung relativ zum Entry).
    """
    atr = _alert_atr_value(row)
    entry = levels.get("entry")
    if not atr or not isinstance(entry, (int, float)) or entry <= 0:
        return {}
    out: Dict[str, str] = {}
    for key in ("stop", "tp1", "tp2"):
        price = levels.get(key)
        if not isinstance(price, (int, float)) or price <= 0:
            continue
        pct = 100.0 * (price - entry) / entry
        mult = abs(price - entry) / atr
        out[key] = f"{pct:+.1f}% ≈ {mult:.1f}×ATR"
    return out


def _format_alert_plan_html(row: Dict[str, Any]) -> str:
    levels = _alert_trade_levels(row)
    if not levels.get("valid"):
        error_text = html.escape(", ".join(levels.get("errors", [])[:3]) or "invalid_trade_plan")
        return (
            '<span style="color:#dc2626;font-weight:bold">Kein gueltiger Trade-Plan</span>'
            f'<br><span style="color:#64748b;font-size:12px">{error_text}</span>'
        )
    entry = _format_alert_price(levels.get("entry"))
    stop = _format_alert_price(levels.get("stop"))
    tp1 = _format_alert_price(levels.get("tp1"))
    tp2 = _format_alert_price(levels.get("tp2"))
    rr = levels.get("rr")
    quality = _alert_trade_plan_quality(levels)
    effective_rr = quality.get("effective_rr")
    rr1 = quality.get("rr_tp1")
    rr2 = quality.get("rr_tp2")
    rr_text = ""
    if isinstance(effective_rr, (int, float)):
        rr_text = f'<br><span style="color:#64748b;font-size:12px">R:R eff {effective_rr:.2f}</span>'
        if isinstance(rr1, (int, float)) and isinstance(rr2, (int, float)):
            rr_text += f'<br><span style="color:#64748b;font-size:11px">TP1 {rr1:.1f}R / TP2 {rr2:.1f}R</span>'
    elif isinstance(rr, (int, float)):
        rr_text = f'<br><span style="color:#64748b;font-size:12px">R:R {rr:.2f}</span>'
    runner_text = (
        '<br><span style="color:#b45309;font-size:11px">TP2 ist Runner-Ziel; TP1/Stop bestimmen die echte Basis-Qualitaet.</span>'
        if quality.get("runner_skew") else ""
    )
    issue_text = ""
    issues = quality.get("issues") or []
    if issues:
        issue_label = html.escape(", ".join(str(item) for item in issues[:3]))
        issue_text = (
            '<br><span style="color:#dc2626;font-size:11px;font-weight:bold">'
            f'Trade-Plan blockiert: {issue_label}</span>'
        )
    level_source_text = _alert_level_source_line(row)
    atr_notes = _atr_distance_annotations(row, levels)
    stop_atr_text = (
        f' <span style="color:#64748b;font-size:11px">({atr_notes["stop"]})</span>'
        if "stop" in atr_notes else ""
    )
    _tp_atr_parts = [atr_notes.get("tp1"), atr_notes.get("tp2")]
    tp_atr_text = (
        f' <span style="color:#64748b;font-size:11px">'
        f'({" / ".join(p for p in _tp_atr_parts if p)})</span>'
        if any(_tp_atr_parts) else ""
    )
    move_warning = _alert_move_warning_line(row, levels)
    source_text = (
        '<br><span style="color:#b45309;font-size:11px">Level geschaetzt - native Scanner-Level fehlen/teilweise fehlen</span>'
        if levels.get("estimated") else ""
    )
    # AUDIT M-1: Level, die _enrich_biotech_alert_trade_levels via
    # _build_structured_trade_setup synthetisiert hat, sichtbar kennzeichnen.
    # AUDIT M-4 (10.06.2026): primaer auf das explizite Synthetic-Flag hoeren
    # (Trade_Setup_Synthetic auf der Row bzw. levels['synthetic'] aus
    # normalize_alert_trade_levels) — robuster als der String-Prefix-Check
    # auf Trade_Setup_Source, der nur als Fallback fuer Alt-Cache-Rows bleibt.
    setup_source = str(row.get("Trade_Setup_Source", row.get("trade_setup_source", "")) or "")
    is_synthetic = bool(
        row.get("Trade_Setup_Synthetic")
        or levels.get("synthetic")
        or setup_source.startswith("biotech_daily")
    )
    synthetic_text = (
        '<br><span style="color:#b45309;font-size:11px">Struktur-Level (ATR/Support) - nicht Scanner-nativ</span>'
        if is_synthetic else ""
    )
    # H-2 (Audit 10.06.2026): Binary-Event-Warnung gehoert in JEDE
    # Abonnenten-Flaeche, die den Plan rendert (Mail-Row + Trade-Plan-HTML).
    binary_warning_text = _biotech_binary_warning_html(row)
    return (
        f'<span>Entry <b>{entry}</b></span><br>'
        f'<span>Stop <b style="color:#dc2626">{stop}</b>{stop_atr_text}</span><br>'
        f'<span>TP1/TP2 <b style="color:#059669">{tp1} / {tp2}</b>{tp_atr_text}</span>'
        f'{rr_text}'
        f'{runner_text}'
        f'{issue_text}'
        f'{level_source_text}'
        f'{move_warning}'
        f'{source_text}'
        f'{synthetic_text}'
        f'{binary_warning_text}'
    )


def _format_alert_timing_label(value: Any, market_type: str = "stocks") -> str:
    """Human-readable timing label for alert tables.

    Scanner internals use machine states like SWING_SETUP. Emails should tell a
    trader what to do with the signal, not leak implementation labels.
    """
    raw = str(value or "").strip()
    key = raw.upper()
    labels = {
        "SWING_SETUP": "Swing-Setup aktiv",
        "TRADEABLE": "Tradeable",
        "JETZT_TRADEN": "Jetzt handelbar",
        "WAIT_FOR_RETEST": "Retest abwarten",
        "WAIT_FOR_TRIGGER": "Trigger abwarten",
        "WAIT_FOR_CONTINUATION": "Fortsetzung abwarten",
        "WATCH_ONLY": "Beobachten",
        "NO_TRADE": "Nicht handeln",
    }
    if key in labels:
        return labels[key]
    if not raw and market_type == "stocks":
        return "Swing-Setup aktiv"
    return raw.replace("_", " ").title()[:40]


def _alert_trade_plan_ok(
    row: Dict[str, Any],
    min_rr: float = _ALERT_MIN_LEVEL_RR,
    require_native_levels: bool = True,
) -> bool:
    levels = _alert_trade_levels(row)
    if not levels.get("valid"):
        return False
    if require_native_levels and levels.get("estimated"):
        return False
    quality = _alert_trade_plan_quality(levels)
    effective_rr = quality.get("effective_rr")
    if quality.get("tp1_ok") is False:
        return False
    if quality.get("issues"):
        return False
    return not isinstance(effective_rr, (int, float)) or effective_rr >= min_rr


def _alert_trade_health_reasons(row: Dict[str, Any], scanner_name: str) -> List[str]:
    """Final execution-quality gate for actionable mails.

    Scanner scores answer "interesting?". This guard answers "tradeable now?".
    """
    levels = _alert_trade_levels(row)
    health_row = dict(row)
    if levels.get("valid"):
        health_row.setdefault("entry", levels.get("entry"))
        health_row.setdefault("Entry", levels.get("entry"))
        health_row.setdefault("stop_loss", levels.get("stop"))
        health_row.setdefault("StopLoss", levels.get("stop"))
        health_row.setdefault("tp1", levels.get("tp1"))
        health_row.setdefault("TP1", levels.get("tp1"))
        health_row.setdefault("tp2", levels.get("tp2"))
        health_row.setdefault("TP2", levels.get("tp2"))
        health_row.setdefault("direction", levels.get("direction"))
    if "current_price" not in health_row:
        health_row["current_price"] = _extract_alert_price(health_row)

    health_scanner = {
        "early_movers": "crypto_early_movers",
        "crypto_strategy": "crypto_strategy",
        "new_listing": "new_listing",
    }.get(scanner_name, scanner_name)
    try:
        market_context = _get_market_context_snapshot()
    except Exception:
        market_context = None
    health = calculate_trade_health(health_row, scanner_name=health_scanner, market_context=market_context)
    decision = str(health.get("decision", "") or "").upper()
    reasons: List[str] = []
    # AUDIT Q-1: Der fruehere soft_swing_wait-Bypass (early_movers + swing
    # liess WAIT_FOR_RETEST/WAIT_FOR_TRIGGER/WAIT_FOR_CONTINUATION/WATCH_ONLY
    # weich durch) ist entfernt. WAIT-Decisions unterdruecken jetzt auch
    # Crypto-Swing-Mails; Watch-Kandidaten laufen in die separate Watch-Mail.

    if decision != "TRADEABLE":
        reasons.append(f"trade_health_{decision.lower() or 'not_tradeable'}")
    if int(health.get("health_score") or 0) < 80:
        reasons.append("trade_health_score_below_80")
    if str(health.get("chase_risk", "") or "").upper() in {"HIGH", "CRITICAL"}:
        reasons.append("trade_health_chase_risk")
    if str(health.get("fakeout_risk", "") or "").upper() in {"HIGH", "CRITICAL"}:
        reasons.append("trade_health_fakeout_risk")
    if str(health.get("liquidity_risk", "") or "").upper() == "CRITICAL":
        reasons.append("trade_health_liquidity_risk")
    return list(dict.fromkeys(reasons))


def _stock_alert_trade_score(row: Dict[str, Any], scanner_name: str) -> int:
    """Turn a stock scanner setup score into a real trade-now score.

    Stock scanners can be correct that a symbol is interesting while the current
    entry is still late, fading, or using weak levels. Generic stock-strategy
    alerts are swing setups, so 1m/5m candles must not be a hard gate there.
    Intraday scanners can still cap by their dedicated trigger quality.
    """
    raw_score = _alert_float(_extract_alert_score(row), 0) or 0
    levels = _alert_trade_levels(row)
    health_row = dict(row)
    if levels.get("valid"):
        health_row.setdefault("entry", levels.get("entry"))
        health_row.setdefault("Entry", levels.get("entry"))
        health_row.setdefault("stop_loss", levels.get("stop"))
        health_row.setdefault("StopLoss", levels.get("stop"))
        health_row.setdefault("tp1", levels.get("tp1"))
        health_row.setdefault("TP1", levels.get("tp1"))
        health_row.setdefault("tp2", levels.get("tp2"))
        health_row.setdefault("TP2", levels.get("tp2"))
        health_row.setdefault("direction", levels.get("direction"))
    health_row.setdefault("current_price", _extract_alert_price(health_row))

    try:
        market_context = _get_market_context_snapshot()
    except Exception:
        market_context = None
    health = calculate_trade_health(health_row, scanner_name=scanner_name, market_context=market_context)
    health_score = int(_alert_float(health.get("health_score"), 0) or 0)
    entry_score = int(_alert_float(health.get("entry_quality_score"), 0) or 0)
    fakeout_score = int(_alert_float(health.get("fakeout_risk_score"), 0) or 0)
    liquidity_score = int(_alert_float(health.get("liquidity_score"), 0) or 0)
    weakest_pillar = min([score for score in (entry_score, fakeout_score, liquidity_score) if score is not None] or [0])

    score = min(
        raw_score * 0.42 + health_score * 0.38 + weakest_pillar * 0.20,
        weakest_pillar + 18,
    )

    decision = str(health.get("decision") or "").upper()
    if decision == "WAIT_FOR_CONTINUATION":
        score = min(score, 76)
    elif decision in {"WAIT_FOR_RETEST", "WAIT_FOR_TRIGGER", "WATCH_ONLY"}:
        score = min(score, 69)
    elif decision and decision != "TRADEABLE":
        score = min(score, 45)

    if not levels.get("valid") or levels.get("estimated"):
        score = min(score, 45)
    elif levels.get("valid"):
        plan_quality = _alert_trade_plan_quality(levels)
        effective_rr = plan_quality.get("effective_rr")
        if plan_quality.get("issues"):
            score = min(score, 45)
        elif plan_quality.get("tp1_ok") is False:
            score = min(score, 45)
        elif isinstance(effective_rr, (int, float)) and effective_rr < 1.5:
            score = min(score, 69)

    swing_stock_mode = scanner_name in _STOCK_SWING_ALERT_SCANNERS and _scanner_uses_swing_horizon(scanner_name)
    short_context = _stock_alert_is_short_context(scanner_name, row)

    if swing_stock_mode:
        swing_reasons = _stock_swing_short_rule_reasons(row) if short_context else _stock_swing_rule_reasons(row)
        if swing_reasons:
            no_chase = {
                "swing_hard_extended_no_chase",
                "swing_short_drop_too_extended_no_chase",
                # 2026-07-31 (BHC): 5-Tage-Move >= 7 ATR = erschoepft, hartes Cap.
                "swing_multi_day_exhausted_no_chase",
            }
            score = min(score, 45 if any(reason in no_chase for reason in swing_reasons) else 69)
    elif scanner_name in _LONG_ENTRY_ALERT_SCANNERS:
        long_reasons = _long_entry_rule_reasons(row)
        if long_reasons:
            score = min(score, 69 if any(reason.endswith("wait_retest") for reason in long_reasons) else 55)
    if not swing_stock_mode and scanner_name in ("bear", "bi_short"):
        short_reasons = _bear_short_rule_reasons(row)
        if short_reasons:
            if "drop_too_extended_no_chase" in short_reasons:
                score = min(score, 45)
            else:
                score = min(score, 62)

    return int(round(max(0, min(100, score))))


def _median_float(values: List[Any], default: float = 0.0) -> float:
    nums = sorted([v for v in (_alert_float(value) for value in values) if v is not None])
    if not nums:
        return default
    mid = len(nums) // 2
    if len(nums) % 2:
        return nums[mid]
    return (nums[mid - 1] + nums[mid]) / 2


def _normalize_crypto_exchange(value: Any) -> str:
    exchange = str(value or "").strip().lower().replace(" ", "_")
    if exchange in ("mexc", "bitget", "binance", "crypto_com"):
        return exchange
    if exchange == "crypto.com":
        return "crypto_com"
    return exchange


def _compact_usd(value: Any) -> str:
    amount = _alert_float(value, 0) or 0
    if amount >= 1_000_000_000:
        return f"${amount / 1_000_000_000:.1f}B"
    if amount >= 1_000_000:
        return f"${amount / 1_000_000:.1f}M"
    if amount >= 1_000:
        return f"${amount / 1_000:.0f}k"
    return f"${amount:.0f}"


def _book_liquidity_metrics(book: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    bids_raw = (book or {}).get("bids") or []
    asks_raw = (book or {}).get("asks") or []

    def _side(raw_side: Any) -> List[Tuple[float, float]]:
        parsed: List[Tuple[float, float]] = []
        for level in raw_side if isinstance(raw_side, list) else []:
            if not isinstance(level, (list, tuple)) or len(level) < 2:
                continue
            price = _alert_float(level[0])
            qty = _alert_float(level[1])
            if price and price > 0 and qty and qty > 0:
                parsed.append((price, qty))
        return parsed

    bids = sorted(_side(bids_raw), key=lambda x: x[0], reverse=True)
    asks = sorted(_side(asks_raw), key=lambda x: x[0])
    if not bids or not asks:
        return {"ok": False, "reason": "orderbook_empty"}

    bid = bids[0][0]
    ask = asks[0][0]
    mid = (bid + ask) / 2
    if mid <= 0 or ask <= bid:
        return {"ok": False, "reason": "orderbook_bad_prices"}

    def _depth(side: List[Tuple[float, float]], bps: float, is_ask: bool) -> float:
        if is_ask:
            cutoff = mid * (1 + bps / 10000)
            return sum(price * qty for price, qty in side if price <= cutoff)
        cutoff = mid * (1 - bps / 10000)
        return sum(price * qty for price, qty in side if price >= cutoff)

    bid_depth_10 = _depth(bids, 10, False)
    ask_depth_10 = _depth(asks, 10, True)
    bid_depth_25 = _depth(bids, 25, False)
    ask_depth_25 = _depth(asks, 25, True)
    bid_depth_50 = _depth(bids, 50, False)
    ask_depth_50 = _depth(asks, 50, True)
    total_bid_depth = sum(price * qty for price, qty in bids)
    total_ask_depth = sum(price * qty for price, qty in asks)
    return {
        "ok": True,
        "bid": round(bid, 12),
        "ask": round(ask, 12),
        "mid": round(mid, 12),
        "spread_bps": round((ask - bid) / mid * 10000, 2),
        "depth_10bps_bid_usd": round(bid_depth_10, 2),
        "depth_10bps_ask_usd": round(ask_depth_10, 2),
        "depth_10bps_min_usd": round(min(bid_depth_10, ask_depth_10), 2),
        "depth_25bps_bid_usd": round(bid_depth_25, 2),
        "depth_25bps_ask_usd": round(ask_depth_25, 2),
        "depth_25bps_min_usd": round(min(bid_depth_25, ask_depth_25), 2),
        "depth_50bps_bid_usd": round(bid_depth_50, 2),
        "depth_50bps_ask_usd": round(ask_depth_50, 2),
        "depth_50bps_min_usd": round(min(bid_depth_50, ask_depth_50), 2),
        "top_book_bid_usd": round(total_bid_depth, 2),
        "top_book_ask_usd": round(total_ask_depth, 2),
        "top_book_min_usd": round(min(total_bid_depth, total_ask_depth), 2),
    }


def _early_mover_static_liquidity(entry: Dict[str, Any]) -> Dict[str, Any]:
    """Execution liquidity, not CoinGecko popularity.

    CoinGecko volume is aggregate market volume. For a live signal we need the
    actual perp/trigger venue to have enough turnover; otherwise small orders
    can paint the chart and invalidate the scanner edge.
    """
    has_perp = bool(entry.get("HasPerp"))
    perp_volume = _alert_float(entry.get("PerpVolume24h"), 0) or 0
    spot_volume = _alert_float(entry.get("Vol24h") or entry.get("volume") or entry.get("dollar_volume"), 0) or 0
    flags: List[str] = []
    reasons: List[str] = []
    score_penalty = 0
    hard_block = False

    if not has_perp:
        flags.append("no_perp_execution_market")
        reasons.append("kein Perp/Trigger-Markt - nur Watchlist")
        score_penalty += 25
        hard_block = True
    elif perp_volume < _EARLY_MOVER_MIN_PERP_VOLUME_USD:
        flags.append("thin_perp_liquidity")
        reasons.append(f"Perp-Volumen duenn: {_compact_usd(perp_volume)}/24h")
        score_penalty += 25
        hard_block = True
    elif perp_volume < _EARLY_MOVER_WARN_PERP_VOLUME_USD:
        flags.append("perp_liquidity_watch")
        reasons.append(f"Perp-Volumen nur mittel: {_compact_usd(perp_volume)}/24h")
        score_penalty += 8

    if spot_volume and spot_volume < 1_000_000:
        flags.append("thin_spot_liquidity")
        reasons.append(f"Gesamtvolumen duenn: {_compact_usd(spot_volume)}/24h")
        score_penalty += 10

    return {
        "hard_block": hard_block,
        "score_penalty": score_penalty,
        "flags": flags,
        "reasons": reasons,
        "perp_volume_24h": round(perp_volume, 2),
        "spot_volume_24h": round(spot_volume, 2),
    }


def _early_mover_orderbook_liquidity(contract: str, exchange: str) -> Dict[str, Any]:
    if not HAS_NEW_LISTING_SCANNER:
        return {"ok": False, "reason": "orderbook_module_missing", "reasons": ["orderbook_module_missing"]}
    try:
        book = fetch_orderbook_for(str(contract), exchange, depth=50)
    except Exception as exc:
        return {"ok": False, "reason": "orderbook_fetch_failed", "detail": str(exc)[:120], "reasons": ["orderbook_fetch_failed"]}

    metrics = _book_liquidity_metrics(book)
    if not metrics.get("ok"):
        metrics["reasons"] = [metrics.get("reason", "orderbook_unavailable")]
        return metrics

    reasons = []
    if metrics["spread_bps"] > _EARLY_MOVER_MAX_SPREAD_BPS:
        reasons.append("spread_too_wide")
    if metrics["depth_10bps_min_usd"] < _EARLY_MOVER_MIN_DEPTH_10BPS_USD:
        reasons.append("thin_book_10bps")
    if metrics["depth_25bps_min_usd"] < _EARLY_MOVER_MIN_DEPTH_25BPS_USD:
        reasons.append("thin_book_25bps")
    if metrics["depth_50bps_min_usd"] < _EARLY_MOVER_MIN_DEPTH_50BPS_USD:
        reasons.append("thin_book_50bps")

    metrics.update({
        "ok": not reasons,
        "reason": "ok" if not reasons else "thin_orderbook_market_impact",
        "reasons": reasons,
        "thresholds": {
            "max_spread_bps": _EARLY_MOVER_MAX_SPREAD_BPS,
            "min_depth_10bps_usd": _EARLY_MOVER_MIN_DEPTH_10BPS_USD,
            "min_depth_25bps_usd": _EARLY_MOVER_MIN_DEPTH_25BPS_USD,
            "min_depth_50bps_usd": _EARLY_MOVER_MIN_DEPTH_50BPS_USD,
        },
    })
    return metrics


def _early_mover_trigger_profile(row: Dict[str, Any]) -> Dict[str, Any]:
    setup = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}
    btc = row.get("btc_context", setup.get("btc_context", {}))
    btc_context = btc if isinstance(btc, dict) else {}
    action = str(row.get("trade_action", row.get("entry_status", "")) or "").upper()
    phase = _alert_float(row.get("phase", row.get("Phase")), 0) or 0
    change24 = _alert_float(row.get("Change24h", row.get("change_24h", row.get("change24h"))), 0) or 0
    vol_mcap = _alert_float(row.get("VolMCapRatio", row.get("vol_mcap", row.get("Vol/MCap"))), 0) or 0
    alpha_24h = _alert_float(row.get("BtcRelative24h", btc_context.get("alpha_24h")), 0) or 0
    distance_value = _alert_float(row.get("distance_to_entry_r"))
    distance_r = distance_value if distance_value is not None else 999
    risk_flags = [str(flag).lower() for flag in (row.get("risk_flags") or []) if flag is not None]
    fast_coin = bool(abs(change24) >= 8 or vol_mcap >= 35 or int(phase) == 2 or "breakout" in " ".join(risk_flags))
    near_retest = bool(action == "WAIT_FOR_RETEST" or distance_r <= _EARLY_MOVER_RETEST_MAX_DISTANCE_R)
    turnover_without_alpha = bool(
        vol_mcap >= _EARLY_MOVER_TURNOVER_CHURN_BLOCK_PCT
        and alpha_24h <= 0
        and change24 < 2.0
    )
    return {
        "action": action,
        "fast_coin": fast_coin,
        "near_retest": near_retest,
        "change24": change24,
        "vol_mcap": vol_mcap,
        "alpha_24h": alpha_24h,
        "distance_to_entry_r": distance_r,
        "requires_5m_confirmation": turnover_without_alpha or "turnover_without_alpha" in risk_flags,
    }


def _timeframe_seconds(timeframe: str) -> Optional[int]:
    tf = str(timeframe or "").strip().lower()
    return {
        "1m": 60,
        "3m": 180,
        "5m": 300,
        "15m": 900,
        "30m": 1800,
        "1h": 3600,
        "4h": 14400,
        "1d": 86400,
        "1w": 604800,
    }.get(tf)


def _candle_epoch_seconds(bar: Dict[str, Any]) -> Optional[float]:
    if not isinstance(bar, dict):
        return None
    for key in ("timestamp", "open_time", "openTime", "time", "t", "ts", "start"):
        value = bar.get(key)
        if value in (None, ""):
            continue
        try:
            if isinstance(value, str) and not value.replace(".", "", 1).isdigit():
                return datetime.fromisoformat(value.replace("Z", "+00:00")).timestamp()
            ts = float(value)
        except Exception:
            continue
        if ts <= 0:
            continue
        if ts > 1_000_000_000_000_000:
            ts = ts / 1_000_000_000
        elif ts > 10_000_000_000:
            ts = ts / 1000
        return ts
    return None


def _completed_candles_only(
    bars: List[Dict[str, Any]],
    timeframe: str,
    now_ts: Optional[float] = None,
) -> List[Dict[str, Any]]:
    """Use only closed candles for execution checks.

    Live 5m bars can start bullish/bearish and then completely reverse before close.
    Trigger, no-chase and alert gates therefore must ignore the still-forming bar.
    """
    if not bars:
        return []
    ordered = list(bars)
    if len(ordered) >= 2:
        timestamped = [
            (_candle_epoch_seconds(bar), index, bar)
            for index, bar in enumerate(ordered)
        ]
        if all(timestamp is not None for timestamp, _, _ in timestamped):
            ordered = [
                bar
                for _, _, bar in sorted(
                    timestamped,
                    key=lambda item: (item[0], item[1]),
                )
            ]
    seconds = _timeframe_seconds(timeframe)
    if not seconds:
        return ordered
    now_value = float(now_ts if now_ts is not None else time.time())
    latest_ts = _candle_epoch_seconds(ordered[-1])
    if latest_ts is not None and latest_ts + seconds > now_value:
        return ordered[:-1]
    return ordered


def _crypto_candle_freshness(
    bars: List[Dict[str, Any]],
    timeframe: str,
    now_ts: Optional[float] = None,
    max_age_bars: float = 2.0,
) -> Dict[str, Any]:
    """Describe whether the newest completed execution candle is still usable.

    Exchange timestamps are candle-open times. A trigger becomes stale once the
    newest closed candle is more than two bars old. Candles without timestamps
    cannot prove freshness and therefore fail closed.
    """
    seconds = _timeframe_seconds(timeframe)
    if not bars or not seconds:
        return {"known": False, "fresh": False, "age_seconds": None, "closed_at": None}
    last_ts = _candle_epoch_seconds(bars[-1])
    if last_ts is None:
        return {"known": False, "fresh": False, "age_seconds": None, "closed_at": None}
    now_value = float(now_ts if now_ts is not None else time.time())
    closed_at = last_ts + seconds
    age_seconds = max(0.0, now_value - closed_at)
    return {
        "known": True,
        "fresh": bool(closed_at <= now_value + 2 and age_seconds <= seconds * max_age_bars),
        "age_seconds": int(round(age_seconds)),
        "closed_at": int(round(closed_at)),
    }


def _crypto_contract_price_multiplier(symbol: Any, contract: Any) -> int:
    """Return the explicit exchange contract unit multiplier (e.g. 1000PEPE)."""
    base_symbol = str(symbol or "").upper().strip()
    contract_text = str(contract or "").upper().replace("-", "").replace("_", "").replace("/", "")
    for quote in ("USDT", "USDC", "USD"):
        if contract_text.endswith(quote):
            contract_text = contract_text[:-len(quote)]
            break
    if not base_symbol or not contract_text:
        return 1
    for multiplier in (1_000_000, 100_000, 10_000, 1_000, 100):
        if contract_text == f"{multiplier}{base_symbol}":
            return multiplier
    return 1


def _perp_reference_price(perp_info: Any) -> Optional[float]:
    """Return the live price of the venue selected for the aggregate perp row."""
    if not isinstance(perp_info, dict):
        return None
    direct = _alert_float(perp_info.get("best_last_price"))
    if direct is not None and direct > 0:
        return direct

    venue = str(
        perp_info.get("best_chart_exchange")
        or perp_info.get("best_exchange")
        or ""
    ).lower()
    venue = venue.replace("-", "_").replace(" ", "_")
    selected = perp_info.get(venue)
    if isinstance(selected, dict):
        value = _alert_float(selected.get("last_price"))
        if value is not None and value > 0:
            return value
    return None


def _select_price_validated_perp(
    symbol: Any,
    spot_price: Any,
    perp_data: Any,
    max_gap_pct: float = 12.0,
) -> Tuple[Optional[str], Dict[str, Any], Optional[float]]:
    """Match spot and perp identities only when their scaled prices agree.

    Exchange symbols such as ``1000PEPE`` cannot safely be associated by name
    alone.  The selected contract must also trade close to ``spot * unit``.
    """
    base = str(symbol or "").upper().strip()
    spot = _alert_float(spot_price)
    if not base or spot is None or spot <= 0 or not isinstance(perp_data, dict):
        return None, {}, None

    matches: List[Tuple[float, float, str, Dict[str, Any]]] = []
    for multiplier in (1, 100, 1_000, 10_000, 100_000, 1_000_000):
        key = base if multiplier == 1 else f"{multiplier}{base}"
        info = perp_data.get(key)
        if not isinstance(info, dict) or not info:
            continue
        contract = info.get("best_contract_symbol") or key
        contract_multiplier = _crypto_contract_price_multiplier(base, contract)
        if multiplier != 1 and contract_multiplier == 1:
            contract_multiplier = multiplier
        expected = spot * contract_multiplier
        actual = _perp_reference_price(info)
        if actual is None or expected <= 0:
            continue
        gap_pct = abs(actual - expected) / expected * 100.0
        if gap_pct > max_gap_pct:
            continue
        liquidity = _alert_float(info.get("volume24_usdt"), 0) or 0
        matches.append((gap_pct, -liquidity, key, info))

    if not matches:
        return None, {}, None
    gap_pct, _negative_liquidity, key, info = min(matches, key=lambda item: (item[0], item[1]))
    return key, info, round(gap_pct, 4)


def _early_mover_execution_threshold(matched: List[str], profile: Dict[str, Any]) -> int:
    """Adaptive 5m trigger threshold by setup type.

    A clean retest/hold should not need the same score as a raw momentum breakout.
    The hard filters above still block chase candles, bad R-distance and thin books.
    """
    if not matched:
        return 999
    thresholds = []
    if "retest_hold" in matched:
        thresholds.append(64)
    if "higher_low_vwap_hold" in matched:
        thresholds.append(64)
    if "vwap_reclaim" in matched:
        thresholds.append(70)
    if "breakout" in matched:
        thresholds.append(72)
    if "trend_continuation" in matched:
        thresholds.append(70)
    threshold = min(thresholds) if thresholds else 76
    if profile.get("fast_coin") and (profile.get("alpha_24h") or 0) >= 2:
        threshold -= 3
    if profile.get("requires_5m_confirmation"):
        threshold = max(threshold, 70)
    return max(62, min(78, int(threshold)))


def _score_early_mover_trigger_bars(row: Dict[str, Any], bars: List[Dict[str, Any]], timeframe: str, profile: Dict[str, Any]) -> Dict[str, Any]:
    timeframe = str(timeframe or "").lower()
    if timeframe != "5m":
        return {
            "ok": False,
            "reason": "execution_timeframe_disabled_use_5m",
            "timeframe": timeframe,
            "execution_score": 0,
        }

    min_bars = 12
    original_bar_count = len(bars or [])
    bars = _completed_candles_only(bars or [], timeframe)
    dropped_open_bar = bool(original_bar_count and len(bars) < original_bar_count)
    if not bars or len(bars) < min_bars:
        return {
            "ok": False,
            "reason": f"not_enough_{timeframe}_candles",
            "timeframe": timeframe,
            "execution_score": 0,
            "dropped_open_candle": dropped_open_bar,
        }

    try:
        clean = []
        for bar in bars:
            open_ = float(bar["open"])
            high = float(bar["high"])
            low = float(bar["low"])
            close = float(bar["close"])
            volume = float(bar.get("volume", 0) or 0)
            if open_ > 0 and close > 0 and high > low:
                cleaned_bar = {"open": open_, "high": high, "low": low, "close": close, "volume": max(volume, 0)}
                timestamp = _candle_epoch_seconds(bar)
                if timestamp is not None:
                    cleaned_bar["timestamp"] = timestamp
                clean.append(cleaned_bar)
        if len(clean) < min_bars:
            return {"ok": False, "reason": f"bad_{timeframe}_candles", "timeframe": timeframe, "execution_score": 0}

        freshness = _crypto_candle_freshness(clean, timeframe)
        if not freshness.get("known"):
            return {
                "ok": False,
                "reason": f"missing_{timeframe}_execution_timestamp",
                "timeframe": timeframe,
                "execution_score": 0,
                "execution_data_age_seconds": None,
                "dropped_open_candle": dropped_open_bar,
            }
        if freshness.get("known") and not freshness.get("fresh"):
            return {
                "ok": False,
                "reason": f"stale_{timeframe}_execution_candle",
                "timeframe": timeframe,
                "execution_score": 0,
                "execution_data_age_seconds": freshness.get("age_seconds"),
                "last_candle_closed_at": freshness.get("closed_at"),
                "dropped_open_candle": dropped_open_bar,
            }

        recent_len = 24
        window_len = 8
        recent = clean[-recent_len:] if len(clean) >= recent_len else clean
        last = clean[-1]
        prev = clean[:-1]
        prev_window = prev[-window_len:] if len(prev) >= window_len else prev
        last_open = last["open"]
        last_high = last["high"]
        last_low = last["low"]
        last_close = last["close"]
        last_vol = last["volume"]

        scanner_price = _alert_float(row.get("Price") or row.get("current_price") or row.get("price"))
        price_basis_diff_pct = (
            abs(last_close - scanner_price) / scanner_price * 100
            if scanner_price is not None and scanner_price > 0 else 0.0
        )
        if scanner_price and price_basis_diff_pct > 2.0:
            return {
                "ok": False,
                "reason": "execution_price_basis_mismatch",
                "timeframe": timeframe,
                "execution_score": 0,
                "scanner_price": round(scanner_price, 10),
                "last_close": round(last_close, 10),
                "price_basis_diff_pct": round(price_basis_diff_pct, 2),
                "execution_data_age_seconds": freshness.get("age_seconds"),
            }

        typical_value = 0.0
        volume_sum = 0.0
        for bar in recent:
            typical = (bar["high"] + bar["low"] + bar["close"]) / 3
            typical_value += typical * bar["volume"]
            volume_sum += bar["volume"]
        vwap = typical_value / volume_sum if volume_sum > 0 else _median_float([b.get("close") for b in recent], last_close)
        median_vol = historical_volume_baseline(
            (b.get("volume") for b in prev),
            lookback=30,
            method="median",
            minimum_periods=8,
        )
        if median_vol is None or median_vol <= 0 or last_vol <= 0:
            return {
                "ok": False,
                "reason": "missing_5m_volume_baseline",
                "timeframe": timeframe,
                "execution_score": 0,
                "execution_data_age_seconds": freshness.get("age_seconds"),
            }
        vol_ratio = last_vol / median_vol
        prev_high = max(bar["high"] for bar in prev_window)
        prev_low = min(bar["low"] for bar in prev_window)
        prev_close = prev[-1]["close"] if prev else last_close
        close_pos = (last_close - last_low) / max(last_high - last_low, 1e-9)
        candle_change_pct = ((last_close - last_open) / last_open * 100) if last_open else 0
        range_pct = ((last_high - last_low) / last_close * 100) if last_close else 0

        setup_obj = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}
        tp1 = _alert_float(row.get("tp1") or setup_obj.get("tp1"))
        entry = _alert_float(row.get("entry") or setup_obj.get("entry"))
        stop = _alert_float(row.get("stop_loss") or row.get("stop") or setup_obj.get("stop_loss") or setup_obj.get("stop"))
        risk = (entry - stop) if entry is not None and stop is not None else None
        if risk is not None and risk <= 0:
            return {
                "ok": False,
                "reason": "invalid_long_stop_geometry",
                "timeframe": timeframe,
                "execution_score": 0,
            }
        distance_r = ((last_close - entry) / risk) if entry is not None and risk and risk > 0 else None

        if stop is not None and last_close <= stop:
            return {
                "ok": False,
                "reason": "long_stop_breached_intraday",
                "timeframe": timeframe,
                "execution_score": 0,
                "last_close": round(last_close, 10),
                "stop": round(stop, 10),
                "execution_data_age_seconds": freshness.get("age_seconds"),
            }

        if tp1 is not None and last_close >= tp1:
            return {
                "ok": False,
                "reason": "tp1_already_reached_intraday",
                "timeframe": timeframe,
                "execution_score": 0,
                "last_close": round(last_close, 10),
            }

        breakout_vol = 1.25
        hold_vol = 1.10
        breakout_buffer = 1.0015
        max_safe_candle = 5.0
        max_safe_range = 7.0
        retest_reclaim = 1.0

        breakout = last_close > prev_high * breakout_buffer and vol_ratio >= breakout_vol and close_pos >= 0.60
        vwap_reclaim = prev_close < vwap and last_close > vwap and vol_ratio >= breakout_vol and close_pos >= 0.58
        hl_hold = last_close > vwap and last_low > prev_low and last_close > last_open and vol_ratio >= hold_vol and close_pos >= 0.55
        retest_hold = bool(
            entry is not None
            and risk
            and -0.10 <= (distance_r if distance_r is not None else 999) <= 0.35
            and last_low <= entry * 1.004
            and last_close >= entry * retest_reclaim
            and last_close > last_open
            and last_close >= vwap * 0.997
            and close_pos >= 0.55
            and vol_ratio >= hold_vol
        )
        continuation = bool(
            profile.get("fast_coin")
            and last_close > prev_close
            and last_close > vwap
            and close_pos >= 0.62
            and vol_ratio >= breakout_vol
            and (distance_r is None or -0.10 <= distance_r <= 0.55)
        )

        matched = []
        score = 0.0
        if retest_hold:
            matched.append("retest_hold")
            score += 34
        if breakout:
            matched.append("breakout")
            score += 34
        if vwap_reclaim:
            matched.append("vwap_reclaim")
            score += 30
        if hl_hold:
            matched.append("higher_low_vwap_hold")
            score += 28
        if continuation and not matched:
            matched.append("trend_continuation")
            score += 25

        if vol_ratio >= 2.2:
            score += 20
        elif vol_ratio >= 1.6:
            score += 16
        elif vol_ratio >= hold_vol:
            score += 10

        if close_pos >= 0.78:
            score += 14
        elif close_pos >= 0.62:
            score += 10
        elif close_pos < 0.45:
            score -= 15

        if distance_r is not None:
            if -0.10 <= distance_r <= 0.25:
                score += 18
            elif 0.25 < distance_r <= 0.50:
                score += 10
            elif 0.50 < distance_r <= 0.75:
                score += 2
            else:
                score -= 28
        elif matched:
            score += 8

        chase_candle = candle_change_pct >= max_safe_candle and close_pos >= 0.86 and range_pct >= max_safe_range
        if chase_candle and (distance_r is None or distance_r > 0.45):
            score -= 35
            matched = [m for m in matched if m != "breakout"]
        elif candle_change_pct <= max_safe_candle:
            score += 6

        last_12 = clean[-12:] if len(clean) >= 12 else clean
        prior_24 = clean[-36:-12] if len(clean) >= 36 else clean[:-12]
        recent_high = max(bar["high"] for bar in last_12)
        recent_low = min(bar["low"] for bar in last_12)
        recent_range_pct = ((recent_high - recent_low) / last_close * 100) if last_close else 0
        recent_open = last_12[0]["open"] if last_12 else last_open
        recent_change_pct = ((last_close - recent_open) / recent_open * 100) if recent_open else 0
        consecutive_green = 0
        for bar in reversed(last_12):
            if bar["close"] > bar["open"]:
                consecutive_green += 1
            else:
                break
        prior_range_pct = 0.0
        if prior_24:
            prior_high = max(bar["high"] for bar in prior_24)
            prior_low = min(bar["low"] for bar in prior_24)
            prior_mid = _median_float([bar["close"] for bar in prior_24], last_close)
            prior_range_pct = ((prior_high - prior_low) / max(prior_mid, 1e-9) * 100) if prior_mid else 0
        near_range_high_pct = ((recent_high - last_close) / last_close * 100) if last_close else 999
        first_half = last_12[: max(1, len(last_12) // 2)]
        second_half = last_12[max(1, len(last_12) // 2):] or last_12
        higher_lows = min(bar["low"] for bar in second_half) >= min(bar["low"] for bar in first_half) * 0.997
        vwap_hold = last_close >= vwap * 0.997
        compression = bool(prior_range_pct > 0 and recent_range_pct <= max(1.25, prior_range_pct * 0.72))
        tight_coil = recent_range_pct <= max(2.2, min(4.0, abs(profile.get("change24", 0) or 0) * 0.35 + 1.2))
        near_breakout = near_range_high_pct <= 0.75
        previous_volume = _median_float([bar["volume"] for bar in prior_24], median_vol) if prior_24 else median_vol
        recent_volume = _median_float([bar["volume"] for bar in last_12[:-1]], median_vol) if len(last_12) > 1 else median_vol
        volume_dryup = bool(previous_volume > 0 and recent_volume <= previous_volume * 0.90)
        volume_wake = bool(vol_ratio >= 0.85)
        recent_extension = bool(recent_change_pct >= 5.0 or (consecutive_green >= 6 and recent_change_pct >= 3.0))
        pre_score = 0
        pre_reasons = []
        if vwap_hold:
            pre_score += 20
            pre_reasons.append("vwap_hold")
        if higher_lows:
            pre_score += 18
            pre_reasons.append("higher_lows")
        if compression or tight_coil:
            pre_score += 22
            pre_reasons.append("compression")
        if near_breakout:
            pre_score += 18
            pre_reasons.append("near_range_high")
        if volume_dryup:
            pre_score += 10
            pre_reasons.append("volume_dryup")
        if volume_wake:
            pre_score += 10
            pre_reasons.append("volume_wake")
        if recent_extension:
            pre_score -= 22
            pre_reasons.append("recent_5m_run_already_extended")
        if chase_candle or candle_change_pct >= max_safe_candle or range_pct >= max_safe_range:
            pre_score -= 25
            pre_reasons.append("anti_chase_block")
        if distance_r is not None:
            if distance_r <= _EARLY_MOVER_MAX_ARMED_DISTANCE_R:
                pre_score += 8
            elif distance_r > 0.65:
                pre_score -= 20
                pre_reasons.append("too_far_from_entry")
        pre_score = int(round(max(0, min(pre_score, 100))))
        pre_structure_ok = bool(
            vwap_hold
            and higher_lows
            and (compression or tight_coil)
            and near_breakout
            and not recent_extension
        )
        pre_breakout_ok = bool(pre_score >= _EARLY_MOVER_MIN_ARMED_PREBREAKOUT_SCORE and pre_structure_ok)
        if pre_score >= _EARLY_MOVER_MIN_ARMED_PREBREAKOUT_SCORE and not pre_structure_ok:
            pre_reasons.append("pre_breakout_structure_incomplete")

        threshold = _early_mover_execution_threshold(matched, profile)
        entry_distance_valid = bool(distance_r is None or -0.10 <= distance_r <= 0.75)
        ok = bool(matched and score >= threshold and entry_distance_valid)
        if ok:
            reason = f"adaptive_{timeframe}_{matched[0]}"
        elif distance_r is not None and distance_r < -0.10:
            reason = "price_below_entry_tolerance"
        elif distance_r is not None and distance_r > 0.75:
            reason = "entry_already_extended"
        elif chase_candle:
            reason = f"single_{timeframe}_candle_chase"
        elif not matched:
            reason = f"no_fresh_{timeframe}_trigger"
        else:
            reason = "execution_score_below_threshold"

        last_timestamp = _candle_epoch_seconds(last)
        return {
            "ok": ok,
            "reason": reason,
            "symbol": _extract_alert_ticker(row),
            "timeframe": timeframe,
            "execution_score": int(round(max(0, min(score, 100)))),
            "execution_threshold": threshold if threshold < 999 else None,
            "execution_model": "adaptive_execution_v1",
            "matched": matched,
            "last_close": round(last_close, 10),
            "last_candle_timestamp": int(last_timestamp) if last_timestamp is not None else None,
            "last_candle_closed_at": freshness.get("closed_at"),
            "execution_data_age_seconds": freshness.get("age_seconds"),
            "price_basis_diff_pct": round(price_basis_diff_pct, 2),
            "dropped_open_candle": dropped_open_bar,
            "vwap": round(vwap, 10),
            "volume_ratio": round(vol_ratio, 2),
            "close_pos": round(close_pos, 2),
            "candle_change_pct": round(candle_change_pct, 2),
            "range_pct": round(range_pct, 2),
            "distance_to_entry_r": round(distance_r, 2) if distance_r is not None else None,
            "pre_breakout_ok": pre_breakout_ok,
            "pre_breakout_score": pre_score,
            "pre_breakout_reasons": pre_reasons,
            "pre_breakout_reason": "5m_coil_near_breakout" if pre_breakout_ok else "pre_breakout_not_ready",
            "recent_range_pct": round(recent_range_pct, 2),
            "recent_change_pct": round(recent_change_pct, 2),
            "consecutive_green_5m": consecutive_green,
            "prior_range_pct": round(prior_range_pct, 2),
            "near_range_high_pct": round(near_range_high_pct, 2),
            "vwap_hold": vwap_hold,
            "higher_lows": higher_lows,
            "volume_dryup": volume_dryup,
        }
    except Exception as exc:
        return {"ok": False, "reason": "trigger_parse_failed", "detail": str(exc)[:120], "timeframe": timeframe, "execution_score": 0}


def _early_mover_htf_armed_context(row: Dict[str, Any], bars: List[Dict[str, Any]], timeframe: str = "4h") -> Dict[str, Any]:
    """Gate EXPLOSION_ARMED with higher-timeframe context.

    A 5m coil after a long 4h rebound is not "shortly before breakout"; it is
    often the place where late longs provide exit liquidity. This check only
    affects pre-breakout/armed state, not confirmed 5m trade triggers.
    """
    timeframe = str(timeframe or "4h").lower()
    clean = []
    for bar in _completed_candles_only(bars or [], timeframe):
        try:
            open_ = float(bar["open"])
            high = float(bar["high"])
            low = float(bar["low"])
            close = float(bar["close"])
            if open_ > 0 and close > 0 and high > low:
                clean.append({"open": open_, "high": high, "low": low, "close": close})
        except Exception:
            continue

    if len(clean) < 10:
        return {"armed_ok": False, "reason": "htf_not_enough_bars", "timeframe": timeframe, "bar_count": len(clean)}

    recent = clean[-8:]
    prior = clean[-32:-8] if len(clean) >= 40 else clean[:-8]
    last_close = recent[-1]["close"]
    recent_open = recent[0]["open"]
    recent_high = max(bar["high"] for bar in recent)
    recent_low = min(bar["low"] for bar in recent)
    recent_change_pct = ((last_close - recent_open) / recent_open * 100) if recent_open else 0
    recent_range_pct = ((recent_high - recent_low) / last_close * 100) if last_close else 999
    near_recent_high_pct = ((recent_high - last_close) / last_close * 100) if last_close else 999
    rebound_from_recent_low_pct = ((last_close - recent_low) / recent_low * 100) if recent_low else 0
    last_bar = recent[-1]
    last_bar_close_pos = (last_bar["close"] - last_bar["low"]) / max(last_bar["high"] - last_bar["low"], 1e-9)
    last_bar_red = last_bar["close"] < last_bar["open"]
    green_count = sum(1 for bar in recent if bar["close"] > bar["open"])
    consecutive_green = 0
    for bar in reversed(recent):
        if bar["close"] > bar["open"]:
            consecutive_green += 1
        else:
            break

    prior_range_pct = 0.0
    if prior:
        prior_high = max(bar["high"] for bar in prior)
        prior_low = min(bar["low"] for bar in prior)
        prior_mid = _median_float([bar["close"] for bar in prior], last_close)
        prior_range_pct = ((prior_high - prior_low) / max(prior_mid, 1e-9) * 100) if prior_mid else 0

    reasons = []
    if recent_change_pct >= 6.0:
        reasons.append("htf_move_already_extended")
    if rebound_from_recent_low_pct >= 8.0:
        reasons.append("htf_rebound_from_lows_already_extended")
    if consecutive_green >= 4 or (green_count >= 6 and recent_change_pct >= 4.0):
        reasons.append("htf_green_run_extended")
    if last_bar_red and last_bar_close_pos <= 0.45:
        reasons.append("htf_current_bar_rejecting")
    if near_recent_high_pct > 1.2:
        reasons.append("not_near_4h_breakout_level")
    if recent_range_pct > 7.0 and recent_change_pct > 3.0:
        reasons.append("htf_not_compressed")
    if prior_range_pct and recent_range_pct > max(6.0, prior_range_pct * 0.95) and recent_change_pct > 2.5:
        reasons.append("htf_range_not_tightening")

    return {
        "armed_ok": not reasons,
        "reason": "htf_context_ok" if not reasons else reasons[0],
        "reasons": reasons,
        "timeframe": timeframe,
        "recent_change_pct": round(recent_change_pct, 2),
        "recent_range_pct": round(recent_range_pct, 2),
        "near_recent_high_pct": round(near_recent_high_pct, 2),
        "rebound_from_recent_low_pct": round(rebound_from_recent_low_pct, 2),
        "last_bar_close_pos": round(last_bar_close_pos, 2),
        "green_count_8": green_count,
        "consecutive_green": consecutive_green,
        "prior_range_pct": round(prior_range_pct, 2),
    }


def _early_mover_htf_execution_context(row: Dict[str, Any], bars: List[Dict[str, Any]], timeframe: str = "4h") -> Dict[str, Any]:
    """Block live long entries when the higher timeframe is rejecting a spike.

    A 5m retest can briefly look valid while the 4h candle is actively selling
    off from a liquidity sweep. In that situation the correct action is wait,
    not JETZT_TRADEN.
    """
    timeframe = str(timeframe or "4h").lower()
    clean = []
    for bar in bars or []:
        try:
            open_ = float(bar["open"])
            high = float(bar["high"])
            low = float(bar["low"])
            close = float(bar["close"])
            if open_ > 0 and close > 0 and high > low:
                clean.append({"open": open_, "high": high, "low": low, "close": close})
        except Exception:
            continue

    if len(clean) < 8:
        return {
            "ok": False,
            "reason": "htf_execution_context_missing",
            "timeframe": timeframe,
            "bar_count": len(clean),
        }

    recent = clean[-8:]
    last = recent[-1]
    prev = recent[-2]
    recent_high = max(bar["high"] for bar in recent)
    recent_low = min(bar["low"] for bar in recent)
    last_close = last["close"]
    last_open = last["open"]
    last_high = last["high"]
    last_low = last["low"]
    last_close_pos = (last_close - last_low) / max(last_high - last_low, 1e-9)
    last_change_pct = ((last_close - last_open) / last_open * 100) if last_open else 0
    pullback_from_high_pct = ((recent_high - last_close) / last_close * 100) if last_close else 999
    bounce_from_low_pct = ((last_close - recent_low) / recent_low * 100) if recent_low else 0
    prev_red = prev["close"] < prev["open"]
    last_red = last_close < last_open
    lower_high = last_high < prev["high"] * 0.998
    lower_close = last_close < prev["close"] * 0.998

    reasons = []
    if last_red and last_close_pos <= 0.35 and pullback_from_high_pct >= 1.5:
        reasons.append("htf_current_bar_rejecting")
    if pullback_from_high_pct >= 3.0 and last_red and lower_close:
        reasons.append("htf_pullback_after_spike")
    if prev_red and last_red and pullback_from_high_pct >= 2.0:
        reasons.append("htf_two_red_after_spike")
    if pullback_from_high_pct >= 4.5 and lower_high and lower_close:
        reasons.append("htf_lower_high_after_sweep")
    if last_change_pct <= -2.2 and last_close_pos <= 0.45:
        reasons.append("htf_active_red_candle")

    return {
        "ok": not reasons,
        "reason": "htf_execution_context_ok" if not reasons else reasons[0],
        "reasons": reasons,
        "timeframe": timeframe,
        "pullback_from_high_pct": round(pullback_from_high_pct, 2),
        "bounce_from_low_pct": round(bounce_from_low_pct, 2),
        "last_bar_change_pct": round(last_change_pct, 2),
        "last_bar_close_pos": round(last_close_pos, 2),
        "last_bar_red": last_red,
        "lower_high": lower_high,
        "lower_close": lower_close,
    }


def _verify_early_mover_intraday_trigger(row: Dict[str, Any]) -> Dict[str, Any]:
    """Confirm Early-Mover mail candidates with adaptive exchange execution candles."""
    symbol = _extract_alert_ticker(row)
    contract = row.get("PerpChartSymbol") or row.get("PerpMatchSymbol")
    exchange = _normalize_crypto_exchange(row.get("PerpChartExchange") or row.get("BestExchange"))
    if not HAS_NEW_LISTING_SCANNER:
        return {"ok": False, "reason": "exchange_chart_module_missing"}
    if not contract or not exchange:
        return {"ok": False, "reason": "no_perp_chart_for_realtime_trigger"}

    profile = _early_mover_trigger_profile(row)
    setup = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}
    plan_fingerprint = ":".join(
        str(value or "") for value in (
            row.get("trade_action"),
            row.get("entry", setup.get("entry")),
            row.get("stop_loss", row.get("stop", setup.get("stop_loss", setup.get("stop")))),
            row.get("tp1", setup.get("tp1")),
            row.get("tp2", setup.get("tp2")),
        )
    )
    cache_key = f"{exchange}:{contract}:adaptive_5m_v3:{plan_fingerprint}"
    now = time.time()
    cached = _EARLY_MOVER_TRIGGER_CACHE.get(cache_key)
    if cached and now - cached.get("ts", 0) < _EARLY_MOVER_TRIGGER_TTL:
        return dict(cached["result"])

    checks: List[Tuple[str, int]] = [("5m", 36)]

    results = []
    for timeframe, count in checks:
        try:
            bars = fetch_candles_for(str(contract), exchange, timeframe=timeframe, count=count)
            completed_bars = _completed_candles_only(bars or [], timeframe)
            scored = _score_early_mover_trigger_bars(row, bars, timeframe, profile)
            vrvp = _early_mover_vrvp_from_bars(completed_bars)
            if vrvp:
                scored["vrvp"] = vrvp
            if scored.get("ok"):
                try:
                    htf_bars = fetch_candles_for(str(contract), exchange, timeframe="4h", count=48)
                    execution_context = _early_mover_htf_execution_context(row, htf_bars, "4h")
                except Exception as htf_exc:
                    execution_context = {
                        "ok": False,
                        "reason": "htf_execution_context_fetch_failed",
                        "detail": str(htf_exc)[:120],
                        "timeframe": "4h",
                    }
                scored["htf_execution_context"] = execution_context
                if not execution_context.get("ok"):
                    scored["ok"] = False
                    scored["reason"] = execution_context.get("reason") or "htf_execution_rejecting"
                    scored["htf_rejection_reasons"] = execution_context.get("reasons", [])
            if scored.get("pre_breakout_ok"):
                try:
                    htf_bars = fetch_candles_for(str(contract), exchange, timeframe="4h", count=48)
                    htf_context = _early_mover_htf_armed_context(row, htf_bars, "4h")
                except Exception as htf_exc:
                    htf_context = {
                        "armed_ok": False,
                        "reason": "htf_context_fetch_failed",
                        "detail": str(htf_exc)[:120],
                        "timeframe": "4h",
                    }
                scored["htf_context"] = htf_context
                if not htf_context.get("armed_ok"):
                    scored["pre_breakout_ok"] = False
                    scored["pre_breakout_reason"] = htf_context.get("reason") or "htf_context_not_ready"
                    reasons = list(scored.get("pre_breakout_reasons") or [])
                    reasons.extend(htf_context.get("reasons") or [htf_context.get("reason")])
                    scored["pre_breakout_reasons"] = list(dict.fromkeys([r for r in reasons if r]))
        except Exception as exc:
            scored = {"ok": False, "reason": "trigger_fetch_failed", "detail": str(exc)[:120], "timeframe": timeframe, "execution_score": 0}
        scored.update({"symbol": symbol, "contract": contract, "exchange": exchange})
        results.append(scored)
        if scored.get("ok"):
            break

    result = max(results, key=lambda item: item.get("execution_score", 0)) if results else {"ok": False, "reason": "no_trigger_checks", "execution_score": 0}
    # AUDIT Q-2: Original-Pruefzeitpunkt mitfuehren, damit der Mail-Pfad das
    # Trigger-Alter auch fuer Cache-Treffer korrekt bestimmen kann.
    result["checked_at"] = now
    result["adaptive_checks"] = [
        {
            "timeframe": item.get("timeframe"),
            "ok": bool(item.get("ok")),
            "score": item.get("execution_score", 0),
            "reason": item.get("reason"),
        }
        for item in results
    ]
    if result.get("ok"):
        liquidity = _early_mover_orderbook_liquidity(str(contract), exchange)
        result["liquidity"] = liquidity
        if not liquidity.get("ok"):
            result["ok"] = False
            result["reason"] = "thin_orderbook_market_impact"
            result["liquidity_reasons"] = liquidity.get("reasons", [])

    _EARLY_MOVER_TRIGGER_CACHE[cache_key] = {"ts": now, "result": result}
    if len(_EARLY_MOVER_TRIGGER_CACHE) > _EARLY_MOVER_TRIGGER_CACHE_MAX:
        overflow = len(_EARLY_MOVER_TRIGGER_CACHE) - _EARLY_MOVER_TRIGGER_CACHE_MAX
        oldest = sorted(_EARLY_MOVER_TRIGGER_CACHE.items(), key=lambda item: item[1].get("ts", 0))[:max(overflow, 50)]
        for key, _ in oldest:
            _EARLY_MOVER_TRIGGER_CACHE.pop(key, None)
    return dict(result)


def _early_mover_mail_trigger_block_reason(trigger_check: Optional[Dict[str, Any]]) -> Optional[str]:
    if not isinstance(trigger_check, dict) or not trigger_check.get("ok"):
        reason = trigger_check.get("reason", "no_intraday_trigger") if isinstance(trigger_check, dict) else "no_intraday_trigger"
        return f"early_mover_{reason}"
    timeframe = str(trigger_check.get("timeframe") or "").lower()
    if timeframe == "1m":
        return "early_mover_1m_trigger_disabled"
    return None


def _early_mover_explosion_score(row: Dict[str, Any], trigger_check: Optional[Dict[str, Any]] = None) -> int:
    """Score the pre-breakout coil itself, independent from broad daily setup score."""
    check = trigger_check if isinstance(trigger_check, dict) else row.get("intraday_trigger")
    check = check if isinstance(check, dict) else {}
    fields = _extract_early_mover_fields(row)
    setup = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}
    flags = set(fields.get("risk_flags") or [])

    setup_score = _alert_float(row.get("setup_score", row.get("score")), 0) or 0
    pre_score = _alert_float(check.get("pre_breakout_score", row.get("pre_breakout_score")), 0) or 0
    live_rr = fields["live_rr"]
    distance_r = fields["distance_to_entry_r"]
    risk_level = str(row.get("risk_level", "") or "").upper()
    target_quality = str(row.get("target_quality", setup.get("target_quality", "")) or "").upper()
    alpha_24h = fields["alpha_24h"]

    score = pre_score * 0.58 + min(setup_score, 100) * 0.18
    if live_rr >= 2.5:
        score += 10
    elif live_rr >= 1.8:
        score += 7
    elif live_rr >= _EARLY_MOVER_VISIBLE_MIN_LIVE_RR:
        score += 4
    else:
        score -= 12

    if distance_r <= 0.25:
        score += 8
    elif distance_r <= _EARLY_MOVER_MAX_ARMED_DISTANCE_R:
        score += 5
    elif distance_r <= _EARLY_MOVER_VISIBLE_MAX_DISTANCE_R:
        score += 1
    else:
        score -= 18

    btc_ok = _early_mover_btc_allows_long(fields)
    if fields["btc_tailwind"]:
        score += 5
    elif btc_ok:
        score += 2
    else:
        score -= 16
    if alpha_24h >= 2:
        score += 4
    elif alpha_24h < -2:
        score -= 5

    if target_quality == "STRUCTURAL":
        score += 5
    elif target_quality.startswith("WEAK"):
        score -= 6

    if risk_level == "MEDIUM":
        score -= 5
    elif risk_level == "HIGH":
        score -= 30

    penalty_map = {
        "perp_liquidity_watch": 5,
        "weak_structural_targets": 4,
        "high_volume_turnover": 5,
        "extreme_volume_turnover": 9,
        "very_high_volume_turnover": 13,
        "turnover_without_alpha": 20,
        "extreme_turnover_churn": 20,
        "chased_from_entry": 18,
        "btc_headwind": 3 if btc_ok else 18,
        "btc_caution": 3,
        "partial_crypto_data": 20,
        "data_warning": 20,
        "thin_perp_liquidity": 30,
        "thin_orderbook": 30,
        "market_impact_risk": 30,
        "no_perp_execution_market": 35,
        "overheated_phase3": 35,
    }
    for flag, penalty in penalty_map.items():
        if flag in flags:
            score -= penalty

    return int(round(max(0, min(100, score))))


def _early_mover_explosion_armed_state(row: Dict[str, Any], trigger_check: Optional[Dict[str, Any]] = None) -> Tuple[bool, List[str]]:
    """True when the coin is a high-conviction pre-breakout setup, not a generic watch row."""
    check = trigger_check if isinstance(trigger_check, dict) else row.get("intraday_trigger")
    check = check if isinstance(check, dict) else {}
    fields = _extract_early_mover_fields(row)
    flags = set(fields.get("risk_flags") or [])
    action = fields["trade_action"]
    setup_score = int(_alert_float(row.get("setup_score", row.get("score")), 0) or 0)
    pre_score = int(_alert_float(check.get("pre_breakout_score", row.get("pre_breakout_score")), 0) or 0)
    pre_ok = bool(check.get("pre_breakout_ok", row.get("pre_breakout_armed_candidate", False)))
    explosion_score = _early_mover_explosion_score(row, check)
    reasons: List[str] = []

    if action not in ("LONG_TRIGGER", "WAIT_FOR_RETEST"):
        reasons.append("action_not_armed")
    if bool(check.get("ok")):
        reasons.append("already_trade_triggered")
    if setup_score < _EARLY_MOVER_MIN_ARMED_SETUP_SCORE:
        reasons.append("setup_score_below_armed_threshold")
    if pre_score < _EARLY_MOVER_MIN_ARMED_PREBREAKOUT_SCORE:
        reasons.append("pre_breakout_score_below_threshold")
    if not pre_ok:
        reasons.append("not_pre_breakout_coil")
    htf_context = check.get("htf_context") if isinstance(check.get("htf_context"), dict) else row.get("htf_context")
    if not isinstance(htf_context, dict):
        reasons.append("htf_context_missing")
    elif not htf_context.get("armed_ok", False):
        reasons.append(htf_context.get("reason") or "htf_context_not_ready")
    if explosion_score < _EARLY_MOVER_VISIBLE_MIN_SETUP_SCORE:
        reasons.append("explosion_score_below_threshold")
    if str(row.get("risk_level", "") or "").upper() == "HIGH":
        reasons.append("risk_high")
    if fields["live_rr"] < _EARLY_MOVER_VISIBLE_MIN_LIVE_RR:
        reasons.append("live_rr_below_armed_threshold")
    if fields["distance_to_entry_r"] > _EARLY_MOVER_VISIBLE_MAX_DISTANCE_R:
        reasons.append("too_far_from_entry_for_armed")
    btc_ok = _early_mover_btc_allows_long(fields)
    if not btc_ok:
        reasons.append("btc_not_tailwind")
    if fields["partial_data"] or fields["data_warning"]:
        reasons.append("data_not_clean")
    if fields["late_to_tp1"]:
        reasons.append("tp1_already_reached")

    hard_flags = {
        "overheated_phase3",
        "data_warning",
        "chased_from_entry",
        "very_high_volume_turnover",
        "turnover_without_alpha",
        "extreme_turnover_churn",
        "thin_perp_liquidity",
        "thin_orderbook",
        "market_impact_risk",
        "no_perp_execution_market",
        "weak_structural_targets",
        "duplicate_targets",
        "targets_too_close",
        "invalid_target_plan",
    }
    if not btc_ok:
        hard_flags.add("btc_headwind")
    for flag in sorted(flags.intersection(hard_flags)):
        reasons.append(flag)

    return not reasons, reasons


def _early_mover_armed_orderbook_block_reason(row: Dict[str, Any]) -> Tuple[Optional[str], Dict[str, Any]]:
    """Armed alerts still need a tradable perp book; otherwise the mail creates FOMO in illiquid names."""
    contract = row.get("PerpChartSymbol") or row.get("PerpMatchSymbol")
    exchange = _normalize_crypto_exchange(row.get("PerpChartExchange") or row.get("BestExchange"))
    if not contract or not exchange:
        return "no_perp_execution_market", {}

    liquidity = _early_mover_orderbook_liquidity(str(contract), exchange)
    row["armed_orderbook_liquidity"] = liquidity
    if liquidity.get("ok"):
        return None, liquidity

    reasons = liquidity.get("reasons") if isinstance(liquidity.get("reasons"), list) else []
    reason = reasons[0] if reasons else liquidity.get("reason", "orderbook_not_ok")
    return f"armed_orderbook_{reason}", liquidity


def _early_mover_entry_score(row: Dict[str, Any]) -> int:
    """Score whether this Early-Mover is actionable now, separate from setup quality."""
    fields = _extract_early_mover_fields(row)
    setup_score = int(_alert_float(row.get("setup_score", row.get("score")), 0) or 0)
    action = str(row.get("trade_action", row.get("entry_status", "")) or "").upper()
    signal = str(row.get("trade_signal", "") or "").upper()
    entry_status = str(row.get("entry_status", "") or "").upper()
    risk_level = str(row.get("risk_level", "") or "").upper()
    flags = {str(flag).lower() for flag in (row.get("risk_flags") or [])}
    setup = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}

    score = setup_score
    if signal == "JETZT_TRADEN":
        score += 8
    elif row.get("pre_breakout_armed"):
        pre_score = _alert_float(row.get("pre_breakout_score"), 0) or 0
        score = max(score - 12, int(setup_score * 0.72 + pre_score * 0.28))
    elif action == "LONG_TRIGGER" or entry_status == "WAIT_FOR_TRIGGER":
        score -= 38
    elif action == "WAIT_FOR_RETEST" or entry_status == "WAIT_FOR_RETEST":
        score -= 30
    elif action == "WAIT_FOR_CONTINUATION":
        score -= 42
    elif action == "WAIT_FOR_LIQUIDITY":
        score -= 50
    elif action == "WAIT_FOR_BTC_CONFIRMATION":
        score -= 45
    elif action in ("NO_LONG_CHASE", "NO_TRADE") or signal == "NICHT_TRADEN":
        score = min(score, 25)
    elif signal in ("WARTEN", "BEOBACHTEN"):
        score -= 22

    if risk_level == "HIGH":
        score -= 30
    elif risk_level == "MEDIUM":
        score -= 10

    flag_penalties = {
        "thin_orderbook": 35,
        "market_impact_risk": 35,
        "thin_perp_liquidity": 30,
        "perp_liquidity_watch": 8,
        "no_perp_execution_market": 28,
        "turnover_without_alpha": 18,
        "extreme_turnover_churn": 20,
        "extreme_volume_turnover": 14,
        "very_high_volume_turnover": 14,
        "high_volume_turnover": 8,
        "btc_headwind": 18,
        "partial_crypto_data": 18,
        "data_warning": 15,
        "chased_from_entry": 16,
        "overheated_phase3": 28,
        "oi_snapshot_only": 6,
        "weak_structural_targets": 26,
    }
    btc_ok = _early_mover_btc_allows_long(fields)
    for flag in flags:
        if flag == "btc_headwind" and btc_ok:
            score -= 3
            continue
        score -= flag_penalties.get(flag, 0)
    if "vrvp_target_confirmed" in flags:
        score += 5

    live_rr = _alert_float(row.get("live_rr_ratio", setup.get("live_rr")), 0) or 0
    if live_rr and live_rr < 1.5:
        score -= 16
    elif signal == "JETZT_TRADEN" and live_rr >= 2.0:
        score += 4

    distance_r = _alert_float(row.get("distance_to_entry_r", setup.get("distance_to_entry_r")), 0) or 0
    if distance_r >= 0.75:
        score -= 16
    elif distance_r >= 0.35:
        score -= 8

    execution_score = _alert_float(row.get("execution_quality_score"), None)
    if signal == "JETZT_TRADEN" and execution_score is not None:
        score = max(score, int(setup_score * 0.55 + execution_score * 0.45))

    return max(0, min(100, int(round(score))))


def _early_mover_entry_score_label(row: Dict[str, Any]) -> str:
    score = int(_alert_float(row.get("entry_score"), 0) or 0)
    signal = str(row.get("trade_signal", "") or "").upper()
    action = str(row.get("trade_action", "") or "").upper()
    if signal == "JETZT_TRADEN":
        return "ENTRY OK"
    if action == "WAIT_FOR_RETEST":
        return "RETEST WARTEN"
    if action == "LONG_TRIGGER":
        return "ENTRY WARTEN"
    if score >= 75:
        return "FAST BEREIT"
    if score >= 50:
        return "WATCH"
    return "NICHT BEREIT"


def _early_mover_trade_score(row: Dict[str, Any]) -> int:
    """Score a *trade now* candidate without letting one strong pillar hide a weak one.

    Setup quality, entry/timing and the fresh 5m execution trigger are different
    dimensions. A max() score is dangerous here: a 90 setup with a mediocre entry
    can look like an S trade. This score uses a weighted blend capped by the
    weakest pillar, so mails need setup, timing and execution to agree.
    """
    setup = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}
    setup_score = int(_alert_float(row.get("setup_score", row.get("score")), 0) or 0)
    entry_value = _alert_float(row.get("entry_score"), None)
    entry_score = int(entry_value if entry_value is not None else _early_mover_entry_score(row))
    execution_value = _alert_float(row.get("execution_quality_score"), None)
    execution_score = int(execution_value if execution_value is not None else (80 if _alert_bool(row.get("execution_trigger_ok")) else 0))
    signal = str(row.get("trade_signal", "") or "").upper()

    if signal != "JETZT_TRADEN":
        return max(0, min(100, min(setup_score, entry_score)))

    pillars = [max(0, setup_score), max(0, entry_score), max(0, execution_score)]
    weighted = pillars[0] * 0.38 + pillars[1] * 0.34 + pillars[2] * 0.28
    weakest_cap = min(pillars) + 14
    score = min(weighted, weakest_cap)

    fields = _extract_early_mover_fields(row)
    risk_level = str(row.get("risk_level", "") or "").upper()
    flags = {str(flag).lower() for flag in (row.get("risk_flags") or setup.get("risk_flags") or [])}

    if fields["live_rr"] < _EARLY_MOVER_MIN_ALERT_RR:
        score = min(score, 45)
    if fields["distance_to_entry_r"] > _EARLY_MOVER_VISIBLE_MAX_DISTANCE_R:
        score = min(score, 55)
    if risk_level == "MEDIUM":
        score = min(score, 82)
    elif risk_level == "HIGH":
        score = min(score, 35)

    hard_flags = {
        "overheated_phase3",
        "partial_crypto_data",
        "data_warning",
        "tp1_already_reached",
        "chased_from_entry",
        "very_high_volume_turnover",
        "turnover_without_alpha",
        "extreme_turnover_churn",
        "thin_perp_liquidity",
        "thin_orderbook",
        "market_impact_risk",
        "no_perp_execution_market",
        "weak_structural_targets",
        "duplicate_targets",
        "targets_too_close",
        "invalid_target_plan",
    }
    if flags.intersection(hard_flags):
        score = min(score, 35)

    return int(round(max(0, min(100, score))))


def _early_mover_vrvp_from_bars(bars: List[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """Build compact VRVP levels from exchange candles for target selection."""
    current = _alert_float((bars or [{}])[-1].get("close")) if bars else None
    profile = build_vrvp_structure(
        bars or [],
        current,
        "LONG",
        timeframe="5m",
        num_bins=18,
        min_bars=20,
        lookback=96,
    )
    if not profile:
        return None

    levels = []

    for level in (profile.get("resistances") or []) + (profile.get("supports") or []):
        price = _alert_float(level.get("price"))
        if price is None or price <= 0:
            continue
        levels.append({
            "price": _round_crypto_price(price),
            "source": str(level.get("source") or "vrvp_level").lower().replace(" ", "_"),
            "weight": int((_alert_float(level.get("weight"), 1) or 1) * 40),
        })

    return {
        "poc": _round_crypto_price(profile.get("poc")),
        "vah": _round_crypto_price(profile.get("vah")),
        "val": _round_crypto_price(profile.get("val")),
        "levels": sorted(levels, key=lambda item: item["price"]),
        "source": "exchange_vrvp_5m",
    }


def _annotate_early_mover_overhead_resistance(
    row: Dict[str, Any],
    level: Dict[str, Any],
    entry: float,
    risk: float,
) -> None:
    """Expose a close overhead VRVP level as a breakout gate, not as a TP."""
    if not isinstance(level, dict) or entry <= 0 or risk <= 0:
        return
    price = _alert_float(level.get("price"))
    if price is None or price <= entry:
        return

    source = str(level.get("source") or "vrvp_resistance")
    # NACHAUDIT N3: defensiv auch hier — LVN-Kanten nie als Barriere werten.
    if source.startswith("vrvp_lvn"):
        return

    distance_pct = ((price - entry) / entry) * 100
    distance_r = (price - entry) / risk
    if distance_pct > 2.5 and distance_r > 1.0:
        return

    rounded_price = _round_crypto_price(price)
    resistance = {
        "price": rounded_price,
        "distance_pct": round(distance_pct, 2),
        "distance_r": round(distance_r, 2),
        "source": source,
        "message": "Nahe Resistance: erst Break/Reclaim darueber bestaetigen",
    }

    row["overhead_resistance"] = resistance
    row["breakout_level"] = rounded_price
    row["resistance_source"] = source
    flags = row.get("risk_flags") if isinstance(row.get("risk_flags"), list) else []
    row["risk_flags"] = list(dict.fromkeys([*flags, "near_overhead_resistance"]))

    setup = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}
    if setup:
        setup["overhead_resistance"] = resistance
        setup["breakout_level"] = rounded_price
        setup["resistance_source"] = source
        setup_flags = setup.get("risk_flags") if isinstance(setup.get("risk_flags"), list) else []
        setup["risk_flags"] = list(dict.fromkeys([*setup_flags, "near_overhead_resistance"]))
        conditions = setup.get("trigger_conditions") if isinstance(setup.get("trigger_conditions"), list) else []
        condition = f"Break/Reclaim ueber ${rounded_price} bestaetigen"
        setup["trigger_conditions"] = list(dict.fromkeys([condition, *conditions]))[:4]
        row["trade_setup"] = setup


def _apply_early_mover_vrvp_targets(row: Dict[str, Any], vrvp: Optional[Dict[str, Any]]) -> None:
    """Use VRVP resistance/acceptance levels as TP candidates when they are valid."""
    if not isinstance(vrvp, dict):
        return
    entry = _alert_float(row.get("entry"))
    stop = _alert_float(row.get("stop_loss", row.get("stop")))
    if entry is None or stop is None or entry <= 0 or stop <= 0 or stop >= entry:
        return

    risk = entry - stop
    setup = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}
    target_req = setup.get("target_min_pct_required") if isinstance(setup.get("target_min_pct_required"), dict) else {}
    min_tp1_pct = (_alert_float(target_req.get("tp1"), 5.5) or 5.5) / 100
    min_tp2_pct = (_alert_float(target_req.get("tp2"), 9.5) or 9.5) / 100
    min_tp1 = max(entry + risk * 1.35, entry * (1 + min_tp1_pct))
    min_tp2 = max(entry + risk * 2.6, entry * (1 + min_tp2_pct))

    levels = sorted([
        level for level in (vrvp.get("levels") or [])
        if _alert_float(level.get("price")) is not None and _alert_float(level.get("price")) > entry
    ], key=lambda level: _alert_float(level.get("price")) or 0)
    if not levels:
        return

    # NACHAUDIT N3 (H10-Restpfad): LVN-Kanten sind Volumen-Vakuum
    # (Beschleunigungszonen), keine Widerstaende. Nur strukturelle Level
    # (POC/VAH/VAL/HVN) duerfen als Overhead-Barriere ein
    # WAIT_FOR_BREAK_RECLAIM ausloesen.
    structural_levels = [
        level for level in levels
        if not str(level.get("source") or "").startswith("vrvp_lvn")
    ]
    if structural_levels:
        _annotate_early_mover_overhead_resistance(row, structural_levels[0], entry, risk)

    valid_tp1 = [level for level in levels if (_alert_float(level.get("price")) or 0) >= min_tp1]
    if not valid_tp1:
        return
    tp1_level = valid_tp1[0]
    tp1 = _alert_float(tp1_level.get("price"))

    valid_tp2 = [
        level for level in levels
        if (_alert_float(level.get("price")) or 0) >= max(min_tp2, (tp1 or 0) + risk * 0.25)
    ]
    tp2_level = valid_tp2[0] if valid_tp2 else None
    current_tp2 = _alert_float(row.get("tp2"), 0) or 0
    tp2 = _alert_float(tp2_level.get("price")) if tp2_level else current_tp2
    if tp1 is None or tp2 is None or tp2 <= tp1:
        return

    min_tp2_gap = max(entry * 0.018, risk * 0.45)
    if (tp2 - tp1) < min_tp2_gap:
        flags = row.get("risk_flags") if isinstance(row.get("risk_flags"), list) else []
        row["risk_flags"] = list(dict.fromkeys([*flags, "targets_too_close", "weak_structural_targets"]))
        row["target_quality"] = "WEAK_STRUCTURAL_TARGETS"
        if setup:
            setup_flags = setup.get("risk_flags") if isinstance(setup.get("risk_flags"), list) else []
            setup["risk_flags"] = list(dict.fromkeys([*setup_flags, "targets_too_close", "weak_structural_targets"]))
            setup["target_quality"] = "WEAK_STRUCTURAL_TARGETS"
            setup_warnings = setup.get("warnings") if isinstance(setup.get("warnings"), list) else []
            setup["warnings"] = list(dict.fromkeys([*setup_warnings, "target_plan_invalid"]))
            row["trade_setup"] = setup
        return

    current_tp1 = _alert_float(row.get("tp1"), 0) or 0
    current_quality = str(row.get("target_quality") or setup.get("target_quality") or "").upper()
    should_replace_tp1 = current_quality.startswith("WEAK") or current_tp1 <= 0 or tp1 < current_tp1 or str(row.get("tp1_source", "")).endswith("_too_close")
    should_replace_tp2 = current_quality.startswith("WEAK") or current_tp2 <= 0 or tp2 < current_tp2 or str(row.get("tp2_source", "")).endswith("_too_close")
    if not should_replace_tp1 and not should_replace_tp2:
        return

    if should_replace_tp1:
        row["tp1"] = _round_crypto_price(tp1)
        row["tp1_source"] = tp1_level.get("source") or "vrvp_resistance"
    if should_replace_tp2:
        row["tp2"] = _round_crypto_price(tp2)
        row["tp2_source"] = (tp2_level or {}).get("source") or "vrvp_resistance"

    new_tp1 = _alert_float(row.get("tp1"), tp1) or tp1
    new_tp2 = _alert_float(row.get("tp2"), tp2) or tp2
    geometry = trade_geometry(entry, stop, new_tp1, new_tp2, "LONG")
    if not geometry.get("valid"):
        flags = row.get("risk_flags") if isinstance(row.get("risk_flags"), list) else []
        row["risk_flags"] = list(dict.fromkeys([*flags, "invalid_trade_geometry", "weak_structural_targets"]))
        row["target_quality"] = "WEAK_STRUCTURAL_TARGETS"
        return

    rr_tp1 = geometry["rr_tp1"]
    rr_tp2 = geometry["rr_tp2"]
    live_entry = _alert_float(
        row.get("execution_price", row.get("current_price", row.get("Price"))),
        entry,
    ) or entry
    live_geometry = trade_geometry(live_entry, stop, new_tp1, new_tp2, "LONG")
    live_rr = live_geometry.get("rr") if live_geometry.get("valid") else 0
    row.update({
        "rr_tp1": rr_tp1,
        "rr_tp2": rr_tp2,
        "risk_reward": geometry["rr"],
        "live_rr_ratio": live_rr,
        "target_quality": "STRUCTURAL_VRVP",
        "vrvp_levels": vrvp,
    })
    flags = [str(flag) for flag in (row.get("risk_flags") or []) if str(flag) != "weak_structural_targets"]
    row["risk_flags"] = list(dict.fromkeys(flags + ["vrvp_target_confirmed"]))

    if setup:
        setup.update({
            "tp1": row.get("tp1"),
            "tp2": row.get("tp2"),
            "tp1_source": row.get("tp1_source"),
            "tp2_source": row.get("tp2_source"),
            "rr_tp1": rr_tp1,
            "rr_tp2": rr_tp2,
            "rr": row.get("risk_reward"),
            "live_rr": row.get("live_rr_ratio"),
            "target_quality": row.get("target_quality"),
            "vrvp_levels": vrvp,
        })
        row["trade_setup"] = setup


def _clear_early_mover_wait_flags_for_trade_now(row: Dict[str, Any]) -> None:
    """Remove stale watch/trigger-needed flags after a fresh 5m trigger confirms.

    The same row starts as a watch candidate and later gets promoted to
    JETZT_TRADEN. Without this cleanup the UI can show both states at once.
    """
    if str(row.get("trade_signal", "") or "").upper() != "JETZT_TRADEN":
        return
    if not bool(row.get("execution_trigger_ok")):
        return

    def _clean_list(values: Any) -> List[Any]:
        if not isinstance(values, list):
            return []
        cleaned = []
        for value in values:
            normalized = str(value or "").strip().lower()
            if normalized in _EARLY_MOVER_WAIT_ONLY_FLAGS:
                continue
            cleaned.append(value)
        return list(dict.fromkeys(cleaned))

    row["risk_flags"] = _clean_list(row.get("risk_flags"))
    row["risk_reasons"] = _clean_list(row.get("risk_reasons"))
    setup = row.get("trade_setup")
    if isinstance(setup, dict):
        setup["risk_flags"] = _clean_list(setup.get("risk_flags"))
        setup["warnings"] = _clean_list(setup.get("warnings"))
        row["trade_setup"] = setup


def _early_mover_target_plan_issues(row: Dict[str, Any]) -> List[str]:
    """Return hard target-plan issues that make a crypto long non-actionable."""
    setup = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}
    entry = _alert_float(row.get("entry", setup.get("entry")))
    stop = _alert_float(row.get("stop_loss", row.get("stop", setup.get("stop_loss", setup.get("stop")))))
    tp1 = _alert_float(row.get("tp1", setup.get("tp1")))
    tp2 = _alert_float(row.get("tp2", setup.get("tp2")))
    target_quality = str(row.get("target_quality", setup.get("target_quality", "")) or "").upper()
    issues: List[str] = []

    if entry is None or stop is None or tp1 is None or tp2 is None or entry <= 0:
        return ["invalid_target_plan"]
    if math.isclose(tp1, tp2, rel_tol=1e-9, abs_tol=max(entry * 1e-9, 1e-12)):
        issues.append("duplicate_targets")
    geometry = trade_geometry(entry, stop, tp1, tp2, "LONG")
    if not geometry.get("valid"):
        issues.append("invalid_target_plan")
        return list(dict.fromkeys(issues))
    risk = geometry["risk"]
    min_tp2_gap = max(entry * 0.024, risk * 0.55)
    if (tp2 - tp1) < min_tp2_gap:
        issues.append("targets_too_close")
    rr1 = geometry["rr_tp1"]
    rr2 = geometry["rr_tp2"]
    if rr1 < 1.5 or rr2 < max(2.05, rr1 + 0.55):
        issues.append("targets_too_close")
    if target_quality.startswith("WEAK"):
        issues.append("weak_structural_targets")
    return list(dict.fromkeys(issues))


def _block_early_mover_trade_on_bad_targets(row: Dict[str, Any]) -> None:
    """Downgrade JETZT_TRADEN if targets are duplicate, too tight or weak."""
    issues = _early_mover_target_plan_issues(row)
    if not issues:
        return
    all_issues = list(dict.fromkeys([*issues, "weak_structural_targets"]))

    def _merge_flags(key: str) -> None:
        current = row.get(key) if isinstance(row.get(key), list) else []
        row[key] = list(dict.fromkeys([*current, *all_issues]))

    _merge_flags("risk_flags")
    _merge_flags("risk_reasons")
    row["target_quality"] = "WEAK_STRUCTURAL_TARGETS"
    setup = row.get("trade_setup")
    if isinstance(setup, dict):
        setup["target_quality"] = "WEAK_STRUCTURAL_TARGETS"
        setup_flags = setup.get("risk_flags") if isinstance(setup.get("risk_flags"), list) else []
        setup["risk_flags"] = list(dict.fromkeys([*setup_flags, *all_issues]))
        setup_warnings = setup.get("warnings") if isinstance(setup.get("warnings"), list) else []
        setup["warnings"] = list(dict.fromkeys([*setup_warnings, "target_plan_invalid"]))
        row["trade_setup"] = setup

    if str(row.get("trade_signal", "") or "").upper() in {"JETZT_TRADEN", "EXPLOSION_ARMED"}:
        row["trade_signal"] = "WARTEN"
        row["signal_label"] = "Warten: TP1/TP2 sind keine sauberen Struktur-Ziele"
        row["signal_quality"] = "wait_target_plan"
        row["entry_status"] = "WAIT_FOR_RETEST"
        row["trade_action"] = "WAIT_FOR_RETEST"
        row["alertable_crypto"] = False
        row["pre_breakout_armed"] = False


def _apply_early_mover_signal_state(row: Dict[str, Any], trigger_check: Optional[Dict[str, Any]] = None) -> None:
    """Expose a simple user-facing decision: observe, wait, no trade, or trade now."""
    action = str(row.get("trade_action", "") or "").upper()
    trigger_ok = bool(trigger_check.get("ok")) if isinstance(trigger_check, dict) else bool(row.get("execution_trigger_ok"))
    trigger_reason = str((trigger_check or {}).get("reason", "") or "")
    trigger_block_reason = _early_mover_mail_trigger_block_reason(trigger_check) if isinstance(trigger_check, dict) else None
    effective_trigger_ok = bool(trigger_ok and not trigger_block_reason)

    row["execution_trigger_ok"] = effective_trigger_ok
    if isinstance(trigger_check, dict):
        row["intraday_trigger"] = trigger_check
        if trigger_check.get("execution_score") is not None:
            row["execution_quality_score"] = trigger_check.get("execution_score")
        if trigger_check.get("timeframe"):
            row["execution_timeframe"] = trigger_check.get("timeframe")
        if trigger_check.get("execution_data_age_seconds") is not None:
            row["execution_data_age_seconds"] = trigger_check.get("execution_data_age_seconds")
        if trigger_check.get("last_close") is not None:
            row["execution_price"] = trigger_check.get("last_close")
            row["current_price"] = trigger_check.get("last_close")
        if trigger_check.get("volume_ratio") is not None:
            actual_rvol = trigger_check.get("volume_ratio")
            row["RVOL"] = actual_rvol
            row["rvol"] = actual_rvol
            row["relative_volume"] = actual_rvol
            row["volume_model"] = "exchange_5m_vs_median"
            row["vol_confirmed"] = bool(actual_rvol >= 1.1)
        if trigger_check.get("pre_breakout_score") is not None:
            row["pre_breakout_score"] = trigger_check.get("pre_breakout_score")
            row["pre_breakout_reason"] = trigger_check.get("pre_breakout_reason")
            row["pre_breakout_reasons"] = trigger_check.get("pre_breakout_reasons", [])
            row["pre_breakout_armed_candidate"] = bool(trigger_check.get("pre_breakout_ok"))
            row["pre_breakout_metrics"] = {
                "recent_range_pct": trigger_check.get("recent_range_pct"),
                "recent_change_pct": trigger_check.get("recent_change_pct"),
                "prior_range_pct": trigger_check.get("prior_range_pct"),
                "near_range_high_pct": trigger_check.get("near_range_high_pct"),
                "vwap_hold": trigger_check.get("vwap_hold"),
                "higher_lows": trigger_check.get("higher_lows"),
                "volume_dryup": trigger_check.get("volume_dryup"),
                "volume_ratio": trigger_check.get("volume_ratio"),
                "consecutive_green_5m": trigger_check.get("consecutive_green_5m"),
            }
        if isinstance(trigger_check.get("htf_context"), dict):
            row["htf_context"] = trigger_check.get("htf_context")
        if isinstance(trigger_check.get("liquidity"), dict):
            row["execution_liquidity"] = trigger_check["liquidity"]
        if trigger_check.get("reason") == "thin_orderbook_market_impact":
            flags = row.get("risk_flags") if isinstance(row.get("risk_flags"), list) else []
            flags.extend(["thin_orderbook", "market_impact_risk"])
            row["risk_flags"] = list(dict.fromkeys(flags))
            reasons = row.get("risk_reasons") if isinstance(row.get("risk_reasons"), list) else []
            reasons.append("Orderbuch zu duenn - kleiner Trade kann Kerze bewegen")
            row["risk_reasons"] = list(dict.fromkeys(reasons))
            row["risk_level"] = "HIGH"
        if isinstance(trigger_check.get("vrvp"), dict):
            _apply_early_mover_vrvp_targets(row, trigger_check.get("vrvp"))

    armed_ok, armed_reasons = _early_mover_explosion_armed_state(row, trigger_check)
    explosion_score = _early_mover_explosion_score(row, trigger_check)
    explosion_grade, explosion_grade_label = _score_grade_for_value(explosion_score)
    row["explosion_score"] = explosion_score
    row["explosion_grade"] = explosion_grade
    row["explosion_grade_label"] = explosion_grade_label
    row["pre_breakout_armed"] = armed_ok
    row["pre_breakout_block_reasons"] = armed_reasons

    matched = set((trigger_check or {}).get("matched") or []) if isinstance(trigger_check, dict) else set()
    retest_execution_ok = action != "WAIT_FOR_RETEST" or "retest_hold" in matched
    if action in ("LONG_TRIGGER", "WAIT_FOR_RETEST") and trigger_ok and not trigger_block_reason and retest_execution_ok:
        confirmed_retest = bool(action == "WAIT_FOR_RETEST" and "retest_hold" in matched)
        row["trade_action"] = "LONG_TRIGGER"
        row["trade_signal"] = "JETZT_TRADEN"
        score_txt = f" Score {trigger_check.get('execution_score')}/100" if isinstance(trigger_check, dict) and trigger_check.get("execution_score") is not None else ""
        tf_txt = str(trigger_check.get("timeframe") or "adaptive") if isinstance(trigger_check, dict) else "adaptive"
        row["signal_label"] = f"Jetzt traden: {tf_txt} Execution-Trigger bestaetigt ({trigger_reason or 'ok'}{score_txt})"
        row["signal_quality"] = "tradeable"
        row["entry_status"] = "JETZT_TRADEN"
        row["retest_confirmed"] = confirmed_retest
        row["entry_confirmation_type"] = "RETEST_CONFIRMED" if confirmed_retest else "EXECUTION_TRIGGER_CONFIRMED"
        row["alertable_crypto"] = True
    elif action == "WAIT_FOR_RETEST" and trigger_ok and not retest_execution_ok:
        row["trade_signal"] = "WARTEN"
        row["signal_label"] = "Warten: Breakout erkannt, aber der geplante Retest am Entry fehlt"
        row["signal_quality"] = "wait_retest"
        row["entry_status"] = "WAIT_FOR_RETEST"
        row["alertable_crypto"] = False
    elif action in ("LONG_TRIGGER", "WAIT_FOR_RETEST") and armed_ok:
        row["trade_signal"] = "EXPLOSION_ARMED"
        score_txt = f" Score {explosion_score}/100" if explosion_score is not None else ""
        row["signal_label"] = f"Breakout-Watch: Swing-Struktur passt, Entry erst bei Breakout/Reclaim{score_txt}"
        row["signal_quality"] = "pre_breakout_armed"
        row["entry_status"] = "PRE_BREAKOUT_ARMED"
        row["alertable_crypto"] = False
    elif action in ("LONG_TRIGGER", "WAIT_FOR_RETEST") and trigger_ok and trigger_block_reason:
        row["trade_signal"] = "WARTEN"
        row["signal_label"] = "Warten: Entry-Bestaetigung fehlt; kein Market-Buy"
        row["signal_quality"] = "wait_trigger"
        row["entry_status"] = "WAIT_FOR_TRIGGER"
        row["alertable_crypto"] = False
    elif action == "NO_LONG_CHASE":
        row["trade_signal"] = "NICHT_TRADEN"
        row["signal_label"] = "Nicht traden: Bewegung ist zu weit gelaufen"
        row["signal_quality"] = "no_chase"
        row["entry_status"] = "NICHT_TRADEN"
        row["alertable_crypto"] = False
    elif action == "WAIT_FOR_BTC_CONFIRMATION":
        row["trade_signal"] = "WARTEN"
        row["signal_label"] = "Warten: BTC bestaetigt das Setup noch nicht"
        row["signal_quality"] = "wait"
        row["entry_status"] = "WARTEN"
        row["alertable_crypto"] = False
    elif action == "WAIT_FOR_LIQUIDITY":
        row["trade_signal"] = "WARTEN"
        row["signal_label"] = "Warten: Perp/Orderbuch-Liquiditaet ist zu duenn"
        row["signal_quality"] = "wait"
        row["entry_status"] = "WARTEN"
        row["alertable_crypto"] = False
    elif action == "WAIT_FOR_RETEST":
        row["trade_signal"] = "WARTEN"
        row["signal_label"] = "Warten: Retest nahe Entry fehlt"
        row["signal_quality"] = "wait_retest"
        row["entry_status"] = "WAIT_FOR_RETEST"
        row["alertable_crypto"] = False
    elif action == "WAIT_FOR_CONTINUATION":
        row["trade_signal"] = "WARTEN"
        row["signal_label"] = "Warten: neue Continuation-Flag fehlt"
        row["signal_quality"] = "wait_continuation"
        row["entry_status"] = "WAIT_FOR_CONTINUATION"
        row["alertable_crypto"] = False
    elif action == "LONG_TRIGGER":
        row["trade_signal"] = "WARTEN"
        row["signal_label"] = "Warten: Execution-Trigger fehlt noch"
        row["signal_quality"] = "wait_trigger"
        row["entry_status"] = "WAIT_FOR_TRIGGER"
        row["alertable_crypto"] = False
    else:
        row["trade_signal"] = "BEOBACHTEN"
        row["signal_label"] = "Achtung beobachten: noch kein Trade-Signal"
        row["signal_quality"] = "observe"
        row["entry_status"] = "BEOBACHTEN"
        row["alertable_crypto"] = False

    _clear_early_mover_wait_flags_for_trade_now(row)
    _block_early_mover_trade_on_bad_targets(row)
    row["entry_score"] = _early_mover_entry_score(row)
    if row.get("trade_signal") == "EXPLOSION_ARMED" and row["entry_score"] < _EARLY_MOVER_VISIBLE_MIN_ENTRY_SCORE:
        reasons = list(row.get("pre_breakout_block_reasons") or [])
        reasons.append("entry_score_below_armed_threshold")
        row["pre_breakout_armed"] = False
        row["pre_breakout_block_reasons"] = list(dict.fromkeys(reasons))
        row["trade_signal"] = "WARTEN"
        row["signal_label"] = "Warten: Breakout-Watch blockiert, Entry-Risk ist zu hoch"
        row["signal_quality"] = "wait_trigger"
        row["entry_status"] = "WAIT_FOR_TRIGGER"
        row["alertable_crypto"] = False
        row["entry_score"] = _early_mover_entry_score(row)
    row["entry_score_label"] = _early_mover_entry_score_label(row)


def _reminder_now() -> float:
    return time.time()


def _reminder_iso(ts: Optional[float] = None) -> str:
    return datetime.fromtimestamp(ts or _reminder_now(), timezone.utc).isoformat()


def _reminder_created_epoch(reminder: Dict[str, Any]) -> Optional[float]:
    """Return the reminder creation time as UTC epoch seconds."""
    created_epoch = _alert_float(reminder.get("created_at_epoch"), None)
    if created_epoch is not None and created_epoch > 0:
        return created_epoch
    raw_created = reminder.get("created_at")
    if not raw_created:
        return None
    try:
        created = datetime.fromisoformat(str(raw_created).replace("Z", "+00:00"))
        if created.tzinfo is None:
            created = created.replace(tzinfo=timezone.utc)
        return created.timestamp()
    except (TypeError, ValueError):
        return None


def _load_trade_reminders() -> List[Dict[str, Any]]:
    try:
        if not os.path.exists(_TRADE_REMINDERS_FILE):
            return []
        with open(_TRADE_REMINDERS_FILE, "r", encoding="utf-8") as f:
            raw = json.load(f)
        return raw if isinstance(raw, list) else []
    except Exception as exc:
        print(f"[Reminder] load error: {exc}")
        return []


def _save_trade_reminders(reminders: List[Dict[str, Any]]) -> None:
    tmp_path = f"{_TRADE_REMINDERS_FILE}.{os.getpid()}.tmp"
    try:
        with open(tmp_path, "w", encoding="utf-8") as f:
            json.dump(reminders, f, indent=2, default=_serialize_json)
        os.replace(tmp_path, _TRADE_REMINDERS_FILE)
    except Exception as exc:
        print(f"[Reminder] save error: {exc}")


def _find_early_mover_row(symbol: str) -> Optional[Dict[str, Any]]:
    rows, _ = load_cache_file(EARLY_MOVERS_CACHE, max_age_hours=24)
    wanted = str(symbol or "").upper().replace("USDT", "")
    for row in _flatten_early_mover_rows(rows):
        if not isinstance(row, dict):
            continue
        row_symbol = str(row.get("Symbol", row.get("symbol", row.get("ticker", "")))).upper().replace("USDT", "")
        if row_symbol == wanted:
            return dict(row)
    return None


def _fetch_recent_stock_5m_bars(ticker: str, limit: int = 24) -> List[Dict[str, Any]]:
    if not ticker or not POLYGON_KEY:
        return []
    try:
        try:
            from zoneinfo import ZoneInfo
            today_et = datetime.now(ZoneInfo("America/New_York")).strftime("%Y-%m-%d")
        except Exception:
            today_et = datetime.utcnow().strftime("%Y-%m-%d")
        url = f"https://api.polygon.io/v2/aggs/ticker/{ticker.upper()}/range/5/minute/{today_et}/{today_et}"
        resp = rate_limited_get(url, params={"apiKey": POLYGON_KEY, "adjusted": "true", "sort": "asc", "limit": 500}, timeout=10)
        if resp.status_code != 200:
            return []
        bars = resp.json().get("results", []) or []
        cleaned = []
        for bar in bars:
            cleaned_bar = {
                "open": float(bar.get("o", 0) or 0),
                "high": float(bar.get("h", 0) or 0),
                "low": float(bar.get("l", 0) or 0),
                "close": float(bar.get("c", 0) or 0),
                "volume": float(bar.get("v", 0) or 0),
                "timestamp": bar.get("t"),
            }
            if cleaned_bar["open"] > 0 and cleaned_bar["close"] > 0 and cleaned_bar["high"] >= cleaned_bar["low"]:
                cleaned.append(cleaned_bar)
        return _completed_candles_only(cleaned, "5m")[-limit:]
    except Exception as exc:
        print(f"[Reminder] stock bars error {ticker}: {exc}")
        return []


def _fetch_recent_stock_4h_bars(ticker: str, limit: int = 24) -> List[Dict[str, Any]]:
    """Fetch recent regular-session 4H candles from 30-minute Polygon bars."""
    symbol = str(ticker or "").strip().upper()
    if not symbol or not POLYGON_KEY:
        return []
    now = time.time()
    with _STOCK_SWING_EXECUTION_CACHE_LOCK:
        cached = _STOCK_SWING_EXECUTION_CACHE.get(symbol)
        if cached and now - float(cached.get("timestamp", 0) or 0) < _STOCK_SWING_EXECUTION_CACHE_TTL_SEC:
            return list(cached.get("bars", []))[-limit:]

    try:
        from zoneinfo import ZoneInfo

        timezone_et = ZoneInfo("America/New_York")
        now_et = datetime.now(timezone_et)
        start_date = (now_et - timedelta(days=45)).strftime("%Y-%m-%d")
        end_date = now_et.strftime("%Y-%m-%d")
        url = f"https://api.polygon.io/v2/aggs/ticker/{symbol}/range/30/minute/{start_date}/{end_date}"
        response = rate_limited_get(
            url,
            params={"apiKey": POLYGON_KEY, "adjusted": "true", "sort": "asc", "limit": 5000},
            timeout=12,
        )
        if response.status_code != 200:
            return []
        raw_bars = response.json().get("results", []) or []
        aggregated = aggregate_regular_session_4h_bars(
            raw_bars,
            timezone_et,
            limit=max(limit, 24),
        )
        with _STOCK_SWING_EXECUTION_CACHE_LOCK:
            if len(_STOCK_SWING_EXECUTION_CACHE) >= _STOCK_SWING_EXECUTION_CACHE_MAX:
                oldest = min(
                    _STOCK_SWING_EXECUTION_CACHE,
                    key=lambda key: float(_STOCK_SWING_EXECUTION_CACHE[key].get("timestamp", 0) or 0),
                )
                _STOCK_SWING_EXECUTION_CACHE.pop(oldest, None)
            _STOCK_SWING_EXECUTION_CACHE[symbol] = {"timestamp": now, "bars": aggregated}
        return aggregated[-limit:]
    except Exception as exc:
        print(f"[Alert] stock 4H execution bars error {symbol}: {exc}")
        return []


def _fetch_stock_swing_execution_state(ticker: str) -> Dict[str, Any]:
    return stock_swing_4h_execution_state(_fetch_recent_stock_4h_bars(ticker, limit=24))


def _stock_breakout_freshness_state(
    row: Dict[str, Any],
    *,
    bars: Optional[List[Dict[str, Any]]] = None,
    daily_close_confirmed_mode: bool = False,
) -> Dict[str, Any]:
    """Classify whether a stock breakout is fresh, held, retested, or stale."""
    enriched = dict(row)
    enriched["Breakout_Freshness_Checked"] = True
    ticker = _extract_alert_ticker(enriched)
    breakout_level = _alert_float(_alert_get_any(
        enriched,
        "Breakout_Level",
        "breakout_level",
        "High_20D",
        "High_10D",
    ), None)
    if not ticker or breakout_level is None or breakout_level <= 0:
        enriched["Breakout_Freshness_Status"] = "DATA_UNAVAILABLE"
        enriched["Breakout_Freshness_Reason"] = "missing_breakout_level"
        return enriched

    recent = list(bars) if bars is not None else _fetch_recent_stock_5m_bars(ticker, limit=96)
    recent = [bar for bar in recent if isinstance(bar, dict) and _alert_float(bar.get("close"), None)]
    if len(recent) < 3:
        enriched["Breakout_Freshness_Status"] = "DATA_UNAVAILABLE"
        enriched["Breakout_Freshness_Reason"] = "missing_completed_5m_bars"
        return enriched

    direction = str(_infer_alert_direction(enriched) or "LONG").upper()
    is_short = direction == "SHORT"
    confirmation_level = breakout_level * (0.999 if is_short else 1.001)

    def _confirmed(close: float) -> bool:
        return close <= confirmation_level if is_short else close >= confirmation_level

    crosses: List[int] = []
    for idx in range(1, len(recent)):
        previous_close = float(recent[idx - 1].get("close") or 0)
        current_close = float(recent[idx].get("close") or 0)
        if _confirmed(current_close) and not _confirmed(previous_close):
            crosses.append(idx)

    latest = recent[-1]
    latest_close = float(latest.get("close") or 0)
    latest_high = float(latest.get("high", latest_close) or latest_close)
    latest_low = float(latest.get("low", latest_close) or latest_close)
    latest_open = float(latest.get("open", latest_close) or latest_close)
    latest_range = max(latest_high - latest_low, 1e-9)
    latest_close_pos = (latest_close - latest_low) / latest_range
    distance_pct = (
        ((breakout_level - latest_close) / breakout_level * 100.0)
        if is_short
        else ((latest_close - breakout_level) / breakout_level * 100.0)
    )
    enriched["Breakout_Freshness_Distance_Pct"] = round(distance_pct, 2)

    failed = latest_close > breakout_level * 1.003 if is_short else latest_close < breakout_level * 0.997
    if failed:
        enriched["Breakout_Freshness_Status"] = "FAILED_BREAKOUT"
        enriched["Breakout_Freshness_Reason"] = "latest_close_lost_breakout_level"
        return enriched

    if not crosses:
        if not _confirmed(latest_close):
            status = "NOT_CONFIRMED"
        else:
            status = "HELD_BREAKOUT" if abs(distance_pct) <= 2.0 else "STALE_EXTENSION"
        if daily_close_confirmed_mode and _confirmed(latest_close):
            status = "DAILY_CLOSE_HELD"
        enriched["Breakout_Freshness_Status"] = status
        enriched["Breakout_Freshness_Reason"] = "cross_precedes_available_intraday_window"
        return enriched

    cross_idx = crosses[-1]
    cross_bar = recent[cross_idx]
    latest_ts = _alert_float(latest.get("timestamp"), None)
    cross_ts = _alert_float(cross_bar.get("timestamp"), None)
    age_minutes = None
    if latest_ts is not None and cross_ts is not None:
        age_minutes = max(0.0, (latest_ts - cross_ts) / 60_000.0)
    else:
        age_minutes = float((len(recent) - 1 - cross_idx) * 5)
    enriched["Breakout_Age_Minutes"] = round(age_minutes, 1)

    post_cross = recent[cross_idx + 1:]
    if is_short:
        retest_indices = [
            idx for idx, bar in enumerate(post_cross)
            if float(bar.get("high", 0) or 0) >= breakout_level * 0.995
            and float(bar.get("close", 0) or 0) <= breakout_level * 1.002
        ]
        latest_direction_ok = latest_close <= latest_open and latest_close_pos <= 0.55
    else:
        retest_indices = [
            idx for idx, bar in enumerate(post_cross)
            if float(bar.get("low", 0) or 0) <= breakout_level * 1.005
            and float(bar.get("close", 0) or 0) >= breakout_level * 0.998
        ]
        latest_direction_ok = latest_close >= latest_open and latest_close_pos >= 0.45

    recent_retest = bool(retest_indices) and retest_indices[-1] >= max(0, len(post_cross) - 12)
    if age_minutes <= 60 and latest_direction_ok:
        status = "FRESH_CROSS"
        reason = "latest_confirmed_cross_within_60m"
    elif recent_retest and _confirmed(latest_close):
        status = "RETEST_HELD"
        reason = "breakout_level_retested_and_held"
    elif daily_close_confirmed_mode and _confirmed(latest_close):
        status = "DAILY_CLOSE_HELD"
        reason = "confirmed_daily_close_above_breakout"
    elif age_minutes <= 180 and abs(distance_pct) <= 2.0:
        status = "HELD_BREAKOUT"
        reason = "breakout_holding_without_late_extension"
    else:
        status = "STALE_EXTENSION" if abs(distance_pct) > 2.0 else "STALE_BREAKOUT"
        reason = "initial_breakout_is_no_longer_fresh"

    enriched["Breakout_Freshness_Status"] = status
    enriched["Breakout_Freshness_Reason"] = reason
    return enriched


def _evaluate_stock_reminder(reminder: Dict[str, Any]) -> Dict[str, Any]:
    row = reminder.get("row") if isinstance(reminder.get("row"), dict) else {}
    setup = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}
    ticker = str(reminder.get("ticker", "")).upper()
    direction = str(
        row.get("direction")
        or row.get("Signal_Direction")
        or setup.get("direction")
        or "LONG"
    ).upper()
    entry = _alert_float(
        row.get("entry")
        or row.get("Entry")
        or row.get("entry_price")
        or setup.get("entry")
        or setup.get("main_entry"),
        None,
    )
    stop = _alert_float(
        row.get("stop_loss")
        or row.get("stop")
        or row.get("Stop Loss")
        or setup.get("stop_loss")
        or setup.get("stop"),
        None,
    )
    tp1 = _alert_float(row.get("tp1") or row.get("TP1") or setup.get("tp1"), None)
    tp2 = _alert_float(row.get("tp2") or row.get("TP2") or setup.get("tp2"), None)
    live_rr = _alert_float(
        row.get("live_rr_ratio")
        or row.get("RiskReward")
        or setup.get("live_rr")
        or setup.get("rr_ratio"),
        None,
    )
    if not ticker or entry is None:
        return {"triggered": False, "reason": "missing_stock_entry"}
    bars = _fetch_recent_stock_5m_bars(ticker)
    if len(bars) < 4:
        return {"triggered": False, "reason": "not_enough_stock_5m_bars"}
    last = bars[-1]
    created_epoch = _reminder_created_epoch(reminder)
    last_bar_epoch = _candle_epoch_seconds(last)
    if (
        created_epoch is not None
        and last_bar_epoch is not None
        and last_bar_epoch + 300 <= created_epoch
    ):
        return {"triggered": False, "reason": "waiting_for_new_5m_candle"}
    prev = bars[-8:-1] if len(bars) >= 9 else bars[:-1]
    last_close = last["close"]
    last_open = last["open"]
    last_high = last["high"]
    last_low = last["low"]
    previous_close = float(prev[-1].get("close", last_close) or last_close)
    median_vol = _median_float([b.get("volume", 0) for b in prev], max(last.get("volume", 1), 1))
    vol_ratio = last.get("volume", 0) / max(median_vol, 1)
    close_pos = (last_close - last_low) / max(last_high - last_low, 1e-9)
    if stop is not None:
        risk = (stop - entry) if direction == "SHORT" else (entry - stop)
        if risk <= 0:
            return {"triggered": False, "reason": "invalid_stock_stop_geometry"}
    else:
        risk = max(entry * 0.02, 0.01)
    distance_r = abs(last_close - entry) / max(risk, 1e-9)

    if direction == "SHORT":
        crossed_now = previous_close > entry * 0.998 and last_close <= entry
        trigger = crossed_now and last_close < last_open and close_pos <= 0.45 and vol_ratio >= 1.1 and distance_r <= 0.75
        previously_below = any(float(bar.get("close", entry) or entry) <= entry * 0.998 for bar in prev[-6:])
        near_retest = (
            previously_below
            and last_high >= entry * 0.995
            and last_close <= entry * 1.002
            and close_pos <= 0.45
            and distance_r <= 0.25
        )
        continuation = (
            last_close < min(float(bar.get("low", last_close) or last_close) for bar in prev[-3:])
            and last_close < last_open
            and close_pos <= 0.45
            and vol_ratio >= 1.1
            and distance_r <= 1.0
        )
    else:
        crossed_now = previous_close < entry * 1.002 and last_close >= entry
        trigger = crossed_now and last_close > last_open and close_pos >= 0.55 and vol_ratio >= 1.1 and distance_r <= 0.75
        previously_above = any(float(bar.get("close", entry) or entry) >= entry * 1.002 for bar in prev[-6:])
        near_retest = (
            previously_above
            and last_low <= entry * 1.005
            and last_close >= entry * 0.998
            and close_pos >= 0.55
            and distance_r <= 0.25
        )
        continuation = (
            last_close > max(float(bar.get("high", last_close) or last_close) for bar in prev[-3:])
            and last_close > last_open
            and close_pos >= 0.55
            and vol_ratio >= 1.1
            and distance_r <= 1.0
        )

    condition = str(reminder.get("condition") or "trigger_or_retest").lower()
    if condition == "retest":
        reminder_ready = near_retest
        reminder_reason = "retest_near_entry"
    elif condition == "continuation":
        reminder_ready = continuation
        reminder_reason = "5m_continuation"
    elif condition == "trigger":
        reminder_ready = trigger
        reminder_reason = "5m_trigger"
    else:
        reminder_ready = trigger or near_retest
        reminder_reason = "5m_trigger" if trigger else "retest_near_entry"

    if reminder_ready:
        return {
            "triggered": True,
            "reason": reminder_reason,
            "last_close": round(last_close, 6),
            "distance_to_entry_r": round(distance_r, 2),
            "volume_ratio": round(vol_ratio, 2),
            "entry": entry,
            "stop": stop,
            "tp1": tp1,
            "tp2": tp2,
            "live_rr": live_rr,
        }
    return {
        "triggered": False,
        "reason": "stock_trigger_not_ready",
        "last_close": round(last_close, 6),
        "distance_to_entry_r": round(distance_r, 2),
        "volume_ratio": round(vol_ratio, 2),
    }


def _evaluate_trade_reminder(reminder: Dict[str, Any]) -> Dict[str, Any]:
    asset_type = str(reminder.get("asset_type", "crypto") or "crypto").lower()
    ticker = str(reminder.get("ticker", "")).upper()
    if asset_type == "crypto":
        row = _find_early_mover_row(ticker)
        if not row:
            saved_row = reminder.get("row") if isinstance(reminder.get("row"), dict) else {}
            if not saved_row:
                return {"triggered": False, "reason": "missing_crypto_reminder_data"}
            row = deepcopy(saved_row)
            row.setdefault("Symbol", ticker.replace("USDT", ""))
            row.setdefault("symbol", ticker.replace("USDT", ""))
        trigger_check = _verify_early_mover_intraday_trigger(row)
        _apply_early_mover_signal_state(row, trigger_check)
        created_epoch = _reminder_created_epoch(reminder)
        last_bar_epoch = _alert_float(
            trigger_check.get("last_candle_timestamp") if isinstance(trigger_check, dict) else None,
            None,
        )
        if (
            created_epoch is not None
            and last_bar_epoch is not None
            and last_bar_epoch + 300 <= created_epoch
        ):
            return {"triggered": False, "reason": "waiting_for_new_5m_candle", "check": trigger_check}
        condition = str(reminder.get("condition") or "trigger_or_retest").lower()
        matched = set(trigger_check.get("matched") or []) if isinstance(trigger_check, dict) else set()
        reason = str(trigger_check.get("reason") or "").lower() if isinstance(trigger_check, dict) else ""
        condition_ready = bool(trigger_check.get("ok"))
        if condition == "retest":
            condition_ready = condition_ready and ("retest_hold" in matched or "retest" in reason)
        if condition_ready:
            setup = row.get("trade_setup", {}) if isinstance(row.get("trade_setup"), dict) else {}
            return {
                "triggered": True,
                "reason": trigger_check.get("reason", "crypto_trigger_ready"),
                "last_close": trigger_check.get("last_close"),
                "entry": row.get("entry", setup.get("entry")),
                "stop": row.get("stop_loss", setup.get("stop_loss")),
                "tp1": row.get("tp1", setup.get("tp1")),
                "tp2": row.get("tp2", setup.get("tp2")),
                "live_rr": row.get("live_rr_ratio", setup.get("live_rr")),
                "row": row,
            }
        return {"triggered": False, "reason": trigger_check.get("reason", "crypto_trigger_not_ready"), "check": trigger_check}
    return _evaluate_stock_reminder(reminder)


def _format_reminder_email(reminder: Dict[str, Any], result: Dict[str, Any]) -> str:
    ticker = html.escape(str(reminder.get("ticker", "?")).upper())
    reason = html.escape(str(result.get("reason", "Trigger bereit")).replace("_", " "))
    row = reminder.get("row") if isinstance(reminder.get("row"), dict) else {}
    setup = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}
    entry = _format_alert_price(result.get("entry") or row.get("entry") or setup.get("entry") or setup.get("main_entry"))
    stop = _format_alert_price(result.get("stop") or row.get("stop_loss") or row.get("stop") or setup.get("stop_loss") or setup.get("stop"))
    tp1 = _format_alert_price(result.get("tp1") or row.get("tp1") or setup.get("tp1"))
    tp2 = _format_alert_price(result.get("tp2") or row.get("tp2") or setup.get("tp2"))
    price = _format_alert_price(result.get("last_close"))
    rr = result.get("live_rr") or row.get("live_rr_ratio") or setup.get("live_rr") or setup.get("rr_ratio")
    return f"""
    <html><body style="font-family:Arial,sans-serif;color:#111827">
    <h2 style="color:#059669">Reminder: {ticker} Trigger ist da</h2>
    <p><b>Grund:</b> {reason}</p>
    <table cellpadding="6" cellspacing="0" style="border-collapse:collapse;background:#f8fafc">
      <tr><td>Preis jetzt</td><td><b>{price}</b></td></tr>
      <tr><td>Entry</td><td><b>{entry}</b></td></tr>
      <tr><td>Stop</td><td><b style="color:#dc2626">{stop}</b></td></tr>
      <tr><td>TP1 / TP2</td><td><b style="color:#059669">{tp1} / {tp2}</b></td></tr>
      <tr><td>Live R:R</td><td><b>{rr if rr is not None else '-'}</b></td></tr>
    </table>
    <p style="font-size:12px;color:#64748b">Reminder wurde automatisch deaktiviert. Bitte Chart und Spread vor dem Entry kurz pruefen.</p>
    </body></html>
    """


def _deliver_trade_reminder_email(
    reminder: Dict[str, Any],
    result: Dict[str, Any],
    now: Optional[float] = None,
) -> bool:
    """Deliver a triggered reminder once, with bounded retries on SMTP failure."""
    now = float(now if now is not None else _reminder_now())
    channel = str(reminder.get("channel", "email_browser") or "email_browser").lower()
    if "email" not in channel:
        reminder["email_delivery_status"] = "not_requested"
        return False
    if reminder.get("email_sent_at"):
        reminder["email_delivery_status"] = "sent"
        return True

    owner_email = str(reminder.get("owner_email") or "").strip().lower()
    users = (_load_users() or {}).get("users", {}) if HAS_AUTH else {}
    owner = users.get(owner_email, {}) if isinstance(users, dict) else {}
    alert_email = str(owner.get("alert_email") or owner_email).strip().lower()
    email_enabled = owner.get("email_alerts_enabled", True) is not False
    if not email_enabled or "@" not in alert_email:
        reminder["email_delivery_status"] = "disabled"
        reminder["email_delivery_reason"] = "email_alerts_disabled_or_recipient_missing"
        return False

    attempts = int(reminder.get("email_attempts", 0) or 0)
    if attempts >= 5:
        reminder["email_delivery_status"] = "failed"
        return False
    next_attempt_at = float(reminder.get("next_email_attempt_at", 0) or 0)
    if next_attempt_at > now:
        return False

    row = reminder.get("row") if isinstance(reminder.get("row"), dict) else {}
    signal_rows = [dict(
        row,
        ticker=str(reminder.get("ticker", "")).upper(),
        entry=result.get("entry"),
        stop=result.get("stop"),
        tp1=result.get("tp1"),
        tp2=result.get("tp2"),
    )]
    reason_label = str(result.get("reason") or "Trigger bereit").replace("_", " ").strip()
    sent = _send_email_alert(
        f"Reminder: {reminder.get('ticker', '').upper()} {reason_label}",
        _format_reminder_email(reminder, result),
        bypass_startup_cooldown=True,
        trade_horizon="swing",
        mail_class="trade",
        recipient_emails=[alert_email],
        telegram_text=_safe_format_telegram_rows(signal_rows),
    )
    attempts += 1
    reminder["email_attempts"] = attempts
    reminder["last_email_attempt_at"] = now
    if sent:
        reminder["email_sent_at"] = _reminder_iso(now)
        reminder["email_delivery_status"] = "sent"
        reminder.pop("next_email_attempt_at", None)
        reminder.pop("email_delivery_reason", None)
        _safe_record_alert_signals("trade_reminder", signal_rows)
        return True

    if attempts >= 5:
        reminder["email_delivery_status"] = "failed"
        reminder.pop("next_email_attempt_at", None)
    else:
        reminder["email_delivery_status"] = "retry_pending"
        reminder["next_email_attempt_at"] = now + min(300, 60 * (2 ** (attempts - 1)))
    return False


def _process_trade_reminders_once() -> None:
    now = _reminder_now()
    changed = False
    with _TRADE_REMINDER_LOCK:
        reminders = _load_trade_reminders()
        for reminder in reminders:
            reminder_status = str(reminder.get("status") or "").lower()
            if reminder_status == "triggered":
                before_delivery = (
                    reminder.get("email_delivery_status"),
                    reminder.get("email_attempts"),
                    reminder.get("next_email_attempt_at"),
                    reminder.get("email_sent_at"),
                )
                _deliver_trade_reminder_email(
                    reminder,
                    reminder.get("trigger_result") if isinstance(reminder.get("trigger_result"), dict) else {},
                    now,
                )
                after_delivery = (
                    reminder.get("email_delivery_status"),
                    reminder.get("email_attempts"),
                    reminder.get("next_email_attempt_at"),
                    reminder.get("email_sent_at"),
                )
                changed = changed or before_delivery != after_delivery
                continue
            if reminder_status != "active":
                continue
            owner_email = str(reminder.get("owner_email") or "").strip().lower()
            if not owner_email or "@" not in owner_email:
                # Legacy reminders had no owner and could leak across accounts.
                # Cancel them instead of guessing a recipient.
                reminder["status"] = "cancelled"
                reminder["updated_at"] = _reminder_iso(now)
                reminder["cancellation_reason"] = "missing_owner_email"
                changed = True
                continue
            if now >= float(reminder.get("expires_at", 0) or 0):
                reminder["status"] = "expired"
                reminder["updated_at"] = _reminder_iso(now)
                changed = True
                continue
            last_checked = float(reminder.get("last_checked_at", 0) or 0)
            if now - last_checked < _TRADE_REMINDER_CHECK_SEC:
                continue
            reminder["last_checked_at"] = now
            result = _evaluate_trade_reminder(reminder)
            reminder["last_check"] = result
            reminder["updated_at"] = _reminder_iso(now)
            changed = True
            if result.get("triggered"):
                reminder["status"] = "triggered"
                reminder["triggered_at"] = _reminder_iso(now)
                reminder["trigger_result"] = result
                _deliver_trade_reminder_email(reminder, result, now)
        if changed:
            _save_trade_reminders(reminders)


def _trade_reminder_loop() -> None:
    print("[Reminder] Trade reminder monitor started")
    while _trade_reminder_running:
        try:
            _process_trade_reminders_once()
        except Exception as exc:
            print(f"[Reminder] loop error: {exc}")
        time.sleep(_TRADE_REMINDER_CHECK_SEC)
    print("[Reminder] Trade reminder monitor stopped")


def _start_trade_reminder_loop() -> None:
    global _trade_reminder_running
    if _trade_reminder_running:
        return
    _trade_reminder_running = True
    threading.Thread(target=_trade_reminder_loop, daemon=True).start()


def _stop_trade_reminder_loop() -> None:
    global _trade_reminder_running
    _trade_reminder_running = False


# AUDIT Q-1: Watch-Mail-Klassifikation. Kern-Gruende = "nur warten", keine
# Qualitaetsmaengel. Rows mit irgendeinem Grund ausserhalb der Allowed-Menge
# (Grade/Score/RVOL/Plan/No-Chase/Daten/Liquiditaet/Cooldown) bleiben draussen.
_EARLY_MOVER_WATCH_CORE_REASONS = {
    "early_mover_action_not_alertable",  # nur falls Action == WAIT_FOR_RETEST (separat geprueft)
    "early_mover_retest_not_near_entry",
    "trade_health_wait_for_retest",
    "trade_health_wait_for_trigger",
    "trade_health_wait_for_continuation",
    "trade_health_watch_only",
    "trigger_stale_for_mail",
}
_EARLY_MOVER_WATCH_ALLOWED_REASONS = _EARLY_MOVER_WATCH_CORE_REASONS | {
    "trade_health_score_below_80",
    "early_mover_wait_entry_confirmation",
}
_EARLY_MOVER_WATCH_REASON_LABELS = {
    "trigger_stale_for_mail": "Trigger abgelaufen - neu bewerten",
    "early_mover_action_not_alertable": "Auf Retest warten",
    "early_mover_retest_not_near_entry": "Retest-Zone noch nicht erreicht",
    "trade_health_wait_for_retest": "Auf Retest warten",
    "trade_health_wait_for_trigger": "Auf Trigger warten",
    "trade_health_wait_for_continuation": "Auf Continuation warten",
    "trade_health_watch_only": "Nur beobachten",
    "early_mover_wait_entry_confirmation": "Entry-Bestaetigung abwarten",
}


def _early_mover_watch_mail_reasons(row: Dict[str, Any], state: Dict[str, Any]) -> List[str]:
    """AUDIT Q-1: Warte-Gruende einer Row, die NUR wegen Wait/Watch (nicht
    wegen Qualitaetsmaengeln) aus der JETZT-Mail gefallen ist. Leer = Row
    gehoert nicht in die Watch-Mail."""
    reasons = list(state.get("suppression_reasons") or [])
    if not reasons:
        return []
    core = [reason for reason in reasons if reason in _EARLY_MOVER_WATCH_CORE_REASONS]
    if not core:
        return []
    if any(reason not in _EARLY_MOVER_WATCH_ALLOWED_REASONS for reason in reasons):
        return []
    action = str(row.get("trade_action", row.get("entry_status", "")) or "").upper()
    if "early_mover_action_not_alertable" in reasons and action != "WAIT_FOR_RETEST":
        return []
    return core


def _send_early_mover_watch_alerts(watch_rows: List[Dict[str, Any]], now: Optional[float] = None) -> bool:
    """AUDIT Q-1: Watch-Kandidaten (Retest/Wait) als separate, klar markierte
    Beobachtungs-Mail (mail_class="watch") statt in der JETZT-Trade-Mail."""
    if not watch_rows:
        return False
    now = now or time.time()
    remaining = _email_dedupe_remaining(_EARLY_MOVER_WATCH_DIGEST_KEY, _EARLY_MOVER_WATCH_DIGEST_DEDUPE_SEC, now)
    if remaining > 0:
        _record_email_event(
            "Crypto Early Mover WATCH Digest",
            "skipped",
            f"watch_digest_cooldown_active:{remaining}s candidates={len(watch_rows)}",
        )
        return False

    def _fmt_num(value, suffix="", decimals=1, default="-"):
        number = _alert_float(value)
        if number is None:
            return default
        return f"{number:.{decimals}f}{suffix}"

    items = sorted(
        watch_rows,
        key=lambda item: ({"S": 4, "A+": 3, "A": 2}.get(str(item.get("grade", "")).upper(), 0), _alert_float(item.get("score"), 0) or 0),
        reverse=True,
    )[:_EARLY_MOVER_MAX_EMAIL_ROWS]

    rows = ""
    for item in items:
        symbol = html.escape(str(item.get("symbol", "")))
        name = html.escape(str(item.get("name") or ""))
        wait_text = html.escape(str(item.get("wait_reason") or "Auf Trigger/Retest warten"))
        rows += (
            f'<tr><td style="padding:8px;border-bottom:1px solid #eee"><b>{symbol}</b><br><span style="color:#777">{name}</span></td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee;color:#b45309"><b>{wait_text}</b><br><span style="color:#777">{html.escape(str(item.get("exchange") or ""))}</span></td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{html.escape(str(item.get("grade", "")))} / {html.escape(str(item.get("score", "")))}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{_format_alert_price(item.get("price"))}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">Entry {_format_alert_price(item.get("entry"))}<br>Stop {_format_alert_price(item.get("stop"))}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">TP1 {_format_alert_price(item.get("tp1"))}<br>TP2 {_format_alert_price(item.get("tp2"))}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{_fmt_num(item.get("live_rr"), "R", 2)}<br><span style="color:#777">Dist {_fmt_num(item.get("distance_r"), "R", 2)}</span></td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">24h {_fmt_num(item.get("change24"), "%")}<br>V/MCap {_fmt_num(item.get("vol_mcap"), "%")}</td></tr>'
        )

    body = f'''<html><body style="font-family:Arial,sans-serif;max-width:980px;margin:0 auto">
    <h2 style="color:#b45309">Crypto Retest-Zonen (Watchlist)</h2>
    <div style="background:#fffbeb;border:1px solid #fcd34d;border-radius:10px;padding:12px;margin:12px 0;color:#78350f;font-size:14px">
      <b>BEOBACHTUNG — kein Einstiegssignal.</b> Warte auf Trigger/Retest.
      Diese Setups erfuellen Grade/Score/Plan-Qualitaet, sind aber im Versandmoment NICHT handelbar.
    </div>
    <p style="color:#666">{_mail_timestamp_dual()} | Top {len(items)} von {len(watch_rows)} Watch-Kandidat(en)</p>
    <table style="width:100%;border-collapse:collapse;font-size:13px">
    <tr style="background:#fffbeb"><th style="padding:8px;text-align:left">Coin</th>
    <th style="padding:8px;text-align:left">Aktion (Warte-Grund)</th><th style="padding:8px;text-align:left">Grade/Score</th>
    <th style="padding:8px;text-align:left">Preis</th><th style="padding:8px;text-align:left">Entry/Stop</th>
    <th style="padding:8px;text-align:left">TP1/TP2</th><th style="padding:8px;text-align:left">Live R</th>
    <th style="padding:8px;text-align:left">Kontext</th></tr>
    {rows}</table>
    <p style="color:#999;font-size:12px;margin-top:20px">Watch-Digest-Cooldown: {_EARLY_MOVER_WATCH_DIGEST_DEDUPE_SEC // 3600}h. Nur Kandidaten, deren Grade/Score/RVOL/Plan passen und die ausschliesslich wegen Wait-/Retest-/Frische-Gates nicht JETZT handelbar sind.</p>
    </body></html>'''
    if not _email_dedupe_claim(
        _EARLY_MOVER_WATCH_DIGEST_KEY,
        _EARLY_MOVER_WATCH_DIGEST_DEDUPE_SEC,
        now=now,
    ):
        _record_email_event(
            "Crypto Early Mover WATCH Digest",
            "skipped",
            f"watch_digest_claimed_by_parallel_sender:candidates={len(watch_rows)}",
        )
        return False
    try:
        sent = _send_email_alert(
            f"Crypto Retest-Zonen ({len(items)} Kandidaten)",
            body,
            trade_horizon="swing",
            mail_class="watch",
            mail_channel="crypto",
        )
    except Exception:
        _email_dedupe_release(_EARLY_MOVER_WATCH_DIGEST_KEY, claimed_at=now)
        raise
    if sent:
        _email_dedupe_mark(_EARLY_MOVER_WATCH_DIGEST_KEY, now=now)
        for item in items:
            key = item.get("key")
            if key:
                _EMAIL_COOLDOWN[key] = now
                _email_dedupe_mark(key, now=now)
    else:
        _email_dedupe_release(_EARLY_MOVER_WATCH_DIGEST_KEY, claimed_at=now)
    return bool(sent)


def _revalidate_early_mover_mail_candidate(
    candidate: Dict[str, Any],
    now_ts: Optional[float] = None,
) -> Dict[str, Any]:
    """Fail closed unless the exact execution contract still supports the plan."""
    item = dict(candidate or {})
    venue = str(item.get("venue") or item.get("exchange") or "").lower().strip()
    contract = str(item.get("contract_symbol") or "").upper().strip()
    if not venue or not contract:
        return {"ok": False, "reason": "final_exact_contract_missing"}

    try:
        bars = _fetch_exchange_candles_any(contract, venue, timeframe="5m", count=24)
    except Exception:
        bars = []
    completed = _completed_candles_only(bars or [], "5m", now_ts=now_ts)
    if len(completed) < 2:
        return {"ok": False, "reason": "final_5m_data_missing"}
    freshness = _crypto_candle_freshness(
        completed,
        "5m",
        now_ts=now_ts,
        max_age_bars=2,
    )
    if not freshness.get("known") or not freshness.get("fresh"):
        return {"ok": False, "reason": "final_5m_data_stale"}

    current = _alert_float(completed[-1].get("close"))
    prior_price = _alert_float(item.get("price"))
    entry = _alert_float(item.get("entry"))
    stop = _alert_float(item.get("stop"))
    tp1 = _alert_float(item.get("tp1"))
    tp2 = _alert_float(item.get("tp2"))
    if any(value is None for value in (current, entry, stop, tp1, tp2)):
        return {"ok": False, "reason": "final_trade_levels_missing"}
    if current <= 0 or prior_price is None or prior_price <= 0:
        return {"ok": False, "reason": "final_price_invalid"}
    price_gap_pct = abs(current - prior_price) / prior_price * 100.0
    if price_gap_pct > 12.0:
        return {"ok": False, "reason": "final_contract_price_mismatch"}
    if not (stop < current < tp1 < tp2):
        if current >= tp1:
            return {"ok": False, "reason": "final_tp1_already_reached"}
        if current <= stop:
            return {"ok": False, "reason": "final_stop_already_breached"}
        return {"ok": False, "reason": "final_level_geometry_invalid"}

    plan_risk = entry - stop
    live_risk = current - stop
    if plan_risk <= 0 or live_risk <= 0:
        return {"ok": False, "reason": "final_risk_invalid"}
    live_rr = (0.5 * (tp1 - current) + 0.5 * (tp2 - current)) / live_risk
    distance_r = abs(current - entry) / plan_risk
    if live_rr < _EARLY_MOVER_MIN_ALERT_RR:
        return {"ok": False, "reason": "final_live_rr_too_low"}
    if distance_r > _EARLY_MOVER_VISIBLE_MAX_DISTANCE_R:
        return {"ok": False, "reason": "final_entry_distance_too_far"}
    if (
        str(item.get("action") or "").upper() == "WAIT_FOR_RETEST"
        and distance_r > _EARLY_MOVER_RETEST_MAX_DISTANCE_R
    ):
        return {"ok": False, "reason": "final_retest_distance_too_far"}

    item.update({
        "price": current,
        "live_rr": round(live_rr, 3),
        "distance_r": round(distance_r, 3),
        "final_quote_source": f"{venue}:{contract}:5m_close",
        "final_quote_age_seconds": freshness.get("age_seconds"),
        "final_quote_price_gap_pct": round(price_gap_pct, 3),
    })
    return {"ok": True, "candidate": item}


def _send_early_mover_long_alerts(payload: Dict[str, Any]) -> bool:
    """Mail swing Early-Mover long/retest candidates; no-chase rows stay UI-only."""
    now = time.time()
    swing_mode = _scanner_uses_swing_horizon("early_movers")
    candidates = []
    watch_rows: List[Dict[str, Any]] = []  # AUDIT Q-1: Kandidaten fuer die separate Watch-Mail
    suppressed: Dict[str, int] = {}
    seen_keys = set()

    for row in _flatten_early_mover_rows(payload):
        trigger_check: Dict[str, Any] = {
            "ok": False,
            "reason": "swing_structure_plan",
            "timeframe": "swing",
            "execution_score": row.get("entry_score"),
        }
        if swing_mode:
            row = dict(row)
            row["_alert_horizon"] = "swing"
            row.setdefault("signal_label", "Crypto Swing-Setup: Struktur/Entry-Zone passt, kein 5m-Zwang.")
            row.setdefault("signal_quality", "swing_setup")
        else:
            trigger_check = _verify_early_mover_intraday_trigger(row)
            trigger_block_reason = _early_mover_mail_trigger_block_reason(trigger_check)
            if trigger_block_reason:
                suppressed[trigger_block_reason] = suppressed.get(trigger_block_reason, 0) + 1
                continue
            _apply_early_mover_signal_state(row, trigger_check)

        state = _classify_alert_candidate("early_movers", row, now)
        if not state["alertable_now"]:
            # AUDIT Q-1: Rows, die NUR wegen Wait/Retest/Frische warten muessen
            # (Qualitaet passt), wandern in die separate Watch-Mail.
            watch_reason_codes = _early_mover_watch_mail_reasons(row, state)
            if watch_reason_codes and state["cooldown_key"] not in seen_keys:
                seen_keys.add(state["cooldown_key"])
                watch_setup = row.get("trade_setup", {}) if isinstance(row.get("trade_setup"), dict) else {}
                watch_rows.append({
                    "key": state["cooldown_key"],
                    "symbol": state["ticker"],
                    "name": row.get("Name", row.get("name", "")),
                    "grade": state["grade"],
                    "score": state["score"],
                    "price": row.get("Price", state["price"]),
                    "wait_reason": _EARLY_MOVER_WATCH_REASON_LABELS.get(
                        watch_reason_codes[0], watch_reason_codes[0]
                    ),
                    "entry": row.get("entry", watch_setup.get("entry")),
                    "stop": row.get("stop_loss", row.get("stop", watch_setup.get("stop_loss", watch_setup.get("stop")))),
                    "tp1": row.get("tp1", watch_setup.get("tp1")),
                    "tp2": row.get("tp2", watch_setup.get("tp2")),
                    "live_rr": row.get("live_rr_ratio", watch_setup.get("live_rr")),
                    "distance_r": row.get("distance_to_entry_r", watch_setup.get("distance_to_entry_r")),
                    "change24": row.get("Change24h"),
                    "vol_mcap": row.get("VolMCapRatio"),
                    "exchange": row.get("PerpChartExchange", row.get("Exchange", "")),
                })
            for reason in state["suppression_reasons"]:
                suppressed[reason] = suppressed.get(reason, 0) + 1
            continue
        key = state["cooldown_key"]
        if key in seen_keys:
            continue
        seen_keys.add(key)
        setup = row.get("trade_setup", {}) if isinstance(row.get("trade_setup"), dict) else {}
        btc_context = row.get("btc_context", setup.get("btc_context", {}))
        if not isinstance(btc_context, dict):
            btc_context = {}
        candidates.append({
            "key": key,
            "symbol": state["ticker"],
            "name": row.get("Name", row.get("name", "")),
            "grade": state["grade"],
            "score": state["score"],
            "price": row.get("Price", state["price"]),
            "action": row.get("trade_action", setup.get("trade_action", "")),
            "entry": row.get("entry", setup.get("entry")),
            "stop": row.get("stop_loss", row.get("stop", setup.get("stop_loss", setup.get("stop")))),
            "tp1": row.get("tp1", setup.get("tp1")),
            "tp2": row.get("tp2", setup.get("tp2")),
            "live_rr": row.get("live_rr_ratio", setup.get("live_rr")),
            "distance_r": row.get("distance_to_entry_r", setup.get("distance_to_entry_r")),
            "change24": row.get("Change24h"),
            "vol_mcap": row.get("VolMCapRatio"),
            "btc_24h": btc_context.get("btc_24h"),
            "alpha_24h": btc_context.get("alpha_24h"),
            "exchange": row.get("PerpChartExchange", row.get("Exchange", "")),
            "trigger": trigger_check,
            "execution_score": trigger_check.get("execution_score"),
            "execution_timeframe": trigger_check.get("timeframe"),
            "horizon": "SWING" if swing_mode else "INTRADAY",
            "coin_id": row.get("ID", row.get("coin_id")),
            "venue": row.get(
                "PerpChartExchange",
                row.get("BestExchange", row.get("Exchange", "")),
            ),
            "contract_symbol": row.get(
                "PerpChartSymbol",
                row.get("PerpMatchSymbol"),
            ),
        })

    revalidated_candidates = []
    for candidate in candidates:
        validation = _revalidate_early_mover_mail_candidate(candidate, now_ts=now)
        if not validation.get("ok"):
            reason = str(validation.get("reason") or "final_revalidation_failed")
            suppressed[reason] = suppressed.get(reason, 0) + 1
            continue
        revalidated_candidates.append(validation["candidate"])
    candidates = revalidated_candidates

    if not candidates:
        if suppressed:
            _record_email_event("Crypto Early Mover LONG Alert", "skipped", f"no_active_long_setups:{suppressed}")
        _send_early_mover_watch_alerts(watch_rows, now=now)  # AUDIT Q-1
        return False
    digest_remaining = _email_dedupe_remaining(_EARLY_MOVER_DIGEST_KEY, _EARLY_MOVER_DIGEST_DEDUPE_SEC, now)
    if digest_remaining > 0:
        _record_email_event(
            "Crypto Early Mover LONG Alert",
            "skipped",
            f"digest_cooldown_active:{digest_remaining}s candidates={len(candidates)}",
        )
        _send_early_mover_watch_alerts(watch_rows, now=now)  # AUDIT Q-1
        return False

    def _fmt_num(value, suffix="", decimals=1, default="-"):
        number = _alert_float(value)
        if number is None:
            return default
        return f"{number:.{decimals}f}{suffix}"

    def _candidate_rank(item: Dict[str, Any]) -> Tuple[float, float, float]:
        grade_rank = {"S": 4, "A+": 3, "A": 2}.get(str(item.get("grade", "")).upper(), 0)
        trigger_rank = 1 if str(item.get("action", "")).upper() == "LONG_TRIGGER" else 0
        score = _alert_float(item.get("score"), 0) or 0
        return (grade_rank, trigger_rank, score)

    candidates = sorted(candidates, key=_candidate_rank, reverse=True)
    email_rows = candidates[:_EARLY_MOVER_MAX_EMAIL_ROWS]

    rows = ""
    for item in email_rows:
        symbol = html.escape(str(item["symbol"]))
        name = html.escape(str(item["name"] or ""))
        action = html.escape(str(item["action"] or "LONG"))
        exchange = html.escape(str(item["exchange"] or ""))
        trigger = item.get("trigger", {}) if isinstance(item.get("trigger"), dict) else {}
        trigger_text = html.escape("Swing-Struktur" if item.get("horizon") == "SWING" else str(trigger.get("reason", "execution_trigger")))
        exec_score = _fmt_num(item.get("execution_score"), "/100", 0)
        exec_tf = html.escape(str(item.get("execution_timeframe") or trigger.get("timeframe") or "swing"))
        volume_ratio = _fmt_num(trigger.get("volume_ratio"), "x", 2)
        rows += (
            f'<tr><td style="padding:8px;border-bottom:1px solid #eee"><b>{symbol}</b><br><span style="color:#777">{name}</span></td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{action}<br><span style="color:#777">{exchange} {exec_tf}</span><br><span style="color:#059669">{trigger_text}{"" if item.get("horizon") == "SWING" else f" ({volume_ratio}, EQ {exec_score})"}</span></td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{html.escape(str(item["grade"]))} / {html.escape(str(item["score"]))}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{_format_alert_price(item["price"])}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">Entry {_format_alert_price(item["entry"])}<br>Stop {_format_alert_price(item["stop"])}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">TP1 {_format_alert_price(item["tp1"])}<br>TP2 {_format_alert_price(item["tp2"])}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{_fmt_num(item["live_rr"], "R", 2)}<br><span style="color:#777">Dist {_fmt_num(item["distance_r"], "R", 2)}</span></td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">24h {_fmt_num(item["change24"], "%")}<br>V/MCap {_fmt_num(item["vol_mcap"], "%")}<br>BTC {_fmt_num(item["btc_24h"], "%")} / Alpha {_fmt_num(item["alpha_24h"], "%")}</td></tr>'
        )

    body = f'''<html><body style="font-family:Arial,sans-serif;max-width:980px;margin:0 auto">
    <h2 style="color:#059669">Crypto Early Mover LONG Digest</h2>
    <p style="color:#666">{_mail_timestamp_dual()} | Top {len(email_rows)} von {len(candidates)} Crypto-Swing Long/Retest Setup(s)</p>
    <table style="width:100%;border-collapse:collapse;font-size:13px">
    <tr style="background:#ecfdf5"><th style="padding:8px;text-align:left">Coin</th>
    <th style="padding:8px;text-align:left">Aktion</th><th style="padding:8px;text-align:left">Grade/Score</th>
    <th style="padding:8px;text-align:left">Preis</th><th style="padding:8px;text-align:left">Entry/Stop</th>
    <th style="padding:8px;text-align:left">TP1/TP2</th><th style="padding:8px;text-align:left">Live R</th>
    <th style="padding:8px;text-align:left">Kontext</th></tr>
    {rows}</table>
    <p style="color:#999;font-size:12px;margin-top:20px">Digest-Cooldown: {_EARLY_MOVER_DIGEST_DEDUPE_SEC // 3600}h. Swing-Default: Nur Score >= {_ALERT_MIN_SCORE}, Grade S/A/A+, Live R:R >= {_EARLY_MOVER_MIN_ALERT_RR}, kein BTC-Gegenwind, kein No-Chase, keine Partial-Daten, unverpasster TP1 und saubere Strukturziele. Intraday-5m ist optionaler separater Modus, nicht Pflicht fuer diese Swing-Mail.</p>
    </body></html>'''
    if not _email_dedupe_claim(
        _EARLY_MOVER_DIGEST_KEY,
        _EARLY_MOVER_DIGEST_DEDUPE_SEC,
        now=now,
    ):
        _record_email_event(
            "Crypto Early Mover LONG Alert",
            "skipped",
            f"digest_claimed_by_parallel_sender:candidates={len(candidates)}",
        )
        _send_early_mover_watch_alerts(watch_rows, now=now)
        return False
    try:
        sent = _send_email_alert(f"Crypto Early Mover LONG Digest: {len(email_rows)}/{len(candidates)} Setup(s)", body, trade_horizon="swing", mail_class="trade", telegram_text=_safe_format_telegram_rows(email_rows), mail_channel="crypto")  # AUDIT H-3 / H-2
    except Exception:
        _email_dedupe_release(_EARLY_MOVER_DIGEST_KEY, claimed_at=now)
        raise
    if sent:
        _email_dedupe_mark(_EARLY_MOVER_DIGEST_KEY, now=now)
        for item in email_rows:
            _EMAIL_COOLDOWN[item["key"]] = now
            _email_dedupe_mark(item["key"], now=now)
        # Signal-Tracking: nur die tatsaechlich gemailten 🚨-Rows (Watch-Mail loggt nicht).
        _safe_record_alert_signals("early_movers", email_rows)
    else:
        _email_dedupe_release(_EARLY_MOVER_DIGEST_KEY, claimed_at=now)
    _send_early_mover_watch_alerts(watch_rows, now=now)  # AUDIT Q-1
    return bool(sent)


def _send_early_mover_armed_alerts(payload: Dict[str, Any]) -> bool:
    """Armed/watch mails are deliberately disabled.

    GMX showed the failure mode clearly: a pre-breakout watch can reverse before
    confirmation. Users need actionable trade alerts, not FOMO prompts.
    """
    _record_email_event(
        "Crypto Explosion Armed Alert",
        "skipped",
        "armed_watch_mail_hard_disabled_trade_signals_only",
    )
    return False


def _extract_long_entry_fields(row: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "change_pct": _alert_float(_alert_get_any(row, "change_pct", "Change_Pct", "Change%", "Change %", "Änderung%", "todaysChangePerc")),
        "gap_pct": _alert_float(_alert_get_any(row, "gap_pct", "Gap_Pct", "Gap%", "Gap %")),
        "close_pos": _alert_float(_alert_get_any(row, "close_pos", "Close_Position", "Close Position", "Range_Pos", "Range Position")),
        "open_to_current_pct": _alert_float(_alert_get_any(row, "open_to_current_pct", "Open_To_Current_Pct", "intraday_change_pct")),
        "latest_bar_change_pct": _alert_float(row.get("latest_bar_change_pct")),
        "latest_bar_close_pos": _alert_float(row.get("latest_bar_close_pos")),
        "extension_atr": _alert_float(row.get("Extension_ATR", row.get("extension_atr"))),
        "upper_wick_pct": _alert_float(row.get("Upper_Wick_Pct", row.get("upper_wick_pct"))),
        "rvol": _alert_float(row.get("rvol", row.get("RVOL"))),
        "mdr_tag": str(row.get("mdr_tag", "") or "").upper(),
    }


def _long_continuation_ok(fields: Dict[str, Any]) -> bool:
    close_pos = fields.get("close_pos")
    latest_change = fields.get("latest_bar_change_pct")
    latest_close_pos = fields.get("latest_bar_close_pos")
    rvol = fields.get("rvol")
    mdr_tag = fields.get("mdr_tag", "")

    latest_available = latest_change is not None and latest_close_pos is not None
    latest_ok = (
        latest_available
        and (
            latest_change >= -0.05
            or latest_close_pos >= 0.55
        )
    )
    volume_ok = rvol is None or rvol >= 1.2
    holding_highs = close_pos is not None and close_pos >= 0.78
    mdr_ok = "MDR" in mdr_tag and "CRASH" not in mdr_tag and close_pos is not None and close_pos >= 0.65
    return (holding_highs and latest_ok and volume_ok) or (mdr_ok and latest_ok)


def _long_entry_rule_reasons(row: Dict[str, Any]) -> List[str]:
    """Block late long mails only when the move is fading, not when it is cleanly continuing."""
    direction = str(row.get("Signal_Direction", row.get("direction", "")) or "").lower()
    if "short" in direction:
        return []
    fields = _extract_long_entry_fields(row)
    reasons: List[str] = []
    change = fields["change_pct"]
    close_pos = fields["close_pos"]
    open_to_current = fields["open_to_current_pct"]
    latest_change = fields["latest_bar_change_pct"]
    latest_close_pos = fields["latest_bar_close_pos"]
    extension_atr = fields["extension_atr"]

    latest_red_fade = (
        latest_change is not None
        and latest_close_pos is not None
        and latest_change < -0.15
        and latest_close_pos < 0.45
    )
    latest_missing = latest_change is None or latest_close_pos is None
    intraday_red_fade = open_to_current is not None and open_to_current < -0.25
    not_holding_highs = change is not None and change > 3 and close_pos is not None and close_pos < 0.55
    extended = (change is not None and change >= 12) or (extension_atr is not None and extension_atr >= 4.0)
    hard_extended = (change is not None and change >= 30) or (extension_atr is not None and extension_atr >= 6.0)
    continuation_ok = _long_continuation_ok(fields)

    if latest_red_fade:
        reasons.append("latest_5m_red_fade")
    if latest_missing:
        reasons.append("fresh_5m_state_missing_wait_trigger")
    if intraday_red_fade:
        reasons.append("current_candle_red_fade")
    if not_holding_highs and (extended or latest_red_fade or intraday_red_fade):
        reasons.append("not_holding_highs_after_up_move")
    if hard_extended and not continuation_ok:
        reasons.append("hard_extended_long_wait_retest")
    elif extended and latest_missing:
        reasons.append("fresh_5m_state_missing_wait_retest")
    elif extended and (latest_red_fade or intraday_red_fade or not_holding_highs):
        reasons.append("extended_long_fading_wait_retest")
    # AUDIT 2026-07-29 (PBT): gleiche Orts-Logik wie im Aktien-Swing —
    # >= 2 ATR Tagesmove UND Einstieg <= 1% unterm Tageshoch = Top-Kauf.
    # None-sicher: Rows ohne ATR-/Tages-Metadaten behalten Bestandsverhalten.
    if _top_entry_gate_active(row, change):
        reasons.append("top_entry_extended_wait_retest")
    return reasons


# AUDIT 2026-07-28 (RITM/GSK/KO/HLN): Tages-Extension in ATR statt nur %.
# Die %-Schwellen (8/12%) lassen einen Korridor: +6,2% bei 2,1% ATR ist ein
# ~2,9-ATR-Tag — der Move ist gelaufen, bevor die Mail kommt, und TP1 liegt
# naeher als die Strecke, die der Kurs heute schon gelaufen ist.
_SWING_DAY_MOVE_EXTENDED_ATR = 2.5   # ab hier: kein JETZT, Retest abwarten
_SWING_DAY_MOVE_HARD_ATR = 3.5       # ab hier: Move erschoepft, NO_CHASE
_SWING_PREMARKET_GAP_MIN_PCT = 3.0   # Gap, ab dem "vorboeslich gelaufen" gilt
# Session bestaetigt nach dem Gap faktisch nichts mehr (<= +0.5% seit Open):
_SWING_PREMARKET_GAP_MAX_SESSION_FOLLOW_PCT = 0.5
# AUDIT 2026-07-29 (PBT): Orts-Gate gegen Top-Kaeufe nach gelaufenem Tag.
# +9,6% bei 4,0% ATR = 2,4 ATR rutschte unter dem 2,5er-Gate durch, der Entry
# lag 0,4% unterm Tageshoch — ein Top-Kauf nach >= 2 ATR gelaufenem Move.
# Tag >= 2 ATR UND Preis <= 1% am Tages-Extrem => kein JETZT. Frische
# Breakouts (< 2 ATR) und Ruecksetzer > 1% vom Extrem (Retest) bleiben frei.
_SWING_TOP_ENTRY_DAY_MOVE_ATR = 2.0
_SWING_TOP_ENTRY_MAX_DIST_FROM_EXTREME_PCT = 1.0
# AUDIT 2026-07-31 (BHC): Alle bisherigen Gates messen nur den HEUTIGEN Tag.
# BHC kam mit +5,1% (~1,2 ATR) durch, obwohl der Move ueber 3 Tage gelaufen
# war (~+38% in 5 Tagen ≈ 8,8 ATR) — die fette Kerze war von gestern. Der
# Mehrtages-Anker |Change_5D| / ATR_% sieht genau das; der Vortag-Anker
# faengt "gestern gelaufen + heute am Hoch" (Tag-2-Top-Kauf).
_SWING_MULTI_DAY_EXTENDED_ATR = 5.0   # 5-Tage-Move >= 5 ATR: Retest abwarten
_SWING_MULTI_DAY_HARD_ATR = 7.0       # >= 7 ATR: Move erschoepft, kein Chase
_SWING_PREVDAY_RUN_ATR = 2.5          # gestriger Tag >= 2,5 ATR UND heute am Hoch


def _swing_day_move_atr(row: Dict[str, Any], change_pct: Optional[float]) -> Optional[float]:
    """Tagesbewegung in ATR-Einheiten (|change_%| / ATR_%).

    None, wenn ATR oder Preis in der Row fehlen — Legacy-/Test-Rows ohne
    ATR-Metadaten behalten das bisherige Verhalten.
    """
    if change_pct is None:
        return None
    atr = _alert_atr_value(row)
    price = _alert_float(_extract_alert_price(row), None)
    if not atr or not price or price <= 0:
        return None
    atr_pct = (atr / price) * 100.0
    if atr_pct <= 0:
        return None
    return abs(change_pct) / atr_pct


def _swing_multi_day_move_atr(row: Dict[str, Any]) -> Optional[float]:
    """5-Tage-Bewegung in ATR-Einheiten (|Change_5D| / ATR_%).

    AUDIT 2026-07-31 (BHC): Tages-Gates sind blind fuer Moves, die ueber
    2-5 Tage laufen. Change_5D wird in den history_metrics aus kompletten
    Daily-Bars gerechnet (Schluss vor 5 Bars -> aktueller Preis) und liegt
    auf der Scanner-Row. None, wenn Change_5D/ATR/Preis fehlen — solche Rows
    behalten das bisherige Verhalten (fail-open wie die Tages-Gates).
    """
    change_5d = _alert_float(_alert_get_any(row, "Change_5D", "change_5d"), None)
    if change_5d is None:
        return None
    atr = _alert_atr_value(row)
    price = _alert_float(_extract_alert_price(row), None)
    if not atr or not price or price <= 0:
        return None
    atr_pct = (atr / price) * 100.0
    if atr_pct <= 0:
        return None
    return abs(change_5d) / atr_pct


def _swing_top_entry_distance_pct(row: Dict[str, Any], *, short: bool = False) -> Optional[float]:
    """Abstand des aktuellen Preises vom Tages-Extrem in % (0 = am Extrem).

    Long: Abstand unterm Tageshoch; Short: Abstand ueberm Tagestief.
    Liegt der Preis ueber/unter dem hinterlegten Extrem (veraltete Tagesdaten),
    zaehlt das als 0 — der Kurs IST am Extrem. None, wenn Preis oder
    Tages-Extrem in der Row fehlen.
    """
    price = _alert_float(_extract_alert_price(row), None)
    if not price or price <= 0:
        return None
    if short:
        day_low = _alert_float(_alert_get_any(row, "Day_Low", "day_low", "DayLow", "Low", "low"))
        if not day_low or day_low <= 0:
            return None
        return max(0.0, (price - day_low) / day_low * 100.0)
    day_high = _alert_float(_alert_get_any(row, "Day_High", "day_high", "DayHigh", "High", "high"))
    if not day_high or day_high <= 0:
        return None
    return max(0.0, (day_high - price) / day_high * 100.0)


def _top_entry_gate_active(row: Dict[str, Any], change_pct: Optional[float], *, short: bool = False) -> bool:
    """PBT-Muster: Tag schon >= 2 ATR gelaufen UND Einstieg <= 1% am Tages-Extrem."""
    day_move_atr = _swing_day_move_atr(row, change_pct)
    if day_move_atr is None or day_move_atr < _SWING_TOP_ENTRY_DAY_MOVE_ATR:
        return False
    dist = _swing_top_entry_distance_pct(row, short=short)
    return dist is not None and dist <= _SWING_TOP_ENTRY_MAX_DIST_FROM_EXTREME_PCT


def _stock_swing_rule_reasons(row: Dict[str, Any]) -> List[str]:
    """Daily/swing timing gate for generic stock strategy alerts.

    Swing strategy mails must not depend on 1m/5m candles. They still need a
    sane entry location, so we gate them with daily extension, ATR stretch and
    whether the move is holding its range.
    """
    direction = str(row.get("Signal_Direction", row.get("direction", "")) or "").lower()
    if "short" in direction:
        return []
    fields = _extract_long_entry_fields(row)
    reasons: List[str] = []
    change = fields["change_pct"]
    gap_pct = fields.get("gap_pct")
    close_pos = fields["close_pos"]
    open_to_current = fields["open_to_current_pct"]
    extension_atr = fields["extension_atr"]
    upper_wick_pct = fields.get("upper_wick_pct")
    rvol = fields.get("rvol")
    strategy_name = str(row.get("Strategy") or row.get("strategy") or "").lower()
    execution_status = str(row.get("Swing_4H_Execution_Status") or "").upper()

    extended = (change is not None and change >= 12.0) or (extension_atr is not None and extension_atr >= 4.0)
    hard_extended = (change is not None and change >= 25.0) or (extension_atr is not None and extension_atr >= 6.0)
    soft_extended_without_volume = change is not None and change >= 8.0 and (rvol is None or rvol < 1.5)
    fading_daily = open_to_current is not None and open_to_current < -0.5
    not_holding_highs = change is not None and change > 3 and close_pos is not None and close_pos < 0.55
    is_gap_momentum_long = "gap momentum long" in strategy_name or "gap up" in strategy_name
    is_momentum_breakout_long = "momentum breakout long" in strategy_name
    is_meaningful_gap = is_gap_momentum_long and (
        (gap_pct is not None and gap_pct >= 3.0)
        or (change is not None and change >= 6.0)
    )
    is_momentum_gap_overlap = is_momentum_breakout_long and (
        (gap_pct is not None and gap_pct >= 3.0)
        or (change is not None and change >= 7.0 and rvol is not None and rvol >= 2.0)
    )

    if hard_extended:
        reasons.append("swing_hard_extended_no_chase")
    elif extended:
        reasons.append("swing_extended_wait_retest")
    elif soft_extended_without_volume:
        reasons.append("swing_extended_without_volume_wait_retest")
    # Tagesmove relativ zur eigenen Volatilitaet (RITM: +6,2% bei 2,1% ATR
    # ≈ 2,9 ATR — unter allen %-Schwellen, aber der Tag ist gelaufen).
    day_move_atr = _swing_day_move_atr(row, change)
    if day_move_atr is not None:
        if day_move_atr >= _SWING_DAY_MOVE_HARD_ATR:
            reasons.append("swing_day_move_exhausted_no_chase")
        elif day_move_atr >= _SWING_DAY_MOVE_EXTENDED_ATR:
            reasons.append("swing_day_move_extended_wait_retest")
    # BHC 2026-07-31: heute +5,1% (~1,2 ATR) sieht frisch aus, war aber Tag 3
    # eines ~8,8-ATR-Moves — die fette Kerze lief gestern. Der Mehrtages-Anker
    # (Change_5D in ATR) misst die Woche, nicht nur den Tag.
    multi_day_atr = _swing_multi_day_move_atr(row)
    if multi_day_atr is not None:
        if multi_day_atr >= _SWING_MULTI_DAY_HARD_ATR:
            reasons.append("swing_multi_day_exhausted_no_chase")
        elif multi_day_atr >= _SWING_MULTI_DAY_EXTENDED_ATR:
            reasons.append("swing_multi_day_extended_wait_retest")
    # Vortag-Anker: gestriger Tag >= 2,5 ATR UND heute weiter gruen UND Preis
    # klebt am Tageshoch = Tag-2-Top-Kauf (BHC: +30% gestern, +5% heute,
    # Entry 0,3% unterm Hoch). Faengt auch Faelle mit duenner 5d-History ab.
    prevday_pct = _alert_float(_alert_get_any(row, "Vortag_Pct", "vortag_pct"), None)
    prevday_atr = _swing_day_move_atr(row, prevday_pct)
    if (
        prevday_atr is not None
        and prevday_atr >= _SWING_PREVDAY_RUN_ATR
        and change is not None
        and change > 0
    ):
        _dist = _swing_top_entry_distance_pct(row)
        if _dist is not None and _dist <= _SWING_TOP_ENTRY_MAX_DIST_FROM_EXTREME_PCT:
            reasons.append("swing_prevday_run_top_entry_wait_retest")
    # PBT 2026-07-29: 2,4 ATR rutschte unter dem 2,5er-Gate durch, aber der
    # Entry 0,4% unterm Tageshoch war ein Top-Kauf. Das Orts-Gate faengt den
    # 2,0-2,5-ATR-Korridor, sobald der Preis am Tages-Extrem klebt.
    if _top_entry_gate_active(row, change):
        reasons.append("swing_top_entry_extended_wait_retest")
    # Gap lief vorbörslich, die Session bestaetigt nichts: kein JETZT.
    # (Bisherige Gap-Gates greifen nur bei "Gap Momentum Long"-Strategienamen;
    # RITM lief als "Momentum Breakout Long" daran vorbei.)
    if (
        gap_pct is not None
        and gap_pct >= _SWING_PREMARKET_GAP_MIN_PCT
        and open_to_current is not None
        and open_to_current <= _SWING_PREMARKET_GAP_MAX_SESSION_FOLLOW_PCT
    ):
        reasons.append("swing_gap_done_premarket_wait_retest")
    if fading_daily:
        reasons.append("swing_current_candle_fading")
    if not_holding_highs and (extended or soft_extended_without_volume or fading_daily):
        reasons.append("swing_not_holding_highs_after_move")
    if is_meaningful_gap:
        if open_to_current is not None and open_to_current < 0.25:
            reasons.append("swing_gap_not_holding_open_wait_retest")
        if close_pos is not None and close_pos < 0.72:
            reasons.append("swing_gap_not_holding_upper_range_wait_retest")
        if upper_wick_pct is not None and upper_wick_pct >= 38:
            reasons.append("swing_gap_wick_rejection_wait_retest")
    if is_momentum_gap_overlap:
        momentum_type = str(
            row.get("Momentum_Breakout_Type")
            or row.get("momentum_breakout_type")
            or ""
        ).upper()
        continuation_status = str(
            row.get("Breakout_Continuation_Status")
            or row.get("breakout_continuation_status")
            or ""
        ).upper()
        continuation_score = _alert_float(
            row.get("Breakout_Continuation_Score", row.get("breakout_continuation_score")),
            None,
        )
        if momentum_type == "TREND_RECLAIM" and change is not None and change >= 6.0:
            reasons.append("swing_momentum_trend_reclaim_gap_wait_retest")
        if open_to_current is not None and open_to_current < 0.25:
            reasons.append("swing_momentum_not_holding_open_wait_retest")
        if close_pos is not None and close_pos < 0.72:
            reasons.append("swing_momentum_not_holding_upper_range_wait_retest")
        if upper_wick_pct is not None and upper_wick_pct >= 34:
            reasons.append("swing_momentum_wick_rejection_wait_retest")
        if continuation_status and continuation_status != "CONTINUATION_OK":
            reasons.append("swing_momentum_breakout_quality_wait_retest")
        elif continuation_score is not None and continuation_score < 78:
            reasons.append("swing_momentum_breakout_quality_wait_retest")
    if execution_status in {"WAIT_RETEST", "RUN_EXTENDED"}:
        reasons.append("swing_4h_extended_run_wait_retest")
    elif execution_status == "WAIT_RECLAIM":
        reasons.append("swing_4h_rejection_wait_reclaim")
    elif execution_status == "DATA_UNAVAILABLE":
        reasons.append("swing_4h_state_missing_wait_trigger")
    return list(dict.fromkeys(reasons))


def _stock_swing_short_rule_reasons(row: Dict[str, Any]) -> List[str]:
    """Daily/swing timing gate for bearish stock scanners.

    A short swing can start after a weak close or failed breakdown, but it should
    not blindly chase a completed one-day collapse or short into a green reclaim.
    """
    fields = _extract_bear_short_fields(row)
    reasons: List[str] = []
    change = fields["change_pct"]
    close_pos = fields["close_pos"]
    open_to_current = fields["open_to_current_pct"]
    rvol = fields["rvol"]

    if change is None:
        reasons.append("missing_current_drop")
    elif change > -2.0:
        reasons.append("swing_short_not_down_enough")
    elif change <= -22.0:
        reasons.append("swing_short_drop_too_extended_no_chase")
    elif change <= -12.0:
        reasons.append("swing_short_extended_wait_retest")
    elif change <= -8.0:
        reasons.append("swing_short_drop_extended_wait_failed_reclaim")

    # Symmetrisch zur Long-Seite: Drop relativ zur eigenen Volatilitaet.
    # (BELFB -7,7% bei 7,7% ATR = 1,0 ATR bleibt frei — ein normaler Tag.)
    day_move_atr = _swing_day_move_atr(row, change)
    if day_move_atr is not None:
        if day_move_atr >= _SWING_DAY_MOVE_HARD_ATR:
            reasons.append("swing_short_day_move_exhausted_no_chase")
        elif day_move_atr >= _SWING_DAY_MOVE_EXTENDED_ATR:
            reasons.append("swing_short_day_move_extended_wait_retest")
    # Orts-Gate symmetrisch (PBT): >= 2 ATR Drop UND Preis <= 1% ueberm
    # Tagestief = Boden-Short nach gelaufenem Move.
    if _top_entry_gate_active(row, change, short=True):
        reasons.append("swing_short_bottom_entry_extended_wait_retest")

    if open_to_current is not None and open_to_current > 0.5:
        reasons.append("swing_short_current_candle_reclaim")
    if close_pos is not None and close_pos > 0.55:
        reasons.append("swing_short_not_closing_weak")
    if rvol is not None and rvol < 0.7:
        reasons.append("rvol_below_bear_threshold")
    return list(dict.fromkeys(reasons))


def _is_late_us_regular_session(
    market_status: Optional[Dict[str, Any]] = None,
    now_utc: Optional[datetime] = None,
) -> bool:
    """True during the final regular-session minutes where fresh entries are easy to chase."""
    status = market_status or {}
    if str(status.get("session") or "").upper() != "US_REGULAR":
        return False
    # Unit tests often stub only the status. Real production status includes
    # market_time; without it we avoid time-dependent test behavior.
    if not status.get("market_time") and "unit-test" in str(status.get("reason", "")).lower():
        return False
    try:
        if now_utc is None:
            now_utc = datetime.now(timezone.utc)
        elif now_utc.tzinfo is None:
            now_utc = now_utc.replace(tzinfo=timezone.utc)
        from zoneinfo import ZoneInfo
        now_et = now_utc.astimezone(ZoneInfo("America/New_York"))
        close_et = now_et.replace(hour=16, minute=0, second=0, microsecond=0)
        minutes_to_close = (close_et - now_et).total_seconds() / 60.0
        return 0 <= minutes_to_close <= 15
    except Exception:
        return False


_STOCK_MOMENTUM_MAIL_MIN_MEDIAN_DOLLAR_VOLUME_20D = 2_000_000.0
# AUDIT 2026-07-28 (HLN): Mindest-Volatilitaetsbudget fuer Swing-Mails.
# Unter ~2% Tages-ATR traegt ein Setup seine Kosten nicht (TP1 ~1.8xATR < 4%
# brutto) — die Cents-Ziele wirken "lachhaft", weil das Vehikel sich nicht
# bewegt, nicht weil die Mathematik falsch waere.
_STOCK_STRATEGY_MAIL_MIN_ATR_PCT = 2.0


def _stock_strategy_mail_quality_state(
    row: Dict[str, Any],
    *,
    daily_close_confirmed_mode: bool = False,
    market_status: Optional[Dict[str, Any]] = None,
    now_utc: Optional[datetime] = None,
) -> tuple[bool, str]:
    """Extra quality gate for automatic stock strategy mails.

    The manual strategy scanner may show broad candidates. The automatic mail
    should be stricter: a "Momentum Breakout Long" mail must be an actual
    breakout setup, not just a trend reclaim that scored well on raw momentum.
    """
    strategy_name = str(row.get("Strategy") or row.get("strategy") or "").lower()
    is_long_context = "short" not in strategy_name and str(
        row.get("Signal_Direction", row.get("direction", row.get("Signal", ""))) or ""
    ).lower() != "short"
    if is_long_context:
        execution_status = str(row.get("Swing_4H_Execution_Status") or "").upper()
        if execution_status in {"WAIT_RETEST", "RUN_EXTENDED"}:
            return False, "stock_swing_mail_blocked_4h_extended_run"
        if execution_status == "WAIT_RECLAIM":
            return False, "stock_swing_mail_blocked_4h_rejection"
        if execution_status == "DATA_UNAVAILABLE":
            return False, "stock_swing_mail_blocked_missing_4h_state"

    # Volatilitaetsbudget (Long UND Short): ohne ausreichend Tages-ATR ist
    # kein Swing-Setup mail-wuerdig. Rows ohne ATR-Metadaten: Bestandsverhalten.
    atr_value = _alert_atr_value(row)
    price_value = _alert_float(_extract_alert_price(row), None)
    if atr_value and price_value and price_value > 0:
        atr_pct = (atr_value / price_value) * 100.0
        if atr_pct < _STOCK_STRATEGY_MAIL_MIN_ATR_PCT:
            return False, "stock_swing_mail_blocked_low_volatility_budget"

    if "momentum breakout long" not in strategy_name:
        return True, ""

    # A single high-RVOL day must not make an ordinarily thin stock look safe
    # enough for an automatic "trade now" mail. Production strategy rows carry
    # completed-daily-history metadata; legacy/test rows without that metadata
    # retain their existing behavior.
    has_liquidity_history_metadata = any(
        key in row
        for key in ("History_OK", "MedianDollarVol20", "median_dollar_volume_20d")
    )
    if has_liquidity_history_metadata:
        if not bool(row.get("History_OK")):
            return False, "momentum_mail_blocked_missing_liquidity_history"
        median_dollar_volume_20d = _alert_float(
            row.get("MedianDollarVol20", row.get("median_dollar_volume_20d"))
        )
        if median_dollar_volume_20d is None or median_dollar_volume_20d <= 0:
            return False, "momentum_mail_blocked_missing_liquidity_history"
        if median_dollar_volume_20d < _STOCK_MOMENTUM_MAIL_MIN_MEDIAN_DOLLAR_VOLUME_20D:
            return False, "momentum_mail_blocked_thin_baseline_liquidity"

    breakout_type = str(
        row.get("Momentum_Breakout_Type")
        or row.get("momentum_breakout_type")
        or ""
    ).upper()
    if not breakout_type:
        return False, "momentum_mail_blocked_missing_breakout_type"

    freshness_checked = bool(row.get("Breakout_Freshness_Checked"))
    freshness_status = str(
        row.get("Breakout_Freshness_Status")
        or row.get("breakout_freshness_status")
        or ""
    ).upper()
    if freshness_checked and freshness_status in {"DATA_UNAVAILABLE", "NOT_CONFIRMED", "FAILED_BREAKOUT"}:
        return False, "momentum_breakout_freshness_unconfirmed"
    if freshness_checked and freshness_status in {"STALE_BREAKOUT", "STALE_EXTENSION"}:
        return False, "momentum_breakout_stale_wait_trigger"

    continuation_status = str(
        row.get("Breakout_Continuation_Status")
        or row.get("breakout_continuation_status")
        or ""
    ).upper()
    continuation_score = _alert_float(
        row.get("Breakout_Continuation_Score", row.get("breakout_continuation_score")),
        None,
    )
    fakeout_risk = str(
        row.get("Breakout_Fakeout_Risk")
        or row.get("breakout_fakeout_risk")
        or ""
    ).upper()
    close_pos = _alert_float(_alert_get_any(row, "Close_Position", "close_pos", "Range_Pos", "Range Position"))
    rvol = _alert_float(_alert_get_any(row, "RVOL", "rvol"))
    upper_wick = _alert_float(row.get("Upper_Wick_Pct", row.get("upper_wick_pct")))
    breakout10 = _alert_float(row.get("Breakout_10D_Pct", row.get("breakout_10d_pct")))
    breakout20 = _alert_float(row.get("Breakout_20D_Pct", row.get("breakout_20d_pct")))
    setup = row.get("trade_setup") if isinstance(row.get("trade_setup"), dict) else {}
    price = _alert_float(_alert_get_any(
        row,
        "Preis",
        "price",
        "current_price",
        default=setup.get("entry") or setup.get("Entry"),
    ))
    day_high = _alert_float(_alert_get_any(row, "Day_High", "day_high", "DayHigh", "High", "high"))
    day_open = _alert_float(_alert_get_any(row, "Day_Open", "day_open", "Open", "open"))
    change_pct = _alert_float(_alert_get_any(row, "Change_Pct", "change_pct", "Change%", "Change %", "todaysChangePerc"))
    open_to_current_pct = _alert_float(_alert_get_any(row, "open_to_current_pct", "Open_To_Current_Pct", "intraday_change_pct"))
    if open_to_current_pct is None and price is not None and day_open is not None and day_open > 0:
        open_to_current_pct = ((price - day_open) / day_open) * 100.0
    tp1 = _alert_float(_alert_get_any(
        row,
        "TP1",
        "tp1",
        "TakeProfit1",
        "target1",
        default=setup.get("tp1") or setup.get("TP1"),
    ))

    if breakout_type == "TREND_RECLAIM":
        return False, "momentum_mail_blocked_trend_reclaim_not_breakout"
    if breakout_type not in {"20D_HIGH_BREAKOUT", "10D_HIGH_BREAKOUT", "RANGE_BREAKOUT"}:
        return False, "momentum_mail_blocked_unknown_breakout_type"
    if continuation_status and continuation_status != "CONTINUATION_OK":
        return False, "momentum_mail_blocked_breakout_continuation_watch"
    if continuation_score is not None and continuation_score < 78:
        return False, "momentum_mail_blocked_breakout_quality_low"
    if fakeout_risk in {"HIGH", "CRITICAL"}:
        return False, "momentum_mail_blocked_fakeout_risk"
    if upper_wick is not None and upper_wick >= 38:
        return False, "momentum_mail_blocked_upper_wick"
    if close_pos is not None and close_pos < 0.65:
        return False, "momentum_mail_blocked_not_holding_upper_range"
    if rvol is not None and rvol < 1.5:
        return False, "momentum_mail_blocked_rvol_below_breakout_floor"
    if (
        not daily_close_confirmed_mode
        and _is_late_us_regular_session(market_status=market_status, now_utc=now_utc)
    ):
        return False, "momentum_mail_blocked_late_session_without_daily_close"
    if day_high is not None and tp1 is not None and day_high > 0 and tp1 > 0:
        if day_high >= tp1 * 0.995:
            return False, "momentum_mail_blocked_tp1_already_touched_intraday"
    pullback_from_high_pct = None
    if price is not None and day_high is not None and price > 0 and day_high > price:
        pullback_from_high_pct = (day_high - price) / day_high * 100.0
        if pullback_from_high_pct >= 5.0 and (close_pos is None or close_pos < 0.86):
            return False, "momentum_mail_blocked_spike_rejected_from_high"
    move_pct = max(
        [v for v in (change_pct, open_to_current_pct) if isinstance(v, (int, float))],
        default=None,
    )
    if move_pct is not None and move_pct >= 8.0:
        clean_big_breakout = (
            breakout_type == "20D_HIGH_BREAKOUT"
            and (continuation_score is not None and continuation_score >= 92)
            and (close_pos is not None and close_pos >= 0.88)
            and (upper_wick is None or upper_wick <= 12)
            and (rvol is None or rvol >= 2.0)
            and (pullback_from_high_pct is None or pullback_from_high_pct <= 3.0)
        )
        if not clean_big_breakout:
            return False, "momentum_mail_blocked_late_intraday_chase"
    if breakout_type == "RANGE_BREAKOUT":
        near_real_breakout = (
            (breakout10 is not None and breakout10 >= -1.0)
            or (breakout20 is not None and breakout20 >= -2.0)
        )
        if not near_real_breakout:
            return False, "momentum_mail_blocked_range_not_near_breakout_high"

    return True, ""


def _long_entry_quality(row: Dict[str, Any]) -> str:
    reasons = _long_entry_rule_reasons(row)
    if reasons:
        if any(reason.endswith("wait_retest") for reason in reasons):
            return "WAIT_RETEST"
        return "FADE_WATCH"
    fields = _extract_long_entry_fields(row)
    extended = (
        (fields["change_pct"] is not None and fields["change_pct"] >= 12)
        or (fields["extension_atr"] is not None and fields["extension_atr"] >= 4.0)
    )
    if extended and _long_continuation_ok(fields):
        return "CONTINUATION_OK"
    return "TRADEABLE"


def _extract_bear_short_fields(row: Dict[str, Any]) -> Dict[str, Optional[float]]:
    """Fields used to decide whether a bear row is still a tradeable short entry."""
    return {
        "change_pct": _alert_float(_alert_get_any(row, "change_pct", "Change_Pct", "Change%", "Change %", "Änderung%", "todaysChangePerc")),
        "close_pos": _alert_float(_alert_get_any(row, "close_pos", "Close_Position", "Close Position", "Range_Pos", "Range Position")),
        "open_to_current_pct": _alert_float(_alert_get_any(row, "open_to_current_pct", "Open_To_Current_Pct", "intraday_change_pct")),
        "latest_bar_change_pct": _alert_float(row.get("latest_bar_change_pct")),
        "latest_bar_close_pos": _alert_float(row.get("latest_bar_close_pos")),
        "latest_bar_age_seconds": _alert_float(row.get("latest_bar_age_seconds")),
        "rvol": _alert_float(row.get("rvol", row.get("RVOL"))),
        "score": _alert_float(row.get("score", row.get("Score"))),
    }


def _bear_short_rule_reasons(row: Dict[str, Any]) -> List[str]:
    """Prevent Bear Scanner mails from becoming FOMO shorts after the move is gone."""
    fields = _extract_bear_short_fields(row)
    reasons: List[str] = []
    change = fields["change_pct"]
    close_pos = fields["close_pos"]
    open_to_current = fields["open_to_current_pct"]
    latest_bar_change = fields["latest_bar_change_pct"]
    latest_bar_close_pos = fields["latest_bar_close_pos"]
    latest_bar_age_seconds = fields["latest_bar_age_seconds"]
    rvol = fields["rvol"]
    latest_missing = latest_bar_change is None or latest_bar_close_pos is None

    if change is None:
        reasons.append("missing_current_drop")
    elif change > -3:
        reasons.append("not_down_enough_for_breakdown")
    elif change <= -12:
        reasons.append("drop_too_extended_no_chase")

    if open_to_current is not None and open_to_current > 0.2:
        reasons.append("current_candle_green_reclaim")
    if close_pos is not None and close_pos > 0.45:
        reasons.append("not_closing_near_low")
    if latest_missing:
        reasons.append("fresh_5m_state_missing_wait_trigger")
    intraday_state_status = str(row.get("intraday_state_status") or "").lower()
    if intraday_state_status and intraday_state_status != "fresh":
        reasons.append(f"fresh_5m_state_{intraday_state_status}")
    elif latest_bar_age_seconds is not None and latest_bar_age_seconds > 15 * 60:
        reasons.append("fresh_5m_state_stale")
    if (
        latest_bar_change is not None
        and latest_bar_close_pos is not None
        and latest_bar_change > 0.15
        and latest_bar_close_pos > 0.55
    ):
        reasons.append("latest_5m_green_reclaim")
    if rvol is not None and rvol < 1.0:
        reasons.append("rvol_below_bear_threshold")
    # AUDIT 2026-07-29 (PBT): Orts-Gate symmetrisch zur Long-Seite — >= 2 ATR
    # Drop UND Preis <= 1% ueberm Tagestief = Boden-Short nach gelaufenem Move.
    # None-sicher: Rows ohne ATR-/Tages-Metadaten behalten Bestandsverhalten.
    if _top_entry_gate_active(row, change, short=True):
        reasons.append("bottom_entry_extended_wait_retest")

    return reasons


def _bear_entry_quality(row: Dict[str, Any]) -> str:
    reasons = _bear_short_rule_reasons(row)
    if not reasons:
        return "TRADEABLE"
    if "drop_too_extended_no_chase" in reasons:
        return "NO_CHASE"
    if "current_candle_green_reclaim" in reasons:
        return "RECLAIM_WATCH"
    return "WATCH"


def _bear_crash_rule_reasons(row: Dict[str, Any]) -> List[str]:
    """Crash alert is informational: active flush only, not a normal short-entry gate."""
    reasons: List[str] = []
    # Das Bottom-Orts-Gate gehoert zum Short-EINSTIEG, nicht zur Crash-Meldung:
    # ein aktiver Flush liegt per Definition am Tagestief und darf hier nicht
    # zusaetzlich unterdrueckt werden.
    hard_blocks = set(_bear_short_rule_reasons(row)) - {
        "drop_too_extended_no_chase",
        "bottom_entry_extended_wait_retest",
    }
    reasons.extend(sorted(hard_blocks))
    fields = _extract_bear_short_fields(row)
    change = fields["change_pct"]
    close_pos = fields["close_pos"]
    open_to_current = fields["open_to_current_pct"]
    rvol = fields["rvol"]
    if change is None:
        if "missing_current_drop" not in reasons:
            reasons.append("missing_current_drop")
    elif change > -10:
        reasons.append("crash_drop_too_small")
    elif change <= -30:
        reasons.append("crash_drop_too_extended")
    if open_to_current is not None and open_to_current > 0.2:
        reasons.append("current_candle_green_reclaim")
    if close_pos is not None and close_pos > 0.35:
        reasons.append("crash_not_pressing_lows")
    if rvol is not None and rvol < 1.2:
        reasons.append("crash_rvol_below_threshold")
    latest_bar_change = fields["latest_bar_change_pct"]
    latest_bar_close_pos = fields["latest_bar_close_pos"]
    if (
        latest_bar_change is not None
        and latest_bar_close_pos is not None
        and latest_bar_change > 0.15
        and latest_bar_close_pos > 0.55
    ):
        reasons.append("latest_5m_green_reclaim")
    return list(dict.fromkeys(reasons))


def _bear_crash_alert_ok(row: Dict[str, Any]) -> bool:
    return not _bear_crash_rule_reasons(row)


def _classify_crash_alert_candidate(row: Dict[str, Any], now: Optional[float] = None) -> Dict[str, Any]:
    now = now or time.time()
    ticker = _extract_alert_ticker(row)
    grade = _extract_alert_grade(row)
    score = _alert_float(_extract_alert_score(row), 0) or 0
    rvol = _extract_alert_rvol(row)
    reasons: List[str] = []

    if not ticker:
        reasons.append("missing_ticker")
    asset_exclusion_reason = None
    if ticker:
        common_stock_universe, common_stock_source = _load_common_stock_universe()
        asset_exclusion_reason = _stock_alert_asset_exclusion_reason(
            ticker,
            common_stock_universe=common_stock_universe,
            universe_source=common_stock_source,
            require_reference=common_stock_universe is None,
        )
        if asset_exclusion_reason:
            reasons.append("non_common_stock_product")
    if grade not in _ALERT_TOP_GRADES:
        reasons.append("grade_below_alert_threshold")
    if score < _ALERT_MIN_SCORE:
        reasons.append("score_below_alert_threshold")
    reasons.extend(_bear_crash_rule_reasons(row))

    levels = _alert_trade_levels(row)
    if not levels.get("valid"):
        reasons.append("invalid_trade_plan")
        for err in levels.get("errors", [])[:2]:
            reasons.append(f"trade_{err}")
    elif levels.get("estimated"):
        reasons.append("estimated_trade_plan")
    elif not _alert_trade_plan_ok(row):
        reasons.append("trade_rr_below_threshold")
    reasons.extend(_alert_trade_health_reasons(row, "bear"))

    dedupe_key = f"crash_stock_{datetime.now().strftime('%Y%m%d')}_{ticker}" if ticker else ""
    dedupe_remaining = _email_dedupe_remaining(dedupe_key, _CRASH_ALERT_DEDUPE_SEC, now) if dedupe_key else 0
    if dedupe_remaining > 0:
        reasons.append("persistent_dedupe_active")

    return {
        "ticker": ticker,
        "grade": grade,
        "score": score,
        "price": _extract_alert_price(row),
        "rvol": rvol,
        "cooldown_key": dedupe_key,
        "persistent_dedupe_remaining_seconds": int(dedupe_remaining),
        "asset_exclusion_reason": asset_exclusion_reason,
        "alertable_now": not reasons,
        "suppression_reasons": list(dict.fromkeys(reasons)),
        **_alert_decision_from_reasons("crash", reasons),
    }


def _fetch_bear_latest_intraday_state(ticker: str) -> Dict[str, Any]:
    """Fetch the latest 5m candle so Bear mails do not chase into a live bounce."""
    if not ticker or not POLYGON_KEY:
        return {}
    try:
        bars = _fetch_recent_stock_5m_bars(ticker, limit=24)
        if not bars:
            return {"intraday_state_status": "missing"}
        bar = bars[-1]
        open_ = bar.get("open", 0) or 0
        high = bar.get("high", 0) or 0
        low = bar.get("low", 0) or 0
        close = bar.get("close", 0) or 0
        if not open_ or not close:
            return {"intraday_state_status": "invalid"}
        bar_open_ts = _candle_epoch_seconds(bar)
        if bar_open_ts is None:
            return {"intraday_state_status": "timestamp_missing"}
        bar_age_seconds = max(0.0, time.time() - (bar_open_ts + 5 * 60))
        state_status = "fresh" if bar_age_seconds <= 15 * 60 else "stale"
        change_pct = ((close - open_) / open_) * 100
        close_pos = ((close - low) / (high - low)) if high > low else 0.5
        return {
            "latest_bar_change_pct": round(change_pct, 2),
            "latest_bar_close_pos": round(close_pos, 3),
            "latest_bar_timestamp": bar.get("timestamp"),
            "latest_bar_age_seconds": round(bar_age_seconds, 1),
            "intraday_state_status": state_status,
        }
    except Exception as exc:
        print(f"[Bear] 5m state error {ticker}: {exc}")
        return {"intraday_state_status": "error"}


def _build_bear_structure_trade_setup(
    *,
    entry: float,
    day_high: float,
    day_low: float,
    day_open: float,
    ma20: Optional[float] = None,
    ma50: Optional[float] = None,
    low_20d: Optional[float] = None,
    low_60d: Optional[float] = None,
    change_pct: Optional[float] = None,
) -> Optional[Dict[str, Any]]:
    """Build a native short plan from reclaim invalidation and lower support.

    This keeps Bear/Crash mails from using synthetic R-only targets while still
    giving active flushes a concrete plan when structure is available.
    """
    try:
        entry = float(entry or 0)
        day_high = float(day_high or entry)
        day_low = float(day_low or entry)
        day_open = float(day_open or entry)
    except (TypeError, ValueError):
        return None
    if entry <= 0:
        return None

    day_range = max(day_high - day_low, entry * 0.025)
    buffer = max(day_range * 0.06, entry * 0.004)
    min_risk = max(entry * 0.012, day_range * 0.12)
    max_risk = entry * (0.10 if change_pct is not None and change_pct <= -10 else 0.08)

    stop_candidates: List[tuple[float, str]] = []
    if day_open > entry:
        stop_candidates.append((day_open + buffer, "day_open_reclaim"))
    if ma20 and entry < float(ma20) <= entry * 1.14:
        stop_candidates.append((float(ma20) + buffer, "ma20_reclaim"))
    if ma50 and entry < float(ma50) <= entry * 1.16:
        stop_candidates.append((float(ma50) + buffer, "ma50_reclaim"))
    if day_high > entry:
        stop_candidates.append((day_high + buffer, "day_high_reclaim"))

    stop = None
    stop_source = "intraday_reclaim_zone"
    for level, label in sorted(stop_candidates, key=lambda item: item[0] - entry):
        risk_candidate = level - entry
        if min_risk <= risk_candidate <= max_risk:
            stop = level
            stop_source = label
            break
    if stop is None:
        fallback_risk = min(max(day_range * 0.35, entry * 0.025), max_risk)
        if fallback_risk < min_risk:
            return None
        stop = entry + fallback_risk

    risk = stop - entry
    if risk <= 0:
        return None

    target_candidates: List[tuple[float, str]] = []
    if 0 < day_low < entry:
        target_candidates.append((day_low, "day_low_liquidity"))
    if low_20d and 0 < float(low_20d) < entry:
        target_candidates.append((float(low_20d), "20d_low_support"))
    if low_60d and 0 < float(low_60d) < entry:
        target_candidates.append((float(low_60d), "60d_low_support"))
    target_candidates.extend([
        (entry - day_range * 0.80, "intraday_measured_move"),
        (entry - day_range * 1.30, "extended_measured_move"),
    ])

    def _pick_short_target(min_rr: float, max_below: float, fallback_rr: float, fallback_label: str) -> tuple[float, str]:
        min_price = entry - risk * min_rr
        valid = sorted(
            {round(p, 6): label for p, label in target_candidates if 0 < p < max_below}.items(),
            reverse=True,
        )
        for level, label in valid:
            if level <= min_price:
                return level, label
        return max(0.01, entry - risk * fallback_rr), fallback_label

    tp1, tp1_source = _pick_short_target(1.25, entry, 1.5, "measured_move_fallback")
    tp2, tp2_source = _pick_short_target(2.10, tp1 - risk * 0.20, 2.5, "measured_move_fallback")
    if tp2 >= tp1:
        tp2 = max(0.01, tp1 - max(risk, day_range * 0.50))
        tp2_source = "measured_move_fallback"

    geometry = trade_geometry(entry, stop, tp1, tp2, "SHORT")
    if not geometry.get("valid"):
        return None
    return {
        "Entry": _round_trade_price(entry),
        "StopLoss": _round_trade_price(stop),
        "TP1": _round_trade_price(tp1),
        "TP2": _round_trade_price(tp2),
        "entry": _round_trade_price(entry),
        "stop_loss": _round_trade_price(stop),
        "tp1": _round_trade_price(tp1),
        "tp2": _round_trade_price(tp2),
        "Risk": _round_trade_price(geometry["risk"]),
        "risk": _round_trade_price(geometry["risk"]),
        "rr": geometry["rr"],
        "rr_tp1": geometry["rr_tp1"],
        "rr_tp2": geometry["rr_tp2"],
        "level_model": "bear_structure_first_v1",
        "trade_setup_source": "native_bear_structure",
        "stop_source": stop_source,
        "tp1_source": tp1_source,
        "tp2_source": tp2_source,
    }


def _fetch_long_latest_intraday_state(ticker: str) -> Dict[str, Optional[float]]:
    """Same 5m state, used to block fading long mails without blocking continuation."""
    return _fetch_bear_latest_intraday_state(ticker)


def _stock_alert_is_short_context(scanner_name: str, row: Dict[str, Any], strategy_name: str = "") -> bool:
    direction = str(row.get("Signal_Direction", row.get("direction", row.get("side", ""))) or "").lower()
    strategy = str(strategy_name or row.get("strategy", row.get("Strategy", "")) or "").lower()
    if scanner_name in _BEARISH_STOCK_ALERT_SCANNERS:
        return True
    if "short" in direction or "bear" in direction or direction in {"sell", "put"}:
        return True
    return any(token in strategy for token in ("short", "bear", "distribution", "gap momentum short", "ma bounce short"))


def _enrich_stock_alert_5m_state(scanner_name: str, row: Dict[str, Any], strategy_name: str = "") -> Dict[str, Any]:
    """Attach execution state appropriate to the scanner's trading horizon."""
    ticker = _extract_alert_ticker(row)
    grade = _extract_alert_grade(row)
    if not ticker or grade not in _ALERT_TOP_GRADES:
        return row

    enriched = dict(row)
    if scanner_name in _STOCK_SWING_ALERT_SCANNERS and _scanner_uses_swing_horizon(scanner_name):
        enriched.setdefault("entry_quality", "SWING_SETUP")
        enriched.setdefault("swing_timeframe", "daily_swing")
        score = _alert_float(_extract_alert_score(enriched), 0) or 0
        if (
            score >= _ALERT_MIN_SCORE
            and not _stock_alert_is_short_context(scanner_name, enriched, strategy_name)
        ):
            enriched.update(_fetch_stock_swing_execution_state(ticker))
        return enriched

    if (
        enriched.get("latest_bar_change_pct") is None
        or enriched.get("latest_bar_close_pos") is None
        or not enriched.get("intraday_state_status")
    ):
        enriched.update(_fetch_long_latest_intraday_state(ticker))

    if _stock_alert_is_short_context(scanner_name, enriched, strategy_name):
        enriched["short_block_reasons"] = _bear_short_rule_reasons(enriched)
        enriched["entry_quality"] = _bear_entry_quality(enriched)
        enriched["alertable_short"] = not enriched["short_block_reasons"]
    elif scanner_name in _LONG_ENTRY_ALERT_SCANNERS:
        enriched["long_entry_quality"] = _long_entry_quality(enriched)
        enriched["alertable_long"] = not _long_entry_rule_reasons(enriched)
    return enriched


def _alert_cooldown_remaining(key: str, now: Optional[float] = None) -> int:
    now = now or time.time()
    last = _EMAIL_COOLDOWN.get(key)
    if not last:
        return 0
    return max(0, int(_EMAIL_COOLDOWN_SEC - (now - last)))


def _alert_decision_from_reasons(scanner_name: str, reasons: List[str]) -> Dict[str, str]:
    """Normalize alert gating into trade/watch/no-trade language."""
    if not reasons:
        return {
            "decision": "TRADE_NOW",
            "decision_label": "Jetzt traden",
            "decision_reason": "Alle Alert-Gates bestanden",
        }
    wait_retest_markers = {
        "hard_extended_long_wait_retest",
        "extended_long_fading_wait_retest",
        "not_holding_highs_after_up_move",
        "swing_extended_wait_retest",
        "swing_extended_without_volume_wait_retest",
        "swing_current_candle_fading",
        "swing_not_holding_highs_after_move",
        "swing_gap_not_holding_open_wait_retest",
        "swing_gap_not_holding_upper_range_wait_retest",
        "swing_gap_wick_rejection_wait_retest",
        "swing_momentum_trend_reclaim_gap_wait_retest",
        "swing_momentum_not_holding_open_wait_retest",
        "swing_momentum_not_holding_upper_range_wait_retest",
        "swing_momentum_wick_rejection_wait_retest",
        "swing_momentum_breakout_quality_wait_retest",
        "swing_4h_extended_run_wait_retest",
        "swing_4h_rejection_wait_reclaim",
        "swing_day_move_extended_wait_retest",
        "swing_gap_done_premarket_wait_retest",
        "swing_top_entry_extended_wait_retest",
        "swing_short_day_move_extended_wait_retest",
        "swing_short_extended_wait_retest",
        "swing_short_drop_extended_wait_failed_reclaim",
        "swing_short_bottom_entry_extended_wait_retest",
        "top_entry_extended_wait_retest",
        "bottom_entry_extended_wait_retest",
        "swing_short_current_candle_reclaim",
        "swing_short_not_closing_weak",
        "early_mover_retest_not_near_entry",
        "trade_health_wait_for_retest",
    }
    wait_trigger_markers = {
        "trade_health_wait_for_trigger",
        "trade_health_wait_for_continuation",
        "fresh_5m_state_missing_wait_trigger",
        "fresh_5m_state_missing_wait_retest",
        "current_candle_red_fade",
        "early_mover_wait_entry_confirmation",
        "trigger_stale_for_mail",
        "near_structural_barrier_wait_trigger",
        "momentum_breakout_freshness_unconfirmed",
        "swing_4h_state_missing_wait_trigger",
        "momentum_breakout_stale_wait_trigger",
    }
    no_trade_markers = {
        "drop_too_extended_no_chase",
        "target_already_missed",
        "early_mover_no_chase",
        "early_mover_late_to_tp1",
        "early_mover_chased_from_entry",
        "early_mover_blowoff_turnover",
        "early_mover_turnover_without_alpha",
        "pump_continuation_risk",
        "safety_not_ok",
        "risk_too_wide",
        "not_new_listing_dump",
        "listing_age_not_tradeable",
        "non_common_stock_product",
        "estimated_trade_plan",
        "invalid_trade_plan",
        "trade_rr_below_threshold",
        "trade_health_no_trade",
        "trade_health_chase_risk",
        "trade_health_fakeout_risk",
        "trade_health_liquidity_risk",
        "swing_hard_extended_no_chase",
        "swing_day_move_exhausted_no_chase",
        "swing_short_day_move_exhausted_no_chase",
        "swing_short_drop_too_extended_no_chase",
        # 2026-07-31 (BHC): 5-Tage-Move >= 7 ATR — Move erschoepft, kein Chase.
        "swing_multi_day_exhausted_no_chase",
    }
    no_trade_prefixes = ("grade_below", "missing_", "partial_", "not_tradeable", "trade_invalid_")
    contextual_no_trade_markers = set(no_trade_markers)
    if scanner_name == "early_movers" and "early_mover_wait_entry_confirmation" in reasons:
        # Retest/trigger-watch rows are not active trades yet. A Trade-Health
        # chase warning in that context should keep the row in WAIT_TRIGGER,
        # not relabel it as a hard no-trade while the trigger is still missing.
        contextual_no_trade_markers.discard("trade_health_chase_risk")
    has_no_trade = any(reason in contextual_no_trade_markers or reason.startswith(no_trade_prefixes) for reason in reasons)
    if has_no_trade:
        return {
            "decision": "NO_TRADE",
            "decision_label": "Nicht traden",
            "decision_reason": ", ".join(reasons[:4]),
        }
    if any(reason in wait_trigger_markers for reason in reasons):
        return {
            "decision": "WAIT_TRIGGER",
            "decision_label": "Auf Trigger warten",
            "decision_reason": ", ".join(reasons[:4]),
        }
    if any(reason in wait_retest_markers or reason.endswith("wait_retest") for reason in reasons):
        return {
            "decision": "WAIT_RETEST",
            "decision_label": "Auf Retest warten",
            "decision_reason": ", ".join(reasons[:4]),
        }
    return {
        "decision": "WATCH",
        "decision_label": "Beobachten",
        "decision_reason": ", ".join(reasons[:4]),
    }


def _classify_alert_candidate(scanner_name: str, row: Dict[str, Any], now: Optional[float] = None) -> Dict[str, Any]:
    now = now or time.time()
    ticker = _extract_alert_ticker(row)
    grade = _extract_alert_grade(row)
    score = _alert_float(_extract_alert_score(row), 0) or 0
    raw_grade = grade
    raw_score = score
    rvol = _extract_alert_rvol(row)
    reasons = []

    if scanner_name == "new_listing":
        nl_fields = _extract_new_listing_signal_fields(row)
        if nl_fields["grade"]:
            grade = nl_fields["grade"]
    elif scanner_name == "early_movers":
        signal = str(row.get("trade_signal", "") or "").upper()
        entry_score = _alert_float(row.get("entry_score"), None)
        if entry_score is None:
            entry_score = _early_mover_entry_score(row)
        execution_score = _alert_float(row.get("execution_quality_score"), None)
        explosion_score = _alert_float(row.get("explosion_score"), None)
        horizon = _normalize_trade_horizon_value(row.get("_alert_horizon", _DEFAULT_TRADE_HORIZON))
        if horizon == "swing" and _scanner_uses_swing_horizon("early_movers"):
            # Swing crypto mails are setup/structure alerts. They must not depend
            # on a fresh 5m trigger, but they still need a clean entry score.
            # AUDIT H-1: entry_score cappt IMMER (auch 0 ist valide und muss
            # cappen). Das alte max(entry_score, 80) hob den Cap faelschlich
            # auf mindestens 80 an. 80 ist nur noch Fallback ohne entry_score.
            entry_score_cap = _alert_float(entry_score, None)
            score = min(
                _alert_float(score, 0) or 0,
                entry_score_cap if entry_score_cap is not None else 80,
            )
        elif signal == "JETZT_TRADEN":
            score = _early_mover_trade_score(row)
        elif signal == "EXPLOSION_ARMED" and explosion_score is not None:
            score = min(_alert_float(explosion_score, 0) or 0, _alert_float(entry_score, 0) or 0)
        elif execution_score is not None:
            score = min(_alert_float(score, 0) or 0, _alert_float(entry_score, 0) or 0, _alert_float(execution_score, 0) or 0)
        else:
            score = min(_alert_float(score, 0) or 0, _alert_float(entry_score, 0) or 0)
        grade, _ = _score_grade_for_value(score)
    elif scanner_name in _STOCK_ALERT_SCANNERS:
        score = _stock_alert_trade_score(row, scanner_name)

    if not ticker:
        reasons.append("missing_ticker")
    asset_exclusion_reason = None
    if ticker and scanner_name in _STOCK_EMAIL_ASSET_GUARD_SCANNERS:
        common_stock_universe, common_stock_source = _load_common_stock_universe()
        asset_exclusion_reason = _stock_alert_asset_exclusion_reason(
            ticker,
            common_stock_universe=common_stock_universe,
            universe_source=common_stock_source,
            require_reference=common_stock_universe is None,
        )
        if asset_exclusion_reason:
            reasons.append("non_common_stock_product")
    if grade not in _ALERT_TOP_GRADES:
        reasons.append("grade_below_alert_threshold")
    if score < _ALERT_MIN_SCORE:
        reasons.append("score_below_alert_threshold")
    # AUDIT S-1: Breakout-Pfade (turtle / *Breakout*/*Momentum*-Strategien)
    # verlangen RVOL >= 1.5; uebrige Guard-Scanner weiterhin >= 0.7.
    _min_rvol_required = _alert_min_rvol_for_row(scanner_name, row)
    _rvol_gate_active = (
        scanner_name in _ALERT_RVOL_GUARD_SCANNERS
        or _min_rvol_required > _ALERT_MIN_RVOL
    )
    if _rvol_gate_active and (rvol is None or rvol < _min_rvol_required):
        reasons.append("rvol_below_alert_threshold")
    base_blockers = {
        "missing_ticker",
        "non_common_stock_product",
        "grade_below_alert_threshold",
        "score_below_alert_threshold",
        "rvol_below_alert_threshold",
    }
    base_actionable = not any(reason in reasons for reason in base_blockers)
    stock_diagnostics_allowed = (
        scanner_name in _STOCK_ALERT_SCANNERS
        and not any(reason in reasons for reason in {"missing_ticker", "non_common_stock_product"})
        and (raw_grade in _ALERT_TOP_GRADES or raw_score >= _ALERT_MIN_SCORE)
    )
    quality_gate_actionable = base_actionable or stock_diagnostics_allowed

    if base_actionable and scanner_name == "new_listing":
        reasons.extend(_new_listing_rule_reasons(row))
    swing_stock_mode = scanner_name in _STOCK_SWING_ALERT_SCANNERS and _scanner_uses_swing_horizon(scanner_name)
    if quality_gate_actionable and swing_stock_mode:
        if _stock_alert_is_short_context(scanner_name, row):
            reasons.extend(_stock_swing_short_rule_reasons(row))
        else:
            reasons.extend(_stock_swing_rule_reasons(row))
    elif quality_gate_actionable and scanner_name in ("bear", "bi_short"):
        reasons.extend(_bear_short_rule_reasons(row))
    if quality_gate_actionable and not swing_stock_mode and scanner_name in _LONG_ENTRY_ALERT_SCANNERS:
        reasons.extend(_long_entry_rule_reasons(row))
    if base_actionable and scanner_name == "crypto_strategy":
        if not _CRYPTO_STRATEGY_ALERTS_ENABLED:
            reasons.append("crypto_strategy_watch_only")
        signal_quality = str(row.get("signal_quality", "") or "").lower()
        if signal_quality != "tradeable":
            reasons.append("no_crypto_tradeable_signal")
        if not bool(row.get("execution_trigger_ok") or row.get("crypto_entry_ok") or row.get("alertable_crypto")):
            reasons.append("no_crypto_execution_trigger")
        if bool(row.get("partial_data") or row.get("data_partial")):
            reasons.append("partial_crypto_data")
    if quality_gate_actionable and scanner_name in _ALERT_TRADE_HEALTH_GUARD_SCANNERS:
        barrier_reason = _structural_barrier_alert_reason(row)
        if barrier_reason:
            reasons.append(barrier_reason)
    if scanner_name == "early_movers":
        reasons.extend(_early_mover_long_rule_reasons(row))
        # AUDIT Q-2: 15-Min-Frische-Gate. Trigger-/Scan-Zustand aelter als
        # _MAIL_TRIGGER_MAX_AGE_SEC darf nicht mehr als JETZT-Mail raus;
        # solche Rows gehoeren (mit Hinweis) in die Watch-Mail.
        trigger_age = _early_mover_mail_trigger_age_seconds(row, now)
        if trigger_age is not None and trigger_age > _MAIL_TRIGGER_MAX_AGE_SEC:
            reasons.append("trigger_stale_for_mail")
    if quality_gate_actionable and scanner_name in _ALERT_TRADE_PLAN_GUARD_SCANNERS:
        levels = _alert_trade_levels(row)
        if not levels.get("valid"):
            reasons.append("invalid_trade_plan")
            for err in levels.get("errors", [])[:2]:
                reasons.append(f"trade_{err}")
        elif levels.get("estimated"):
            # AUDIT M-4 (10.06.2026): biotech: synthetic erlaubt (Struktur-
            # Level aus _enrich_biotech_alert_trade_levels), Kennzeichnung via
            # M1-Label + synthetic-Flag — levels['synthetic'] loest dieses
            # estimated-Gate bewusst NICHT aus (native=True, estimated=False).
            # Geschaetzte Level (price_fallback/day_range/r_multiple) anderer
            # Scanner bleiben hier hart geblockt.
            reasons.append("estimated_trade_plan")
        elif not _alert_trade_plan_ok(row):
            reasons.append("trade_rr_below_threshold")
    if quality_gate_actionable and scanner_name in _ALERT_TRADE_HEALTH_GUARD_SCANNERS:
        reasons.extend(_alert_trade_health_reasons(row, scanner_name))

    # H-2 (Audit 10.06.2026): HARTES Mail-Gate — ein binaeres Event <= T-3
    # (PDUFA/Readout) ist NIE ein JETZT-Trade-Call: das Gap durchschlaegt
    # jeden Stop. Run-up-Phase = Beobachtung/Exit, kein Neueinstieg.
    if scanner_name == "biotech" and _biotech_near_binary_event(row):
        reasons.append("near_binary_event")

    if quality_gate_actionable and scanner_name in (_STOCK_ALERT_SCANNERS - _SWING_STOCK_STRATEGY_ALERT_SCANNERS):
        entry_quality_text = str(
            row.get("entry_quality")
            or row.get("long_entry_quality")
            or row.get("short_entry_quality")
            or ""
        ).upper()
        non_trade_quality_markers = ("WATCH", "WAIT", "NO_CHASE", "RECLAIM", "FADE", "LATE", "CHASE")
        if entry_quality_text and any(marker in entry_quality_text for marker in non_trade_quality_markers):
            reasons.append("entry_quality_watch_only")

    # AUDIT K-2a: Der Session-Downgrade des C&H-Scanners (laufende Tageskerze
    # => INTRADAY_UNCONFIRMED/BEOBACHTEN/WAIT_FOR_DAILY_CLOSE) schuetzte nur
    # die UI — kein Mail-Gate las entry_status/trade_signal. Rows, die der
    # Scanner selbst als unbestaetigt markiert, sind nie als Trade-Mail
    # zustellbar. Gilt fuer stock_strategy/strategy_scan generell (jede
    # Strategie, die diese Felder setzt).
    if scanner_name in _SWING_STOCK_STRATEGY_ALERT_SCANNERS:
        _entry_status_text = str(row.get("entry_status", "") or "").strip().upper()
        _trade_signal_text = str(row.get("trade_signal", "") or "").strip().upper()
        _trade_action_text = str(row.get("trade_action", "") or "").strip().upper()
        if (
            _entry_status_text == "INTRADAY_UNCONFIRMED"
            or _trade_signal_text == "BEOBACHTEN"
            or _trade_action_text.startswith("WAIT_FOR")
        ):
            reasons.append("intraday_unconfirmed_pattern")

    cooldown_key = _early_mover_alert_key(row, ticker) if scanner_name == "early_movers" else (f"{scanner_name}_{ticker}" if ticker else "")
    cooldown_ttl = _alert_dedupe_ttl_seconds(scanner_name)
    cooldown_last = _EMAIL_COOLDOWN.get(cooldown_key) if cooldown_key else None
    cooldown_remaining = max(0, int(cooldown_ttl - (now - cooldown_last))) if cooldown_last else 0
    if cooldown_remaining > 0:
        reasons.append("cooldown_active")
    dedupe_remaining = _email_dedupe_remaining(cooldown_key, cooldown_ttl, now) if cooldown_key else 0
    if dedupe_remaining > 0:
        reasons.append("persistent_dedupe_active")
    bearish_remaining = _bearish_stock_alert_remaining(ticker, now) if scanner_name in _BEARISH_STOCK_ALERT_SCANNERS else 0
    if bearish_remaining > 0:
        reasons.append("bearish_ticker_already_alerted")

    decision = _alert_decision_from_reasons(scanner_name, reasons)
    return {
        "ticker": ticker,
        "grade": grade,
        "score": int(score) if float(score).is_integer() else round(score, 2),
        "price": _extract_alert_price(row),
        "rvol": rvol,
        "cooldown_key": cooldown_key,
        "cooldown_remaining_seconds": cooldown_remaining,
        "persistent_dedupe_remaining_seconds": dedupe_remaining,
        "bearish_dedupe_remaining_seconds": bearish_remaining,
        "asset_exclusion_reason": asset_exclusion_reason,
        "alertable_now": not reasons,
        "suppression_reasons": reasons,
        **decision,
    }


def _classify_premarket_candidate(scanner_name: str, row: Dict[str, Any], now: Optional[float] = None) -> Dict[str, Any]:
    """Dedizierter Alert-Check fuer Pre-Market-Radar-Rows (AUDIT 2026-07-29).

    Die Regular-Session-Maschinerie (trade_health, 4H-Execution, 5m-Freshness,
    RVOL-Guard) wuerde PM-Rows systematisch verwerfen — sie ist auf
    Regular-Session-Daten kalibriert. PM ist eine bewusst einfachere
    Fruehwarnung: Scan-Score >= 85, Top-Grade, absolute PM-Liquiditaet,
    ATR-Extensions-Decke, valide Level. Eigener Cooldown-Namespace (_pm),
    damit die Regular-Mail nach Open unabhaengig bleibt.
    """
    now = now or time.time()
    ticker = _extract_alert_ticker(row)
    grade = _extract_alert_grade(row)
    score = _alert_float(_extract_alert_score(row), 0) or 0
    rvol = _extract_alert_rvol(row)
    reasons = []

    if not ticker:
        reasons.append("missing_ticker")
    if not _alert_bool(row.get("Premarket") or row.get("premarket")):
        reasons.append("not_a_premarket_row")
    asset_exclusion_reason = None
    if ticker and scanner_name in _STOCK_EMAIL_ASSET_GUARD_SCANNERS:
        common_stock_universe, common_stock_source = _load_common_stock_universe()
        asset_exclusion_reason = _stock_alert_asset_exclusion_reason(
            ticker,
            common_stock_universe=common_stock_universe,
            universe_source=common_stock_source,
            require_reference=common_stock_universe is None,
        )
        if asset_exclusion_reason:
            reasons.append("non_common_stock_product")
    if grade not in _ALERT_TOP_GRADES:
        reasons.append("grade_below_alert_threshold")
    if score < _PREMARKET_MIN_SCORE:
        reasons.append("premarket_score_below_threshold")
    pm_dollar_vol = _alert_float(_alert_get_any(row, "PM_DollarVol", "dollar_volume", "Dollar_Volume"), 0) or 0.0
    if pm_dollar_vol < _PREMARKET_MIN_DOLLAR_VOLUME:
        reasons.append("premarket_liquidity_below_threshold")
    extension_atr = _alert_float(row.get("Extension_ATR"), None)
    if extension_atr is not None and extension_atr > _PREMARKET_MAX_EXTENSION_ATR:
        reasons.append("premarket_extension_too_stretched")
    levels = _alert_trade_levels(row)
    if not levels.get("valid") or levels.get("estimated"):
        reasons.append("premarket_missing_trade_levels")

    cooldown_key = f"{scanner_name}_{ticker}_pm" if ticker else ""
    cooldown_ttl = _alert_dedupe_ttl_seconds(scanner_name)
    cooldown_last = _EMAIL_COOLDOWN.get(cooldown_key) if cooldown_key else None
    cooldown_remaining = max(0, int(cooldown_ttl - (now - cooldown_last))) if cooldown_last else 0
    if cooldown_remaining > 0:
        reasons.append("cooldown_active")
    dedupe_remaining = _email_dedupe_remaining(cooldown_key, cooldown_ttl, now) if cooldown_key else 0
    if dedupe_remaining > 0:
        reasons.append("persistent_dedupe_active")

    decision = _alert_decision_from_reasons(scanner_name, reasons)
    return {
        "ticker": ticker,
        "grade": grade,
        "score": int(score) if float(score).is_integer() else round(score, 2),
        "price": _extract_alert_price(row),
        "rvol": rvol,
        "pm_dollar_vol": pm_dollar_vol,
        "cooldown_key": cooldown_key,
        "cooldown_remaining_seconds": cooldown_remaining,
        "persistent_dedupe_remaining_seconds": dedupe_remaining,
        "bearish_dedupe_remaining_seconds": 0,
        "asset_exclusion_reason": asset_exclusion_reason,
        "alertable_now": not reasons,
        "suppression_reasons": reasons,
        **decision,
    }


def _extract_cache_rows_for_alert_audit(scanner_name: str, cache_file: str) -> List[Dict[str, Any]]:
    rows, _ = load_cache_file(cache_file, max_age_hours=24)
    if scanner_name == "orb":
        flat = []
        for container in rows:
            if isinstance(container, dict):
                for key in ("breakouts", "failed_breakouts", "candidates"):
                    flat.extend([r for r in container.get(key, []) or [] if isinstance(r, dict)])
        return flat
    if scanner_name == "bear":
        flat = []
        for container in rows:
            if isinstance(container, dict):
                flat.extend([r for r in container.get("breakdown_stocks", []) or [] if isinstance(r, dict)])
        return flat
    if scanner_name == "new_listing":
        flat = [r for r in rows if isinstance(r, dict)]
        return [
            r for r in flat
            if str(r.get("source", "")).lower() == "signals"
            or str(r.get("signal", "")).upper().startswith("SHORT")
        ]
    if scanner_name == "early_movers":
        return _flatten_early_mover_rows(rows)
    return [r for r in rows if isinstance(r, dict)]


def _build_alert_audit_for_cache(scanner_name: str, cache_file: str) -> Dict[str, Any]:
    if scanner_name == "biotech":
        _enrich_biotech_alert_trade_levels()
    rows = _extract_cache_rows_for_alert_audit(scanner_name, cache_file)
    now = time.time()
    grade_counts: Dict[str, int] = {}
    decision_counts: Dict[str, int] = {}
    reason_counts: Dict[str, int] = {}
    alertable = []
    watch_preview = []
    crash_reason_counts: Dict[str, int] = {}
    crash_decision_counts: Dict[str, int] = {}
    crash_alertable = []
    armed_reason_counts: Dict[str, int] = {}
    armed_alertable = []
    for row in rows:
        if scanner_name in _STOCK_ALERT_SCANNERS:
            row = _enrich_stock_alert_5m_state(scanner_name, row)
        state = _classify_alert_candidate(scanner_name, row, now)
        grade_counts[state["grade"] or "UNKNOWN"] = grade_counts.get(state["grade"] or "UNKNOWN", 0) + 1
        decision = state.get("decision") or "UNKNOWN"
        decision_counts[decision] = decision_counts.get(decision, 0) + 1
        if state["alertable_now"]:
            alertable.append(state)
        elif len(watch_preview) < 10 and state.get("decision") in ("WATCH", "WAIT_RETEST", "WAIT_TRIGGER"):
            watch_preview.append(state)
        for reason in state["suppression_reasons"]:
            reason_counts[reason] = reason_counts.get(reason, 0) + 1
        if scanner_name == "bear":
            crash_state = _classify_crash_alert_candidate(row, now)
            crash_decision = crash_state.get("decision") or "UNKNOWN"
            crash_decision_counts[crash_decision] = crash_decision_counts.get(crash_decision, 0) + 1
            if crash_state["alertable_now"]:
                crash_alertable.append(crash_state)
            for reason in crash_state["suppression_reasons"]:
                crash_reason_counts[reason] = crash_reason_counts.get(reason, 0) + 1
        if scanner_name == "early_movers":
            trigger = row.get("intraday_trigger") if isinstance(row.get("intraday_trigger"), dict) else None
            armed_ok, armed_reasons = _early_mover_explosion_armed_state(row, trigger)
            if armed_ok:
                armed_score = _alert_float(row.get("explosion_score"), None)
                if armed_score is None:
                    armed_score = _early_mover_explosion_score(row, trigger)
                armed_grade, _ = _score_grade_for_value(int(armed_score))
                if armed_grade in _ALERT_TOP_GRADES and armed_score >= _EARLY_MOVER_MIN_ARMED_SETUP_SCORE:
                    armed_alertable.append({
                        "ticker": state.get("ticker"),
                        "grade": armed_grade,
                        "score": int(armed_score),
                        "setup_score": row.get("setup_score", row.get("score")),
                        "price": state.get("price"),
                        "entry": row.get("entry"),
                        "stop": row.get("stop_loss", row.get("stop")),
                        "tp1": row.get("tp1"),
                        "tp2": row.get("tp2"),
                        "pre_breakout_score": (trigger or {}).get("pre_breakout_score", row.get("pre_breakout_score")),
                        "live_rr": row.get("live_rr_ratio"),
                        "distance_to_entry_r": row.get("distance_to_entry_r"),
                        "mail_type": "EXPLOSION_ARMED",
                        "note": "Armed-Watch ist kein Trade und wird nicht gemailt.",
                    })
                else:
                    armed_reason_counts["armed_grade_or_score_below_threshold"] = armed_reason_counts.get("armed_grade_or_score_below_threshold", 0) + 1
            else:
                for reason in armed_reasons[:4]:
                    armed_reason_counts[reason] = armed_reason_counts.get(reason, 0) + 1

    cache_age = None
    if os.path.exists(cache_file):
        cache_age = int(max(0, time.time() - os.path.getmtime(cache_file)))

    audit = {
        "scanner": scanner_name,
        "cache_file": os.path.basename(cache_file),
        "cache_exists": os.path.exists(cache_file),
        "cache_age_seconds": cache_age,
        "rows_checked": len(rows),
        "grade_counts": grade_counts,
        "decision_counts": decision_counts,
        "alertable_now_count": len(alertable),
        "alertable_preview": alertable[:10],
        "watch_preview": watch_preview,
        "mail_status": "SEND_NOW" if alertable else "NO_MAIL",
        "mail_status_label": "Mail wuerde jetzt rausgehen" if alertable else "Keine Mail: Gates blockieren oder nur Watch",
        "suppression_counts": reason_counts,
        "suppression_top": _top_alert_reasons(reason_counts),
        "suppression_human": _format_alert_suppression_summary(reason_counts, grade_counts),
    }
    if scanner_name == "bear":
        audit.update({
            "crash_alertable_now_count": len(crash_alertable),
            "crash_alertable_preview": crash_alertable[:10],
            "crash_decision_counts": crash_decision_counts,
            "crash_suppression_counts": crash_reason_counts,
            "crash_suppression_top": _top_alert_reasons(crash_reason_counts),
            "crash_mail_status": "SEND_NOW" if crash_alertable else "NO_MAIL",
            "crash_mail_status_label": "Crash-Mail wuerde jetzt rausgehen" if crash_alertable else "Keine Crash-Mail: Gates blockieren oder Dedupe aktiv",
        })
    if scanner_name == "early_movers":
        armed_mail_enabled = bool(_EARLY_MOVER_SEND_ARMED_EMAILS)
        audit.update({
            "armed_watch_count": len(armed_alertable),
            "armed_watch_preview": armed_alertable[:10],
            "armed_alertable_now_count": len(armed_alertable) if armed_mail_enabled else 0,
            "armed_alertable_preview": armed_alertable[:10] if armed_mail_enabled else [],
            "armed_suppression_counts": armed_reason_counts,
            "armed_suppression_top": _top_alert_reasons(armed_reason_counts),
            "armed_mail_status": (
                "ARMED_READY"
                if armed_mail_enabled and armed_alertable
                else "DISABLED"
                if armed_alertable
                else "NO_ARMED_MAIL"
            ),
            "armed_mail_status_label": (
                "Armed-Watch-Mails sind deaktiviert; Mails nur fuer bestaetigte Trade-Signale."
                if armed_alertable
                else "Keine Armed-Mail: Watch/Armed ist kein bestaetigtes Trade-Signal"
            ),
            "armed_mail_enabled": armed_mail_enabled,
        })
    if scanner_name == "new_listing":
        raw_rows, _ = load_cache_file(cache_file, max_age_hours=24)
        dump_watch_candidates = _new_listing_watch_candidates({"monitoring": raw_rows})
        dump_watch_enabled = bool(_NEW_LISTING_SEND_DUMP_WATCH_EMAILS)
        audit.update({
            "dump_watch_mails_enabled": dump_watch_enabled,
            "dump_watch_candidate_count": len(dump_watch_candidates),
            "dump_watch_preview": dump_watch_candidates[:10],
            "dump_watch_mail_status": (
                "DUMP_WATCH_READY"
                if dump_watch_enabled and dump_watch_candidates
                else "DISABLED"
                if dump_watch_candidates
                else "NO_DUMP_WATCH"
            ),
            "dump_watch_mail_status_label": (
                "New-Listing-Dump-Watch-Mail moeglich; Short-Mail kommt separat erst bei bestaetigtem 5m Crack/Rejection."
                if dump_watch_enabled and dump_watch_candidates
                else "New-Listing-Dump-Watch-Mails sind deaktiviert."
                if dump_watch_candidates
                else "Keine Dump-Watch-Mail: keine gepumpten New Listings mit ausreichender Safety/Qualitaet."
            ),
        })
    return audit


def _summarize_email_alert_audit(scanners: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
    total_rows = 0
    total_alertable = 0
    total_crash_alertable = 0
    total_armed_alertable = 0
    aggregate_reasons: Dict[str, int] = {}
    scanner_statuses = []
    for name, audit in scanners.items():
        if not isinstance(audit, dict):
            continue
        if audit.get("error"):
            scanner_statuses.append({
                "scanner": name,
                "status": "ERROR",
                "label": f"Audit-Fehler: {audit.get('error')}",
            })
            continue
        rows = int(audit.get("rows_checked") or 0)
        alertable = int(audit.get("alertable_now_count") or 0)
        crash_alertable = int(audit.get("crash_alertable_now_count") or 0)
        armed_alertable = int(audit.get("armed_alertable_now_count") or 0)
        total_rows += rows
        total_alertable += alertable
        total_crash_alertable += crash_alertable
        total_armed_alertable += armed_alertable
        for counts_key in ("suppression_counts", "crash_suppression_counts", "armed_suppression_counts"):
            counts = audit.get(counts_key) or {}
            if isinstance(counts, dict):
                for reason, count in counts.items():
                    aggregate_reasons[reason] = aggregate_reasons.get(reason, 0) + int(count or 0)
        if alertable or crash_alertable:
            status = "SEND_NOW"
            label = f"{alertable + crash_alertable} Mail-Kandidat(en) jetzt"
        elif armed_alertable:
            status = "ARMED_READY"
            label = f"{armed_alertable} Explosion-Armed Kandidat(en); kein Market-Buy, Orderbook-Check im Sendelauf"
        elif rows == 0:
            status = "NO_CANDIDATES"
            label = "Keine aktuellen Kandidaten im Cache"
        else:
            status = "BLOCKED"
            top = _top_alert_reasons(audit.get("suppression_counts") or {}, max_items=1)
            label = top[0]["label"] if top else "Nur Watch/unter Alert-Gates"
        scanner_statuses.append({
            "scanner": name,
            "status": status,
            "label": label,
            "rows_checked": rows,
            "alertable_now_count": alertable,
            "crash_alertable_now_count": crash_alertable,
            "armed_alertable_now_count": armed_alertable,
            "cache_age_seconds": audit.get("cache_age_seconds"),
        })

    email_status = _email_alert_status()
    startup_cooldown = int(email_status.get("startup_cooldown_remaining_seconds") or 0)
    configured = bool(email_status.get("configured"))
    if not configured:
        overall = "EMAIL_NOT_CONFIGURED"
        next_step = "GMAIL_USER/GMAIL_APP_PASSWORD/ALERT_EMAIL pruefen."
    elif startup_cooldown > 0:
        overall = "STARTUP_COOLDOWN"
        next_step = f"Noch {startup_cooldown}s Startup-Cooldown nach Restart."
    elif total_alertable + total_crash_alertable > 0:
        overall = "MAIL_READY"
        next_step = "Mindestens ein Kandidat besteht alle Gates; Mail sollte beim naechsten Alert-Lauf kommen."
    elif total_armed_alertable > 0:
        overall = "ARMED_READY"
        next_step = "Crypto Armed-Kandidaten vorhanden; Mail kommt, wenn Armed-Digest-Dedupe und Orderbook-Check frei sind."
    elif total_rows == 0:
        overall = "NO_CANDIDATES"
        next_step = "Scanner-Caches enthalten aktuell keine Kandidaten fuer Mail-Audit."
    else:
        overall = "ALL_BLOCKED_BY_GATES"
        next_step = "Keine Mail ist korrekt: Score/Grade/Timing/R:R/Trade-Health/Dedupe blockt aktuell."

    return {
        "overall_status": overall,
        "next_step": next_step,
        "total_rows_checked": total_rows,
        "total_alertable_now": total_alertable,
        "total_crash_alertable_now": total_crash_alertable,
        "total_armed_alertable_now": total_armed_alertable,
        "top_blockers": _top_alert_reasons(aggregate_reasons, max_items=10),
        "scanner_statuses": scanner_statuses,
    }


def _alert_suppression_summary_for_rows(scanner_name: str, rows: List[Dict[str, Any]], now: Optional[float] = None) -> str:
    now = now or time.time()
    suppressed: Dict[str, int] = {}
    grade_counts: Dict[str, int] = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        state = _classify_alert_candidate(scanner_name, row, now)
        grade_counts[state["grade"] or "UNKNOWN"] = grade_counts.get(state["grade"] or "UNKNOWN", 0) + 1
        for reason in state["suppression_reasons"]:
            suppressed[reason] = suppressed.get(reason, 0) + 1
    return _format_alert_suppression_summary(suppressed, grade_counts)


def _crash_alert_suppression_summary_for_rows(rows: List[Dict[str, Any]], now: Optional[float] = None) -> str:
    now = now or time.time()
    suppressed: Dict[str, int] = {}
    grade_counts: Dict[str, int] = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        state = _classify_crash_alert_candidate(row, now)
        grade_counts[state["grade"] or "UNKNOWN"] = grade_counts.get(state["grade"] or "UNKNOWN", 0) + 1
        for reason in state["suppression_reasons"]:
            suppressed[reason] = suppressed.get(reason, 0) + 1
    return _format_alert_suppression_summary(suppressed, grade_counts)


def _extract_email_body_inner(body_html: str) -> str:
    """Accept old full HTML mails and extract only the content for the branded shell."""
    text = str(body_html or "")
    match = re.search(r"<body[^>]*>(.*?)</body>", text, flags=re.IGNORECASE | re.DOTALL)
    if match:
        text = match.group(1)
    text = re.sub(r"^\s*<html[^>]*>\s*", "", text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"\s*</html>\s*$", "", text, flags=re.IGNORECASE | re.DOTALL)
    # Keep legacy alert bodies from leaking the old product name.
    text = text.replace("TradingBot Alert", "Alpha Station Alert")
    text = text.replace("TradingBot", "Alpha Station")
    return text.strip()


