# AUDIT H-2: Mail-Klassen mit verbindlichem Betreff-Praefix. "trade" = im
# Versandmoment handelbar, "watch" = Beobachtung ohne Einstiegssignal,
# "info" = Status/Test/Marktkontext ohne Trade-Bezug.
# 2026-07-31 (BHC): "swing_trade" verliert das Wort "JETZT" — Swing-Mails
# sind mehrtaegige Struktur-Plaene (eigener Mail-Disclaimer), und der
# Betreff versprach "jetzt kaufen", obwohl die Timing-Spalte "Swing-Setup
# aktiv" sagte. "JETZT" bleibt ausschliesslich den Intraday-Trade-Mails
# mit 15-Minuten-Frische-Gate vorbehalten.
_MAIL_CLASS_SUBJECT_PREFIXES = {
    "trade": "\U0001F6A8 JETZT: ",
    "swing_trade": "\U0001F6A8 SWING: ",
    "watch": "\U0001F441️ WATCH: ",
    "info": "ℹ️ ",
}


def _apply_mail_class_subject(subject: str, mail_class: str, trade_horizon: str = "") -> str:
    """AUDIT H-2: Klassen-Praefix voranstellen ohne Emoji-Stapelung.

    Bereits vorhandene Klassen-/Legacy-Emojis am Betreffanfang werden ersetzt
    statt gestapelt (z.B. "\U0001F6A8 3 Top-Setups" -> "\U0001F6A8 JETZT: 3 Top-Setups").
    """
    cls = str(mail_class or "trade").strip().lower()
    prefix = _MAIL_CLASS_SUBJECT_PREFIXES.get(cls, _MAIL_CLASS_SUBJECT_PREFIXES["trade"])
    text = str(subject or "").strip()
    legacy_markers = (
        "\U0001F6A8 JETZT SWING:",
        "\U0001F6A8 SWING:",
        "\U0001F6A8 JETZT:",
        "\U0001F4C8 SWING:",
        "\U0001F441️ WATCH:",
        "\U0001F441 WATCH:",
        "ℹ️",
        "ℹ",
        "\U0001F6A8",
        "\U0001F4C8",
        "\U0001F441️",
        "\U0001F441",
        "\U0001F514",
        "⚠️",
        "⚠",
        "✅",
    )
    stripped = True
    while stripped:
        stripped = False
        for marker in legacy_markers:
            if text.startswith(marker):
                text = text[len(marker):].lstrip()
                stripped = True
    return f"{prefix}{text}"


def _safe_format_telegram_rows(rows) -> str:
    """Telegram-Body defensiv formatieren — Mail-Versand darf nie daran scheitern."""
    if not format_alert_rows_for_telegram or not rows:
        return ""
    try:
        return str(format_alert_rows_for_telegram(rows) or "")
    except Exception as exc:
        print(f"[Alert] Telegram-Formatter Fehler (ignoriert): {exc}")
        return ""


def _safe_record_alert_signals(scanner_name: str, rows, mail_class: str = "trade", channel: str = "email") -> None:
    """Signal-Tracking nach erfolgreichem Trade-Mail-Versand (defensiv).

    Kontrakt: record_alert_signals wirft nie, dedupet intern und loggt nur
    mail_class=="trade". Zusaetzlicher try/except, damit Alerts auch bei
    kaputtem/gemocktem Modul niemals am Tracking scheitern.

    Annotation (2026-07-30): aktueller Zins-Block aus dem Market-Context wird
    als rates_json mitgespeichert (Mess-First, kein Gate). Bei TypeError
    (gemischter Code-Stand) Fallback ohne rates_context — Tracking bricht nie.
    """
    if not record_alert_signals or not rows:
        return
    try:
        rates_ctx = None
        try:
            snap = _get_market_context_snapshot()
            if isinstance(snap, dict) and (snap.get("rates") or {}).get("status") == "ok":
                rates_ctx = snap.get("rates")
        except Exception:
            rates_ctx = None
        try:
            record_alert_signals(scanner_name, rows, mail_class=mail_class, channel=channel, rates_context=rates_ctx)
        except TypeError:
            record_alert_signals(scanner_name, rows, mail_class=mail_class, channel=channel)
    except Exception as exc:
        print(f"[Alert] Signal-Tracking Fehler (ignoriert): {exc}")


def _send_email_alert(
    subject,
    body_html,
    bypass_startup_cooldown: bool = False,
    recipient_emails: Optional[List[str]] = None,
    trade_horizon: str = "swing",
    mail_class: str = "trade",
    telegram_text: str = "",
    mail_channel: str = "",
):
    """Sendet E-Mail Alert via Gmail SMTP."""
    # AUDIT H-2: Betreff traegt immer das Klassen-Praefix (auch in Logs).
    subject = _apply_mail_class_subject(subject, mail_class, trade_horizon=trade_horizon)
    if _email_has_blocked_etf_content(subject, body_html):
        print(f"[Alert] SKIP (ETF/ETP-Inhalt blockiert): {subject}")
        _record_email_event(subject, "skipped", "blocked_etf_content")
        return False
    # V2.6b: Nach Restart 5 Min warten (alte Cache-Daten erzeugen Phantom-Alerts)
    if not bypass_startup_cooldown and time.time() - _EMAIL_STARTUP_TIME < _EMAIL_STARTUP_DELAY:
        print(f"[Alert] SKIP (Startup-Cooldown): {subject}")
        _record_email_event(subject, "skipped", "startup_cooldown")
        return False
    gmail_user = _SECRETS.get("GMAIL_USER", "")
    gmail_pass = _SECRETS.get("GMAIL_APP_PASSWORD", "")
    alert_to = _SECRETS.get("ALERT_EMAIL", gmail_user)
    if not gmail_user or not gmail_pass:
        print("[Alert] SKIP: GMAIL_USER oder GMAIL_APP_PASSWORD fehlt")
        _record_email_event(subject, "skipped", "missing_gmail_config")
        return False
    operator_watch_optin = str(
        _SECRETS.get(
            "ALERT_OPERATOR_WATCH_OPTIN",
            os.environ.get("ALERT_OPERATOR_WATCH_OPTIN", "0"),
        )
    ).strip().lower() in {"1", "true", "yes", "on"}
    if recipient_emails is not None:
        recipients = [addr.strip().lower() for addr in recipient_emails if str(addr).strip()]
    else:
        operator_recipients = [addr.strip().lower() for addr in str(alert_to).split(",") if addr.strip()]
        if mail_channel and HAS_AUTH:
            # AUDIT 2026-07-28: Kanal-Opt-out gilt auch fuer die Betreiber-Mailbox,
            # sofern die Adresse ein User-Konto mit abgeschaltetem Kanal hat.
            operator_recipients = [
                addr for addr in operator_recipients
                if mail_channel_enabled(addr, mail_channel)
            ]
        recipients = operator_recipients if mail_class != "watch" or operator_watch_optin else []
    if recipient_emails is None and ALERT_SEND_TO_SUBSCRIBERS and HAS_AUTH:
        try:
            # Watch-Mails gehen nur an explizit angemeldete Empfaenger. Das gilt
            # auch fuer den Betreiber-Fallback, damit Watchlists nie ungefragt
            # den Trade-Posteingang fluten.
            recipients.extend(get_email_alert_recipients(trade_horizon=trade_horizon, mail_class=mail_class, mail_channel=mail_channel))
        except Exception as exc:
            print(f"[Alert] Subscriber recipients skipped: {exc}")
    recipients = sorted(set(addr for addr in recipients if "@" in addr))
    if not recipients:
        print("[Alert] SKIP: ALERT_EMAIL/GMAIL_USER Empfaenger fehlt")
        _record_email_event(subject, "skipped", "missing_recipient")
        return False
    branded_body_html = _brand_email_html(subject, body_html)
    for attempt in range(3):
        try:
            msg = MIMEMultipart("alternative")
            msg["From"] = f"Alpha Station Alert <{gmail_user}>"
            # Never disclose subscriber addresses to other recipients.
            msg["To"] = recipients[0] if len(recipients) == 1 else "undisclosed-recipients:;"
            msg["Subject"] = subject
            plain = re.sub(r"<[^>]+>", "", branded_body_html.replace("<br>", "\n").replace("</tr>", "\n"))
            msg.attach(MIMEText(plain, "plain", "utf-8"))
            msg.attach(MIMEText(branded_body_html, "html", "utf-8"))
            # Try port 587 (STARTTLS) first, fallback to 465 (SSL)
            try:
                server = smtplib.SMTP("smtp.gmail.com", 587, timeout=10)
                server.ehlo()
                server.starttls()
                server.ehlo()
                server.login(gmail_user, gmail_pass)
                server.sendmail(gmail_user, recipients, msg.as_string())
                server.quit()
            except Exception:
                with smtplib.SMTP_SSL("smtp.gmail.com", 465, timeout=10) as server:
                    server.login(gmail_user, gmail_pass)
                    server.sendmail(gmail_user, recipients, msg.as_string())
            print(f"[Alert] Email gesendet: {subject}")
            _record_email_event(subject, "sent")
            # Telegram-Spiegel NUR fuer handelbare Alerts (trade/swing_trade).
            # Kontrakt: send_telegram_alert wirft nie; zusaetzlich defensiv,
            # damit der Mail-Erfolg nie am Telegram-Hook haengt.
            if str(mail_class or "").strip().lower() in {"trade", "swing_trade"} and is_telegram_configured and send_telegram_alert:
                try:
                    if is_telegram_configured():
                        send_telegram_alert(subject, telegram_text or "")
                except Exception as _tg_exc:
                    print(f"[Alert] Telegram-Hook Fehler (ignoriert): {_tg_exc}")
            return True
        except Exception as e:
            if attempt < 2:
                time.sleep(2 ** attempt)
            else:
                print(f"[Alert] Email FEHLER nach 3 Versuchen: {e}")
                _record_email_event(subject, "error", str(e))
                return False


def _cluster_warning_html(rows) -> str:
    """Klumpenrisiko-Hinweis fuer Aktien-Signal-Mails — reine Funktion, "" wenn nichts zu warnen.

    Anlass (11.06.): zwei Alert-Mails enthielten zusammen 5 argentinische ADRs
    (BMA, GGAL, CEPU, TGS, IRS) als "separate" Setups — derselbe Makro-Treiber,
    Abonnenten haetten 3x Size auf denselben Trade legen koennen.
    Regel A: >= 2 Setups, deren Ticker im ADR-Set (ADRC/ADRP) liegen.
    Regel B: >= 3 Setups mit |Tages-Change| > 5 Prozent.
    Beide Regeln koennen gemeinsam erscheinen. NUR Information — Setups werden
    nicht unterdrueckt (Produktentscheidung: jedes Setup bleibt einzeln valide).
    Darf NIE werfen und NIE Netz ziehen (laeuft im Mail-Versandpfad).
    """
    try:
        safe_rows = [r for r in (rows or []) if isinstance(r, dict)]
        if not safe_rows:
            return ""
        try:
            adr_set = _adr_ticker_set()
        except Exception:
            adr_set = set()  # doppeltes Sicherheitsnetz — _adr_ticker_set wirft selbst nie
        change_keys = ("change_pct", "Change_Pct", "Change%", "Change %", "Änderung%", "change", "Change")
        adr_hits: list[str] = []
        strong_movers = 0
        for row in safe_rows:
            ticker = _extract_alert_ticker(row)
            if ticker and ticker in adr_set and ticker not in adr_hits:
                adr_hits.append(ticker)
            change_raw = _alert_get_any(row, *change_keys, default=None)
            if change_raw is None and isinstance(row.get("source_row"), dict):
                change_raw = _alert_get_any(row["source_row"], *change_keys, default=None)
            change_val = _alert_float(change_raw, None)
            if change_val is not None and abs(change_val) > 5:
                strong_movers += 1
        warnings: list[str] = []
        if len(adr_hits) >= 2:
            warnings.append(
                f"⚠ Klumpenrisiko: {len(adr_hits)} Setups sind auslaendische US-Listings "
                f"(ADR: {', '.join(adr_hits)}) — haeufig derselbe Laender-/Makro-Treiber. "
                "Als EINEN Trade behandeln, nicht mehrfach Size aufbauen."
            )
        if strong_movers >= 3:
            warnings.append(
                f"⚠ {strong_movers} Setups mit starkem Tages-Move — pruefe gemeinsamen "
                "Treiber (News/Sektor/Land) vor dem Einstieg."
            )
        if not warnings:
            return ""
        lines = "".join(f'<div style="margin:2px 0">{w}</div>' for w in warnings)
        return (
            '<p style="background:#fef3c7;border:1px solid #f59e0b;border-radius:8px;'
            f'padding:10px;color:#b91c1c;font-size:13px;font-weight:bold">{lines}</p>'
        )
    except Exception as cluster_err:
        print(f"[Cluster Warning] build error: {cluster_err}")
        return ""


def _check_and_alert(scanner_name, cache_file):
    """Prüft Scan-Ergebnisse auf Grade S/A/B und sendet Alert."""
    now = time.time()
    claimed_alerts: List[Dict[str, Any]] = []
    mail_sent = False
    try:
        if not os.path.exists(cache_file):
            print(f"[Alert] {scanner_name}: Cache-Datei nicht vorhanden: {cache_file}")
            return
        with open(cache_file, "r") as f:
            data = json.load(f)
        results = data if isinstance(data, list) else data.get("results", data.get("data", []))
        if isinstance(results, list) and len(results) > 0 and isinstance(results[0], dict) and "data" in results[0]:
            results = results[0].get("data", results)
        if not isinstance(results, list):
            print(f"[Alert] {scanner_name}: Cache hat kein gültiges results-Array")
            return
        if scanner_name in _STOCK_ALERT_SCANNERS:
            allowed, _reason = _stock_trade_email_allowed(scanner_name)
            if not allowed:
                return
        print(f"[Alert] {scanner_name}: {len(results)} Ergebnisse gefunden, prüfe Grades...")
        # V2.6: Grade-Schwellen VERSCHÄRFT — nur noch hochkarätige Setups
        # BI: S/A (kein B mehr!), Biotech: A (hat kein S)
        alerts = []
        suppressed: Dict[str, int] = {}
        _alert_grades = _ALERT_TOP_GRADES
        for r in results:
            if not isinstance(r, dict):
                continue
            if scanner_name in _STOCK_ALERT_SCANNERS:
                r = _enrich_stock_alert_5m_state(scanner_name, r)
            elif scanner_name in _LONG_ENTRY_ALERT_SCANNERS:
                ticker_probe = _extract_alert_ticker(r)
                grade_probe = _extract_alert_grade(r)
                if ticker_probe and grade_probe in _ALERT_TOP_GRADES:
                    r = dict(r)
                    r.update(_fetch_long_latest_intraday_state(ticker_probe))
                    r["long_entry_quality"] = _long_entry_quality(r)
                    r["alertable_long"] = not _long_entry_rule_reasons(r)
            state = _classify_alert_candidate(scanner_name, r, now)
            ticker = state["ticker"]
            grade = state["grade"]
            score = state["score"]
            _rvol_check = state["rvol"] if state["rvol"] is not None else 0
            if not state["alertable_now"]:
                for reason in state["suppression_reasons"]:
                    suppressed[reason] = suppressed.get(reason, 0) + 1
                continue
            # RVOL Guard: Grade S/A braucht min RVOL (0.7 default, 1.5 fuer
            # Breakout-Pfade, AUDIT S-1) — Sicherheitsnetz
            if scanner_name in _ALERT_RVOL_GUARD_SCANNERS and grade in ("S", "A", "A+") and _rvol_check < _alert_min_rvol_for_row(scanner_name, r):
                grade = "B"  # Downgrade — kein Alert
            if grade not in _alert_grades:
                continue
            ck = f"{scanner_name}_{ticker}"
            ck_ttl = _alert_dedupe_ttl_seconds(scanner_name)
            if ck in _EMAIL_COOLDOWN and now - _EMAIL_COOLDOWN[ck] < ck_ttl:
                continue
            alerts.append({"ticker": ticker, "grade": grade, "score": score,
                           "price": _extract_alert_price(r),
                           "direction": r.get("BI_Direction", r.get("direction", "")),
                           "rvol": r.get("RVOL", r.get("rvol", 0)),
                           "entry_quality": r.get("long_entry_quality", ""),
                           "trade_plan_html": _format_alert_plan_html(r),
                           "source_row": r,  # Signal-Tracking: Row mit Entry/StopLoss/TP-Feldern
                           "cooldown_key": ck})
        if not alerts:
            # Log warum keine Alerts
            all_grades = [_extract_alert_grade(r) or "?" for r in results if isinstance(r, dict)]
            grade_counts = dict((g, all_grades.count(g)) for g in set(all_grades))
            print(f"[Alert] {scanner_name}: Keine alertbaren Grades. Vorhandene Grades: {grade_counts}; suppressed={suppressed}")
            if scanner_name in _STOCK_ALERT_SCANNERS:
                _record_email_event(
                    f"{scanner_name} Stock Alert",
                    "skipped",
                    f"no_alertable_stock_setups:{_format_alert_suppression_summary(suppressed, grade_counts)}",
                )
            return
        claimed_alerts = [
            alert for alert in alerts
            if _email_dedupe_claim(
                alert["cooldown_key"],
                _alert_dedupe_ttl_seconds(scanner_name),
                now=now,
            )
        ]
        alerts = claimed_alerts
        if not alerts:
            return
        labels = {"bi_long": "BI Scanner LONG", "bi_short": "BI Scanner SHORT",
                  "biotech": "Biotech Scanner", "bear": "Bear Scanner"}
        label = labels.get(scanner_name, scanner_name)
        n = len(alerts)
        # Emoji pro Grade
        _grade_emoji = {"S": "🏆", "A": "🔥", "A+": "🔥", "B": "⭐"}
        subject = f"🚨 {n} Top-Setup{'s' if n > 1 else ''} — {label}"
        rows = ""
        for a in alerts:
            emoji = _grade_emoji.get(a["grade"], "📊")
            rows += f'<tr><td style="padding:8px;border-bottom:1px solid #eee"><b>{a["ticker"]}</b></td>'
            rows += f'<td style="padding:8px;border-bottom:1px solid #eee">{emoji} {a["grade"]}</td>'
            rows += f'<td style="padding:8px;border-bottom:1px solid #eee">{a["score"]}</td>'
            rows += f'<td style="padding:8px;border-bottom:1px solid #eee">{_format_alert_price(a["price"])}</td>'
            rows += f'<td style="padding:8px;border-bottom:1px solid #eee">{a["rvol"]}x</td>'
            rows += f'<td style="padding:8px;border-bottom:1px solid #eee">{a["trade_plan_html"]}</td>'
            rows += f'<td style="padding:8px;border-bottom:1px solid #eee">{a.get("entry_quality", "")}</td></tr>'
        # Klumpenrisiko-Hinweis (ADR-Cluster / Mehrfach-Mover) — nur Information, keine Unterdrueckung
        _cluster_hint = _cluster_warning_html(alerts)
        body = f'''<html><body style="font-family:Arial,sans-serif;max-width:700px;margin:0 auto">
        <h2 style="color:#1a73e8">🚨 TradingBot Alert — {label}</h2>
        <p style="color:#666">{_mail_timestamp_dual()} | {n} starke Setups</p>
        {_cluster_hint}
        <table style="width:100%;border-collapse:collapse;font-size:14px">
        <tr style="background:#f5f5f5"><th style="padding:8px;text-align:left">Ticker</th>
        <th style="padding:8px;text-align:left">Grade</th><th style="padding:8px;text-align:left">Score</th>
        <th style="padding:8px;text-align:left">Preis</th><th style="padding:8px;text-align:left">RVOL</th>
        <th style="padding:8px;text-align:left">Entry / Stop / TP</th><th style="padding:8px;text-align:left">Timing</th></tr>
        {rows}</table>
        <p style="color:#999;font-size:12px;margin-top:20px">Automatischer Alert — S = ELITE | A = STARK | B = SOLIDE</p>
        </body></html>'''
        print(f"[Alert] {scanner_name}: Sende Alert für {n} Treffer: {[a['ticker'] for a in alerts]}")
        _signal_rows = [dict(a.get("source_row") or {}, ticker=a["ticker"], grade=a["grade"], score=a["score"], price=a["price"]) for a in alerts]
        sent = _send_email_alert(subject, body, trade_horizon="swing", mail_class="trade", telegram_text=_safe_format_telegram_rows(_signal_rows), mail_channel=scanner_mail_channel(scanner_name))  # AUDIT H-3 / H-2 (BI/Biotech/Bear Top-Setups)
        if sent:
            mail_sent = True
            for alert in alerts:
                _EMAIL_COOLDOWN[alert["cooldown_key"]] = now
                _email_dedupe_mark(alert["cooldown_key"], now=now)
                if scanner_name in _BEARISH_STOCK_ALERT_SCANNERS:
                    _mark_bearish_stock_alert(alert["ticker"], now=now)
            _safe_record_alert_signals(scanner_name, _signal_rows)
        else:
            for alert in claimed_alerts:
                _email_dedupe_release(alert["cooldown_key"], claimed_at=now)
    except Exception as e:
        if not mail_sent:
            for alert in claimed_alerts:
                _email_dedupe_release(alert.get("cooldown_key", ""), claimed_at=now)
        import traceback
        print(f"[Alert] Check-Fehler {scanner_name}: {e}\n{traceback.format_exc()}")


def _daily_bar_date_str(bar: Dict[str, Any]) -> str:
    """Datum einer Daily-Bar als YYYY-MM-DD ('' wenn unbestimmbar)."""
    if not isinstance(bar, dict):
        return ""
    raw = bar.get("date") or bar.get("Date") or ""
    if raw:
        return str(raw)[:10]
    ts = bar.get("t") or bar.get("time") or bar.get("timestamp")
    try:
        ts_f = float(ts)
        if ts_f > 1e12:  # Millisekunden (Polygon aggs)
            ts_f /= 1000.0
        if ts_f <= 0:
            return ""
        return datetime.fromtimestamp(ts_f, tz=timezone.utc).strftime("%Y-%m-%d")
    except (TypeError, ValueError):
        return ""


def _strategy_rows_daily_close_confirmed(results: List[Dict[str, Any]]) -> bool:
    """AUDIT K-2b: Eng begrenzte Daily-Close-Ausnahme vom Session-Mail-Gate.

    True NUR wenn ALLE Rows (a) entry_status == BREAKOUT_CONFIRMED tragen und
    (b) ihre letzte Daily-Kerze der HEUTIGE US-Handelstag ist (ET). Damit gehen
    nach Boersenschluss ausschliesslich frisch per Tagesschluss bestaetigte
    Daily-Breakouts (z.B. Cup & Handle) raus — kein Wochenend-/Feiertags-Stale,
    keine Mischung mit unbestaetigten Rows.
    """
    rows = [row for row in results if isinstance(row, dict)]
    if not rows:
        return False
    try:
        from zoneinfo import ZoneInfo
        today_et = datetime.now(timezone.utc).astimezone(ZoneInfo("America/New_York")).date()
        exchange = _us_exchange_calendar()
        if exchange is None or not _is_exchange_trading_day(exchange, today_et):
            return False  # heute ist kein US-Handelstag => letzte Kerze ist stale
        today_str = today_et.isoformat()
    except Exception:
        return False
    for row in rows:
        if str(row.get("entry_status", "") or "").strip().upper() != "BREAKOUT_CONFIRMED":
            return False
        if str(row.get("last_daily_bar_date", "") or "")[:10] != today_str:
            return False
    return True


def _send_strategy_scan_alerts(strategy_name: str, results: List[Dict[str, Any]], market_type: str = "stocks") -> None:
    """Mail top S/A strategy rows when a manual or scheduled strategy scan produces them."""
    if not results:
        return
    scanner_key = "crypto_strategy" if market_type == "crypto" else "stock_strategy"
    daily_close_confirmed_mode = False
    # AUDIT 2026-07-29 (Punkt C / RITM+NVST): Pre-Market-Radar-Modus — eigene
    # Fruehwarn-Mail im PM-Fenster, bewusst einfachere Gates (siehe
    # _classify_premarket_candidate), eigener Kanal + Cooldown-Namespace.
    premarket_mail_mode = False
    send_time_utc = datetime.now(timezone.utc)
    market_status: Dict[str, Any] = {}
    if market_type == "stocks":
        try:
            market_status = _stock_trade_email_status(send_time_utc)
        except TypeError:
            # Some unit tests monkeypatch the helper as a no-arg lambda.
            market_status = _stock_trade_email_status()
        if not market_status.get("allowed"):
            if _premarket_window_active(send_time_utc):
                premarket_mail_mode = True
            # AUDIT K-2b (PRODUKTENTSCHEIDUNG, final): Nach US-Daily-Close ist
            # die Bestaetigung eines Daily-Breakouts legitim — sonst waere der
            # C&H-Kanal architektonisch tot (intraday unterdrueckt K-2a, nach
            # Close blockte das Session-Gate alles). ENG begrenzte Ausnahme:
            # nur wenn ALLE Rows BREAKOUT_CONFIRMED + heutige Tageskerze.
            elif _strategy_rows_daily_close_confirmed(results):
                daily_close_confirmed_mode = True
            else:
                reason = str(market_status.get("reason") or "US market closed")
                print(f"[Alert] Aktien Strategie - {strategy_name}: SKIP stock strategy mail outside US regular session ({reason})")
                _record_email_event(
                    f"Aktien Strategie Alert - {strategy_name}",
                    "skipped",
                    f"stock_market_closed_before_strategy_mail:{reason}",
                )
                return
    now = time.time()
    alerts = []
    suppressed: Dict[str, int] = {}
    grade_counts: Dict[str, int] = {}
    seen_cooldown_keys = set()
    for row in results[:50]:
        if not isinstance(row, dict):
            continue
        grade_for_counts = _extract_alert_grade(row) or "UNKNOWN"
        grade_counts[grade_for_counts] = grade_counts.get(grade_for_counts, 0) + 1
        if scanner_key in _STOCK_ALERT_SCANNERS and not premarket_mail_mode:
            row = _enrich_stock_alert_5m_state(scanner_key, row, strategy_name)
        if scanner_key == "stock_strategy" and not premarket_mail_mode:
            row_strategy = str(row.get("Strategy") or row.get("strategy") or strategy_name or "").lower()
            if "momentum breakout long" in row_strategy:
                row = _stock_breakout_freshness_state(
                    row,
                    daily_close_confirmed_mode=daily_close_confirmed_mode,
                )
            mail_quality_ok, mail_quality_reason = _stock_strategy_mail_quality_state(
                row,
                daily_close_confirmed_mode=daily_close_confirmed_mode,
                market_status=market_status,
                now_utc=send_time_utc,
            )
            if not mail_quality_ok:
                reason_key = mail_quality_reason or "stock_strategy_mail_quality_gate"
                suppressed[reason_key] = suppressed.get(reason_key, 0) + 1
                continue
        if premarket_mail_mode:
            state = _classify_premarket_candidate(scanner_key, row, now)
        else:
            state = _classify_alert_candidate(scanner_key, row, now)
        if daily_close_confirmed_mode and state.get("cooldown_key"):
            # AUDIT K-2b: eigener Dedupe-Namespace fuer die Daily-Close-Mail
            # (Suffix _dailyclose), damit pro Ticker und Tag genau eine
            # Bestaetigungs-Mail rausgeht — unabhaengig vom Intraday-Cooldown.
            _dc_key = f"{state['cooldown_key']}_dailyclose"
            state["cooldown_key"] = _dc_key
            _dc_ttl = _alert_dedupe_ttl_seconds(scanner_key)
            _dc_last = _EMAIL_COOLDOWN.get(_dc_key)
            if (_dc_last and (now - _dc_last) < _dc_ttl) or _email_dedupe_remaining(_dc_key, _dc_ttl, now) > 0:
                state["alertable_now"] = False
                state["suppression_reasons"] = list(state.get("suppression_reasons") or []) + ["dailyclose_dedupe_active"]
        if not state["alertable_now"]:
            for reason in state["suppression_reasons"]:
                suppressed[reason] = suppressed.get(reason, 0) + 1
            continue
        if state["cooldown_key"] in seen_cooldown_keys:
            suppressed["duplicate_ticker_in_scan"] = suppressed.get("duplicate_ticker_in_scan", 0) + 1
            continue
        seen_cooldown_keys.add(state["cooldown_key"])
        alerts.append({
            "cooldown_key": state["cooldown_key"],
            "ticker": state["ticker"],
            "grade": state["grade"],
            "score": state["score"],
            "price": state["price"],
            "rvol": _alert_float(state["rvol"], 0) or 0,
            "premarket": premarket_mail_mode,
            "pm_dollar_vol": _alert_float(state.get("pm_dollar_vol"), 0) or 0,
            "change_pct": _alert_float(_alert_get_any(row, "change_pct", "Change_Pct", "Change%", "Change %", "Änderung%", default=0), 0) or 0,
            "entry_quality": row.get("entry_quality") or row.get("long_entry_quality") or ("SWING_SETUP" if scanner_key in _SWING_STOCK_STRATEGY_ALERT_SCANNERS else ""),
            "strategy": row.get("Strategy") or row.get("strategy") or strategy_name,
            "market_type": market_type,
            "trade_plan_html": _format_alert_plan_html(row),
            "source_row": row,  # Signal-Tracking: Row mit Entry/StopLoss/TP-Feldern
        })

    if not alerts:
        if market_type == "stocks":
            _record_email_event(
                f"Aktien Strategie Alert - {strategy_name}",
                "skipped",
                f"no_alertable_strategy_setups:{_format_alert_suppression_summary(suppressed, grade_counts)}",
            )
        return

    total_alerts = len(alerts)
    email_alerts = [
        alert for alert in alerts[:_ALERT_EMAIL_MAX_ROWS]
        if _email_dedupe_claim(
            alert["cooldown_key"],
            _alert_dedupe_ttl_seconds(scanner_key),
            now=now,
        )
    ]
    if not email_alerts:
        _record_email_event(
            f"{'Crypto' if market_type == 'crypto' else 'Aktien'} Strategie Alert - {strategy_name}",
            "skipped",
            "all_strategy_rows_claimed_by_parallel_sender",
        )
        return

    rows = ""
    for a in email_alerts:
        timing_label = html.escape(_format_alert_timing_label(a.get("entry_quality"), market_type))
        # AUDIT 2026-07-29 (NVST): Strategiename 'Gap Momentum' ohne sichtbaren
        # Gap-Beleg verwirrt — die Mail zeigt das gemessene Gap (Open vs.
        # Vortagesschluss) jetzt explizit unter der Tagesaenderung.
        _src_row = a.get("source_row") or {}
        _gap_pct = _alert_float(_alert_get_any(_src_row, "Gap_Pct", "gap_pct"), None)
        _gap_suffix = (
            f'<br><span style="color:#64748b;font-size:11px">Gap {_gap_pct:+.1f}% (Open vs. Vortagesschluss)</span>'
            if _gap_pct is not None and abs(_gap_pct) >= 1.0
            else ""
        )
        # PM-Radar: RVOL-Spalte zeigt das absolute PM-Dollar-Volumen (der
        # ehrliche PM-Massstab), nicht den unvergleichbaren Ganztages-RVOL.
        if a.get("premarket") and a.get("pm_dollar_vol"):
            _rvol_cell = f'PM ${a["pm_dollar_vol"] / 1_000_000:.1f}M'
        else:
            _rvol_cell = f'{a["rvol"]:.1f}x'
        rows += (
            f'<tr><td style="padding:8px;border-bottom:1px solid #eee"><b>{a["ticker"]}</b></td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{a["strategy"]}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{a["grade"]}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{a["score"]}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{_format_alert_price(a["price"])}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{a["change_pct"]:+.1f}%{_gap_suffix}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{_rvol_cell}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{a["trade_plan_html"]}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{timing_label}</td></tr>'
        )
    label = "Crypto Strategie" if market_type == "crypto" else "Aktien Strategie Swing"
    if premarket_mail_mode:
        label = "Aktien Pre-Market Radar"
    horizon_note = (
        "Swing-Setup: mehrtaegiger Plan. Entry/Stop/TP sind Struktur-Level; "
        "nicht als Intraday-Scalp oder sofortiger Minuten-TP interpretieren. "
        "Nach TP1: Teilgewinn/Freeroll planen und Stop mindestens Richtung Entry nachziehen."
        if market_type == "stocks"
        else "Crypto Strategie-Alert: nur mit bestaetigtem Exchange-Trigger handeln."
    )
    if premarket_mail_mode:
        horizon_note = (
            "PRE-MARKET-FRUEHWARNUNG: duenne Liquiditaet, weite Spreads, der Kurs kann sich zum Open "
            "stark veraendern. KEIN Market-Einstieg — nur Limit-Orders, kleine Positionsgroesse; "
            "Abwarten der Eroeffnungsrange ist oft der bessere Einstieg. Volumen-Angabe = absolutes "
            "PM-Dollar-Volumen (kein Ganztages-RVOL). Die regulaere Swing-Mail nach US-Open bleibt "
            "davon unberuehrt (eigener Cooldown)."
        )
    trigger_note = (
        "Intraday-Trigger sind optional und gehoeren in den separaten Intraday-Modus, nicht in diese Swing-Mail."
        if market_type == "stocks"
        else "Nur Score, Grade, frische Trigger-Qualitaet und Cooldown-Gates."
    )
    count_text = f"{len(email_alerts)} von {total_alerts}" if total_alerts > len(email_alerts) else str(len(email_alerts))
    _score_floor_shown = _PREMARKET_MIN_SCORE if premarket_mail_mode else _ALERT_MIN_SCORE
    # AUDIT K-2b: Daily-Close-Bestaetigung klar labeln (Betreff + Body-Hinweis).
    _dailyclose_subject_suffix = ""
    _dailyclose_hint = ""
    if daily_close_confirmed_mode:
        _dailyclose_subject_suffix = " (Daily Close bestätigt)"
        _entry_levels = ", ".join(
            f"{_format_alert_price(_alert_get_any(a.get('source_row') or {}, 'entry', 'Entry', default=a['price']))} ({a['ticker']})"
            for a in email_alerts
        )
        _dailyclose_hint = (
            '<p style="background:#ecfdf5;border:1px solid #6ee7b7;border-radius:8px;'
            'padding:10px;color:#065f46;font-size:13px">'
            f"Bestätigt per Tagesschluss — Entry-Planung für die nächste Session über {_entry_levels}</p>"
        )
    # Klumpenrisiko-Hinweis (ADR-Cluster / Mehrfach-Mover) — nur Aktien-Mails:
    # in Crypto-Sweeps waere Regel B (Mover >5%) quasi immer aktiv => Warn-Fatigue.
    _cluster_hint = _cluster_warning_html(email_alerts) if market_type == "stocks" else ""
    body = f'''<html><body style="font-family:Arial,sans-serif;max-width:760px;margin:0 auto">
    <h2 style="color:#1a73e8">{label} Alert - {strategy_name}</h2>
    <p style="color:#666">{_mail_timestamp_dual()} | Top {count_text} S/A Setup(s) ab Score {_score_floor_shown}</p>
    <p style="background:#eef6ff;border:1px solid #bfdbfe;border-radius:8px;padding:10px;color:#1e3a8a;font-size:13px">{horizon_note}</p>
    {_cluster_hint}
    {_dailyclose_hint}
    <table style="width:100%;border-collapse:collapse;font-size:13px">
    <tr style="background:#f5f5f5"><th style="padding:8px;text-align:left">Ticker</th>
    <th style="padding:8px;text-align:left">Strategie</th><th style="padding:8px;text-align:left">Grade</th>
    <th style="padding:8px;text-align:left">Score</th><th style="padding:8px;text-align:left">Preis</th>
    <th style="padding:8px;text-align:left">Change</th><th style="padding:8px;text-align:left">RVOL</th>
    <th style="padding:8px;text-align:left">Entry / Stop / TP</th><th style="padding:8px;text-align:left">Timing</th></tr>
    {rows}</table>
    <p style="color:#999;font-size:12px;margin-top:20px">Nur Score >= {_score_floor_shown}, Grade S/A/A+ und Alert-Gates; 8h Cooldown pro Ticker. {trigger_note}</p>
    </body></html>'''
    _signal_rows = [dict(a.get("source_row") or {}, ticker=a["ticker"], grade=a["grade"], score=a["score"], price=a["price"], strategy=a.get("strategy", strategy_name)) for a in email_alerts]
    try:
        sent = _send_email_alert(f"{label}: Top {count_text} Setup(s) - {strategy_name}{_dailyclose_subject_suffix}", body, trade_horizon="swing", mail_class="swing_trade", telegram_text=_safe_format_telegram_rows(_signal_rows), mail_channel=("stocks_premarket" if premarket_mail_mode else "stocks_swing"))  # AUDIT H-3 / H-2 (Strategie-Sweep); K-2b: sichtbarer SWING-Betreff, Signal-Tracking bleibt unten trade; 2026-07-29: PM-Radar eigener Kanal
    except Exception:
        for alert in email_alerts:
            _email_dedupe_release(alert["cooldown_key"], claimed_at=now)
        raise
    if sent:
        for alert in email_alerts:
            if alert.get("cooldown_key"):
                _EMAIL_COOLDOWN[alert["cooldown_key"]] = now
                _email_dedupe_mark(alert["cooldown_key"], now=now)
        _safe_record_alert_signals(scanner_key, _signal_rows)
    else:
        for alert in email_alerts:
            _email_dedupe_release(alert["cooldown_key"], claimed_at=now)


def _new_listing_nested_signal(entry: Dict[str, Any]) -> Dict[str, Any]:
    sig = entry.get("signal", {}) if isinstance(entry, dict) else {}
    return sig if isinstance(sig, dict) else {}


def _new_listing_age_sort_value(value: Any) -> float:
    """Keep a valid zero-hour listing first; unknown/invalid ages sort last."""
    try:
        age = float(value)
    except (TypeError, ValueError):
        return float("inf")
    return age if math.isfinite(age) and age >= 0 else float("inf")


def _new_listing_watch_candidates(payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    candidates: List[Dict[str, Any]] = []
    if not isinstance(payload, dict):
        return candidates

    for bucket in ("signals", "watchlist"):
        for entry in payload.get(bucket, []) or []:
            if not isinstance(entry, dict):
                continue
            sig = _new_listing_nested_signal(entry)
            fields = _extract_new_listing_signal_fields(entry)
            if fields["listing_source"] != "new_listing":
                continue
            if _new_listing_exchange_mismatch(entry):
                continue
            if entry.get("announcement_source") and "contract_confirmed" in entry and not _alert_bool(entry.get("contract_confirmed")):
                continue
            symbol = _display_crypto_contract_symbol(entry.get("symbol") or sig.get("symbol") or "")
            if not symbol:
                continue
            pump = sig.get("pump_data", {}) if isinstance(sig.get("pump_data", {}), dict) else {}
            candidates.append({
                "symbol": symbol,
                "exchange": entry.get("exchange", ""),
                "bucket": bucket,
                "grade": fields["grade"] or str(entry.get("grade", "") or ""),
                "timing": sig.get("timing", entry.get("timing", "")),
                "category": fields["trade_category"] or sig.get("trade_category", entry.get("trade_category", "")),
                "age": fields["listing_age_hours"],
                "pump_pct": _alert_float(pump.get("pump_pct", entry.get("pump_pct")), 0) or 0,
                "from_ath_pct": _alert_float(pump.get("from_ath_pct", entry.get("from_ath_pct")), 0) or 0,
                "exh_score": _alert_float(sig.get("exh_score", entry.get("exh_score")), 0) or 0,
                "rr": fields["rr_effective"],
                "btc_change": _alert_float(pump.get("btc_change_pct", sig.get("btc_change_pct")), None),
                "coin_change": _alert_float(pump.get("coin_change_pct", sig.get("coin_change_pct")), None),
                "btc_divergence": _alert_float(pump.get("btc_divergence", sig.get("btc_divergence")), None),
                "btc_context": str(pump.get("btc_short_context", sig.get("btc_short_context", "")) or ""),
                "risk_flags": sig.get("risk_flags", entry.get("risk_flags", [])) if isinstance(sig.get("risk_flags", entry.get("risk_flags", [])), list) else [],
                "title": entry.get("announcement_title", ""),
                "url": entry.get("announcement_url", ""),
                "listing_source": fields["listing_source"],
            })

    for item in payload.get("monitoring", []) or []:
        if not isinstance(item, dict):
            continue
        listing_source = item.get("source") if item.get("source") == "new_listing" else item.get("listing_source")
        if listing_source != "new_listing":
            continue
        if _new_listing_exchange_mismatch(item):
            continue
        if item.get("announcement_source") and "contract_confirmed" in item and not _alert_bool(item.get("contract_confirmed")):
            continue
        category = str(item.get("trade_category", "") or "")
        if category in ("ALREADY_DUMPED", "NEW_LISTING_EXPIRED"):
            continue
        symbol = _display_crypto_contract_symbol(item.get("symbol", ""))
        if not symbol:
            continue
        candidates.append({
            "symbol": symbol,
            "exchange": item.get("exchange", ""),
            "bucket": "monitoring",
            "grade": item.get("grade", ""),
            "timing": item.get("timing", ""),
            "category": category or "NEW_LISTING_WATCH",
            "age": _alert_float(item.get("listing_age_hours")),
            "pump_pct": _alert_float(item.get("pump_pct"), 0) or 0,
            "from_ath_pct": _alert_float(item.get("from_ath_pct"), 0) or 0,
            "exh_score": _alert_float(item.get("exh_score"), 0) or 0,
            "rr": _alert_float(item.get("rr_effective"), 0) or 0,
            "btc_change": _alert_float(item.get("btc_change_pct"), None),
            "coin_change": _alert_float(item.get("coin_change_pct"), None),
            "btc_divergence": _alert_float(item.get("btc_divergence"), None),
            "btc_context": str(item.get("btc_short_context", "") or ""),
            "risk_flags": item.get("risk_flags", []) if isinstance(item.get("risk_flags", []), list) else [],
            "title": item.get("announcement_title", ""),
            "url": item.get("announcement_url", ""),
            "listing_source": listing_source,
        })

    deduped: Dict[str, Dict[str, Any]] = {}
    for candidate in candidates:
        key = candidate["symbol"]
        old = deduped.get(key)
        candidate_rank = (
            candidate["bucket"] == "signals",
            candidate["bucket"] in ("watchlist", "monitoring"),
            candidate["bucket"] == "announcement",
            candidate["exh_score"] or 0,
            candidate["rr"] or 0,
        )
        old_rank = (
            old["bucket"] == "signals",
            old["bucket"] in ("watchlist", "monitoring"),
            old["bucket"] == "announcement",
            old["exh_score"] or 0,
            old["rr"] or 0,
        ) if old else None
        if old is None or candidate_rank > old_rank:
            deduped[key] = candidate
    visible = []
    for c in deduped.values():
        score = c.get("exh_score") or 0
        pump_pct = c.get("pump_pct") or 0
        rr = c.get("rr") or 0
        grade = str(c.get("grade") or "").upper()
        flags = set(c.get("risk_flags") or [])
        watch_quality = (
            grade in _ALERT_TOP_GRADES
            and score >= _NEW_LISTING_WATCH_MIN_SCORE
            and rr >= _NEW_LISTING_WATCH_MIN_RR
            and not (flags & _NEW_LISTING_WATCH_BLOCK_FLAGS)
        )
        if pump_pct >= _NEW_LISTING_WATCH_MIN_PUMP_PCT and watch_quality:
            visible.append(c)
    return sorted(
        visible,
        key=lambda c: (
            c["bucket"] == "announcement",
            c["bucket"] != "signals",
            -(c["exh_score"] or 0),
            _new_listing_age_sort_value(c.get("age")),
        ),
    )[:12]


def _send_new_listing_watch_email(payload: Dict[str, Any], suppressed: Optional[Dict[str, int]] = None, now: Optional[float] = None) -> bool:
    if not _NEW_LISTING_SEND_DUMP_WATCH_EMAILS:
        _record_email_event("Crypto New Listing Dump-Watch", "skipped", "new_listing_dump_watch_emails_disabled")
        return False
    now = now or time.time()
    candidates = _new_listing_watch_candidates(payload)
    if not candidates:
        _record_email_event("Crypto New Listing Dump-Watch", "skipped", "no_new_listing_dump_watch_candidates")
        return False

    watch_dt = datetime.fromtimestamp(now, timezone.utc)
    day_key = watch_dt.strftime("%Y%m%d")
    dedupe_key = f"new_listing_watch_{day_key}"
    if not _email_dedupe_claim(dedupe_key, _NEW_LISTING_WATCH_DEDUPE_SEC, now=now):
        _record_email_event("Crypto New Listing Dump-Watch", "skipped", "daily_dump_watch_dedupe_active")
        return False

    def _fmt(value, suffix="", default="-"):
        if value is None:
            return default
        try:
            return f"{float(value):.1f}{suffix}"
        except (TypeError, ValueError):
            return str(value)

    def _safe(value: Any) -> str:
        return html.escape(str(value or ""), quote=True)

    def _watch_action(c: Dict[str, Any]) -> Tuple[str, str]:
        flags = set(c.get("risk_flags") or [])
        if "btc_risk_on_wait_for_deeper_crack" in flags:
            return "WARTEN", "BTC ist nicht klar bearish - tieferen 5m Crack abwarten."
        if "micro_trigger_missing" in flags or "wait_for_dump_trigger" in flags:
            return "WARTEN", "5m Strukturbruch/Rejection fehlt noch."
        if "turn_not_confirmed" in flags or "crack_structure_weak" in flags:
            return "WARTEN", "Turn/Rejection ist noch zu schwach."
        return "BEOBACHTEN", "Nur beobachten - Short-Freigabe fehlt."

    def _missing_steps(c: Dict[str, Any]) -> str:
        flags = set(c.get("risk_flags") or [])
        priority = [
            "micro_trigger_missing",
            "wait_for_dump_trigger",
            "btc_risk_on_wait_for_deeper_crack",
            "turn_not_confirmed",
            "crack_structure_weak",
            "no_first_crack",
            "pump_continuation_risk",
        ]
        labels = [_alert_reason_label(flag) for flag in priority if flag in flags]
        if not labels:
            labels = ["5m Crack/Rejection, Safety OK und R:R muessen fuer die Short-Mail passen"]
        return "<br>".join(f"- {_safe(label)}" for label in labels[:4])

    rows = ""
    for c in candidates:
        action, action_note = _watch_action(c)
        title = str(c.get("title") or c.get("timing") or "")
        if len(title) > 95:
            title = title[:92] + "..."
        link = f'<br><a href="{_safe(c.get("url"))}" style="color:#2563eb">Quelle</a>' if c.get("url") else ""
        why = (
            f'Pump {_fmt(c["pump_pct"], "%")}, Abstand ATH {_fmt(c["from_ath_pct"], "%")}, '
            "aber noch kein bestaetigter Short-Trigger."
        )
        rows += (
            f'<tr><td style="padding:10px;border-bottom:1px solid #eee;vertical-align:top"><b>{_safe(c["symbol"])}</b><br><span style="color:#777">{_safe(c["exchange"])}</span>{link}</td>'
            f'<td style="padding:10px;border-bottom:1px solid #eee;vertical-align:top"><span style="display:inline-block;background:#fee2e2;color:#991b1b;font-weight:700;border-radius:6px;padding:3px 7px">NICHT SHORTEN</span><br><b>{_safe(action)}</b><br><span style="color:#555">{_safe(action_note)}</span></td>'
            f'<td style="padding:10px;border-bottom:1px solid #eee;vertical-align:top">{_safe(why)}<br><span style="color:#777">Alter {_fmt(c["age"], "h")} | {_safe(title)}</span></td>'
            f'<td style="padding:10px;border-bottom:1px solid #eee;vertical-align:top"><b>{_safe(c["grade"] or "-")} / {int(c["exh_score"] or 0)}</b><br>{_fmt(c["rr"], "R")}<br><span style="color:#777">BTC {_fmt(c["btc_change"], "%")} | Coin {_fmt(c["coin_change"], "%")} | Div {_fmt(c["btc_divergence"], "%")}</span></td>'
            f'<td style="padding:10px;border-bottom:1px solid #eee;vertical-align:top;color:#92400e">{_missing_steps(c)}</td></tr>'
        )

    suppressed_text = ""
    if suppressed:
        suppressed_text = "<p style='color:#777;font-size:12px'>Warum keine Jetzt-Short-Mail: " + ", ".join(f"{_safe(_alert_reason_label(k))}: {v}" for k, v in sorted(suppressed.items())) + "</p>"
    body = f'''<html><body style="font-family:Arial,sans-serif;max-width:980px;margin:0 auto">
    <h2 style="color:#f97316">Crypto New Listing Dump-Watch - NICHT SHORTEN</h2>
    <p style="color:#666">{_mail_timestamp_dual(watch_dt)} | {len(candidates)} Coin(s) nur zur Beobachtung</p>
    <div style="background:#fff7ed;border:1px solid #fed7aa;border-radius:10px;padding:12px;margin:12px 0;color:#7c2d12">
      <b>Was jetzt tun?</b> Nicht shorten. Chart aktiv beobachten und auf die separate <b>Jetzt-Short-Mail</b> warten.
      Diese Dump-Watch-Mail bedeutet nur: New Listing hat bereits gepumpt, aber 5m Crack/Rejection, Safety oder Timing sind noch nicht voll bestaetigt.
    </div>
    {suppressed_text}
    <table style="width:100%;border-collapse:collapse;font-size:13px">
    <tr style="background:#fff7ed"><th style="padding:8px;text-align:left">Coin</th>
    <th style="padding:8px;text-align:left">Aktion</th><th style="padding:8px;text-align:left">Warum im Blick</th>
    <th style="padding:8px;text-align:left">Qualitaet</th><th style="padding:8px;text-align:left">Was fehlt</th></tr>
    {rows}</table>
    <p style="color:#999;font-size:12px;margin-top:20px">Dump-Watch-Mail maximal 1x taeglich und nur nach Pump >= {_NEW_LISTING_WATCH_MIN_PUMP_PCT:.0f}%, Score >= {_NEW_LISTING_WATCH_MIN_SCORE}, R:R >= {_NEW_LISTING_WATCH_MIN_RR:.1f}R und ohne Safety-/Low-Quality-Blocker. JETZT SHORTEN kommt separat nur bei 5m Micro-Crack/Rejection, Safety OK, ausreichendem R:R und New-Listing-Alter im Fenster.</p>
    </body></html>'''
    sent = _send_email_alert(
        f"Crypto New Listing Dump-Watch: {len(candidates)} Coin(s) - NICHT SHORTEN",
        body,
        trade_horizon="swing",
        mail_class="watch",
        mail_channel="new_listing",
    )  # AUDIT H-3 / H-2 (Beobachtung, kein Einstiegssignal)
    if not sent:
        _email_dedupe_release(dedupe_key, claimed_at=now)
    return bool(sent)


def _send_new_listing_pipeline_alerts(payload: Dict[str, Any]) -> None:
    """Mail S/A active Pump-&-Dump short signals from the FastAPI pipeline."""
    signals = payload.get("signals", []) if isinstance(payload, dict) else []
    if not signals:
        _send_new_listing_watch_email(payload if isinstance(payload, dict) else {})
        return
    now = time.time()
    alerts = []
    suppressed: Dict[str, int] = {}

    def _fmt_pct(value: Any) -> str:
        number = _alert_float(value)
        if number is None:
            return "-"
        return f"{number:.1f}%"

    for entry in signals:
        if not isinstance(entry, dict):
            continue
        sig = entry.get("signal", {}) or {}
        fields = _extract_new_listing_signal_fields(entry)
        state = _classify_alert_candidate("new_listing", entry, now)
        if not state.get("alertable_now"):
            for reason in state.get("suppression_reasons", []):
                suppressed[reason] = suppressed.get(reason, 0) + 1
            continue
        symbol = _display_crypto_contract_symbol(entry.get("symbol") or sig.get("symbol") or "")
        cooldown_key = state.get("cooldown_key") or f"new_listing_{symbol}"
        pump = sig.get("pump_data", {}) if isinstance(sig.get("pump_data", {}), dict) else {}
        alerts.append({
            "symbol": symbol,
            "exchange": entry.get("exchange", ""),
            "grade": fields["grade"],
            "timing": sig.get("timing", ""),
            "setup": sig.get("setup_type", ""),
            "stop_model": sig.get("stop_model", ""),
            "entry": sig.get("entry", 0),
            "stop": sig.get("stop_loss", sig.get("stop", 0)),
            "tp1": sig.get("tp1", 0),
            "tp2": sig.get("tp2", 0),
            "rr": fields["rr_effective"],
            "exh_score": state.get("score", 0),
            "micro_score": pump.get("micro_score", 0),
            "btc_change": pump.get("btc_change_pct", sig.get("btc_change_pct")),
            "coin_change": pump.get("coin_change_pct", sig.get("coin_change_pct")),
            "btc_divergence": pump.get("btc_divergence", sig.get("btc_divergence")),
            "btc_context": pump.get("btc_short_context", sig.get("btc_short_context", "")),
            "cooldown_key": cooldown_key,
        })
    if not alerts:
        if suppressed:
            _record_email_event("Pump & Dump SHORT Alert", "skipped", f"no_active_short_signals:{suppressed}")
        _send_new_listing_watch_email(payload if isinstance(payload, dict) else {}, suppressed=suppressed, now=now)
        return

    email_alerts = [
        alert for alert in alerts[:10]
        if _email_dedupe_claim(
            alert["cooldown_key"],
            _alert_dedupe_ttl_seconds("new_listing"),
            now=now,
        )
    ]
    if not email_alerts:
        _record_email_event(
            "Pump & Dump SHORT Alert",
            "skipped",
            "all_short_rows_claimed_by_parallel_sender",
        )
        return

    rows = ""
    for a in email_alerts:
        rows += (
            f'<tr><td style="padding:8px;border-bottom:1px solid #eee"><b>{a["symbol"]}</b></td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{a["exchange"]}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{a["grade"]}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{a["setup"] or a["timing"]}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">${a["entry"]}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">${a["stop"]}<br><span style="color:#999;font-size:11px">{a["stop_model"]}</span></td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">${a["tp1"]} / ${a["tp2"]}</td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">{a["rr"]}R<br><span style="color:#999;font-size:11px">Micro {a["micro_score"]}</span></td>'
            f'<td style="padding:8px;border-bottom:1px solid #eee">BTC {_fmt_pct(a["btc_change"])}<br>Coin {_fmt_pct(a["coin_change"])}<br>Div {_fmt_pct(a["btc_divergence"])}</td></tr>'
        )
    body = f'''<html><body style="font-family:Arial,sans-serif;max-width:820px;margin:0 auto">
    <h2 style="color:#dc2626">Pump & Dump SHORT Alert</h2>
    <p style="color:#666">{_mail_timestamp_dual()} | {len(email_alerts)} aktive S/A Signale ab Score {_ALERT_MIN_SCORE}</p>
    <table style="width:100%;border-collapse:collapse;font-size:13px">
    <tr style="background:#fef2f2"><th style="padding:8px;text-align:left">Coin</th>
    <th style="padding:8px;text-align:left">Exchange</th><th style="padding:8px;text-align:left">Grade</th>
    <th style="padding:8px;text-align:left">Timing</th><th style="padding:8px;text-align:left">Entry</th>
    <th style="padding:8px;text-align:left">Stop</th><th style="padding:8px;text-align:left">TP1/TP2</th>
    <th style="padding:8px;text-align:left">R</th><th style="padding:8px;text-align:left">BTC</th></tr>
    {rows}</table>
    <p style="color:#999;font-size:12px;margin-top:20px">Nur echte New-Listing-Dump JETZT-SHORTEN Signale: Score >= {_ALERT_MIN_SCORE}, New-Listing-Quelle + gueltiges Listing-Alter, Timing-Quality >=4, Safety OK, erster Crack/Rejection bestaetigt, kein Pump-Continuation-Risk, TP-Zonen nicht verpasst, R:R >= {_NEW_LISTING_MIN_ALERT_RR}; Active-Pumps bleiben Beobachtung ohne Trade-Mail; 8h Cooldown pro Coin.</p>
    </body></html>'''
    try:
        sent = _send_email_alert(f"Pump & Dump: {len(email_alerts)} SHORT Top-Signal(e)", body, trade_horizon="swing", mail_class="trade", telegram_text=_safe_format_telegram_rows(email_alerts), mail_channel="new_listing")  # AUDIT H-3 / H-2
    except Exception:
        for alert in email_alerts:
            _email_dedupe_release(alert["cooldown_key"], claimed_at=now)
        raise
    if sent:
        for alert in email_alerts:
            _EMAIL_COOLDOWN[alert["cooldown_key"]] = now
            _email_dedupe_mark(alert["cooldown_key"], now=now)
        _safe_record_alert_signals("new_listing", email_alerts)
    else:
        for alert in email_alerts:
            _email_dedupe_release(alert["cooldown_key"], claimed_at=now)


# Cleanup cooldown (alle 4h wird automatisch bereinigt)
def _cleanup_email_cooldown():
    # AUDIT M-Cooldown-Lock: Snapshot der Items unter Lock — verhindert
    # RuntimeError("dictionary changed size during iteration") bei parallelen
    # Scanner-Threads, die waehrend des Cleanups Cooldowns setzen.
    now = time.time()
    with _EMAIL_COOLDOWN_LOCK:
        expired = [k for k, ts in list(_EMAIL_COOLDOWN.items()) if now - ts > _EMAIL_COOLDOWN_SEC]
        for k in expired:
            _EMAIL_COOLDOWN.pop(k, None)


