def _scan_runtime_state(
    scan_name: str,
    scan_state: Dict[str, Any],
    now_ts: Optional[float] = None,
    timeout_minutes: Optional[float] = None,
) -> Dict[str, Any]:
    """Return scanner runtime health without mutating or restarting its worker."""
    running = bool(scan_state.get("running"))
    started_at = _alert_float(scan_state.get("_started_at"), 0.0) or 0.0
    elapsed_seconds = int(max(0.0, (now_ts or time.time()) - started_at)) if running and started_at else 0
    configured_timeout = timeout_minutes if timeout_minutes is not None else _SCAN_TIMEOUTS.get(scan_name, 10)
    timeout_minutes = max(0.01, float(configured_timeout))
    timed_out = bool(running and started_at and elapsed_seconds > timeout_minutes * 60)
    return {
        "runtime_health": "stuck" if timed_out else ("running" if running else "idle"),
        "runtime_seconds": elapsed_seconds if running else 0,
        "timeout_minutes": timeout_minutes,
        "timeout_exceeded": timed_out,
    }


def _scan_cache_health(scan_name: str, scan_state: Dict[str, Any]) -> Dict[str, Any]:
    """Expose whether a scanner cache is fresh enough for the UI."""
    cache_path = SCAN_CACHE_MAP.get(scan_name)
    runtime_error = scan_state.get("last_error")
    runtime = _scan_runtime_state(scan_name, scan_state)

    def _with_runtime(payload: Dict[str, Any]) -> Dict[str, Any]:
        payload["cache_data_health"] = payload.get("cache_health", "not_tracked")
        payload.update(runtime)
        if runtime["runtime_health"] == "running":
            payload["cache_health"] = "running"
        elif runtime["runtime_health"] == "stuck":
            payload["cache_health"] = "stuck"
            payload["scan_error"] = (
                f"Scan laeuft seit {runtime['runtime_seconds']}s; "
                f"Zeitbudget {runtime['timeout_minutes']}min ueberschritten"
            )
        return payload

    if not cache_path:
        return _with_runtime({
            "cache_file": None,
            "cache_exists": False,
            "cache_age_seconds": None,
            "cache_stale": None,
            "cache_health": "error" if runtime_error else "not_tracked",
            "scan_error": runtime_error,
        })

    cache_file = os.path.basename(cache_path)
    if not os.path.exists(cache_path):
        return _with_runtime({
            "cache_file": cache_file,
            "cache_exists": False,
            "cache_age_seconds": None,
            "cache_stale": True,
            "cache_health": "error" if runtime_error else "missing",
            "scan_error": runtime_error,
        })

    try:
        age_seconds = int(max(0, time.time() - os.path.getmtime(cache_path)))
        interval_seconds = max(60, int(scan_state.get("interval_min", 0) or 0) * 60)
        stale_after = max(interval_seconds * 2, interval_seconds + 15 * 60)
        stale = age_seconds > stale_after
        return _with_runtime({
            "cache_file": cache_file,
            "cache_exists": True,
            "cache_age_seconds": age_seconds,
            "cache_stale": stale,
            "cache_health": "error" if runtime_error else ("stale" if stale else "ok"),
            "scan_error": runtime_error,
        })
    except Exception as exc:
        return _with_runtime({
            "cache_file": cache_file,
            "cache_exists": True,
            "cache_age_seconds": None,
            "cache_stale": True,
            "cache_health": "error",
            "cache_error": str(exc),
        })


def _scan_cache_revision(cache_path: Optional[str]) -> Optional[tuple[int, int]]:
    """Return a stable cache revision, or None when no readable cache exists."""
    if not cache_path or not os.path.exists(cache_path):
        return None
    try:
        stat = os.stat(cache_path)
        with open(cache_path, "r", encoding="utf-8") as handle:
            payload = json.load(handle)
        if not isinstance(payload, dict) or not isinstance(payload.get("results"), list):
            return None
        return stat.st_mtime_ns, stat.st_size
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return None


_SCAN_PROGRESS_MAP = {
    "bi_long": "/tmp/bi_scan_progress_long.json",
    "bi_short": "/tmp/bi_scan_progress_short.json",
    "biotech": "/tmp/alpha_biotech_progress.json",
}


def _scan_cache_payload(cache_path: Optional[str]) -> Optional[Dict[str, Any]]:
    if not cache_path or not os.path.exists(cache_path):
        return None
    try:
        with open(cache_path, "r", encoding="utf-8") as handle:
            payload = json.load(handle)
        if not isinstance(payload, dict) or not isinstance(payload.get("results"), list):
            return None
        return payload
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return None


def _scan_progress_payload(scan_name: str) -> Optional[Dict[str, Any]]:
    progress_path = _SCAN_PROGRESS_MAP.get(scan_name)
    if not progress_path or not os.path.exists(progress_path):
        return None
    try:
        with open(progress_path, "r", encoding="utf-8") as handle:
            payload = json.load(handle)
        return payload if isinstance(payload, dict) else None
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return None


def _require_fresh_scan_cache(scan_name: str, previous_revision: Optional[tuple[int, int]]) -> None:
    """A successful scheduled scan must publish a new, readable snapshot."""
    cache_path = SCAN_CACHE_MAP.get(scan_name)
    if not cache_path:
        return
    current_revision = _scan_cache_revision(cache_path)
    if current_revision is None:
        raise RuntimeError(f"{scan_name} did not publish a readable cache")
    if current_revision == previous_revision:
        raise RuntimeError(f"{scan_name} finished without publishing a fresh cache")
    if scan_name in _SCAN_PROGRESS_MAP:
        payload = _scan_cache_payload(cache_path)
        if payload is None:
            raise RuntimeError(f"{scan_name} published an invalid cache payload")
        if payload.get("partial") is True:
            raise RuntimeError(f"{scan_name} published only a partial cache")
        progress = _scan_progress_payload(scan_name)
        progress_status = str((progress or {}).get("status", "")).lower()
        if progress_status != "done":
            raise RuntimeError(
                f"{scan_name} did not finish cleanly (progress {progress_status or 'missing'})"
            )

# Initialize last_run from cache files on startup (survives restarts)
def _init_scan_status_from_cache():
    """Read cache file timestamps to populate last_run on startup."""
    import os
    for scan_name, cache_path in SCAN_CACHE_MAP.items():
        if scan_name in _scan_status and os.path.exists(cache_path):
            try:
                with open(cache_path, "r") as f:
                    cache_data = json.load(f)
                cached_at = None
                # Neues Format: ISO string
                if isinstance(cache_data, dict) and cache_data.get("cached_at"):
                    cached_at = cache_data["cached_at"]
                # Altes Scanner-Format: Unix timestamp
                elif isinstance(cache_data, dict) and "timestamp" in cache_data:
                    ts = cache_data["timestamp"]
                    if isinstance(ts, (int, float)) and ts > 1000000000:
                        cached_at = datetime.fromtimestamp(ts).isoformat()
                # Fallback: File modification time
                if not cached_at:
                    cached_at = datetime.fromtimestamp(os.path.getmtime(cache_path)).isoformat()
                _scan_status[scan_name]["last_run"] = cached_at
                print(f"[Init] {scan_name} last_run restored: {cached_at}")
            except Exception as e:
                print(f"[Init] Could not read cache for {scan_name}: {e}")

_init_scan_status_from_cache()

