def _effective_scan_timing(
    status: Dict[str, Any],
    cache: Dict[str, Any],
    *,
    now_ts: Optional[float] = None,
) -> tuple[Optional[str], Optional[str]]:
    """Letzten/naechsten Scan-Zeitpunkt robust bestimmen (AUDIT 2026-07-29).

    bg-owned Scanner (seit H-9: bi_long/bi_short/biotech) laufen ausserhalb
    des api-Prozesses — deren In-Memory last_run/next_run veraltet oder fehlt,
    waehrend der geteilte Cache (/tmp/*.json) vom bg-Service frisch
    geschrieben wird. Wirksamer letzter Lauf = max(In-Memory, Cache-mtime);
    naechster Lauf = In-Memory next_run, wenn in der Zukunft, sonst
    letzter Lauf + Intervall. Verhindert irrefuehrende 'Letzter: vor 18h'-
    Anzeigen, obwohl der Scanner laeuft (und umgekehrt echte Staendigkeit).
    """
    now_ts = now_ts if now_ts is not None else time.time()
    interval_sec = max(60, int(status.get("interval_min", 0) or 0) * 60)

    def _parse_ts(value: Any) -> Optional[float]:
        if not value:
            return None
        try:
            return datetime.fromisoformat(str(value)).timestamp()
        except (ValueError, TypeError, OverflowError, OSError):
            return None

    candidates = []
    mem_last = _parse_ts(status.get("last_run"))
    if mem_last is not None:
        candidates.append(mem_last)
    cache_age = cache.get("cache_age_seconds")
    if cache.get("cache_exists") and isinstance(cache_age, (int, float)):
        candidates.append(now_ts - float(cache_age))
    last_ts = max(candidates) if candidates else None

    next_ts = _parse_ts(status.get("next_run"))
    if next_ts is None or next_ts <= now_ts:
        next_ts = (last_ts + interval_sec) if last_ts is not None else None

    last_iso = (
        datetime.fromtimestamp(last_ts).isoformat()
        if last_ts is not None
        else status.get("last_run")
    )
    next_iso = (
        datetime.fromtimestamp(next_ts).isoformat()
        if next_ts is not None
        else status.get("next_run")
    )
    return last_iso, next_iso


def _build_system_health() -> Dict[str, Any]:
    """Build a trader-facing health summary without triggering expensive scans."""
    with _scan_lock:
        scan_health = {}
        health_counts = {
            "ok": 0,
            "running": 0,
            "stuck": 0,
            "stale": 0,
            "missing": 0,
            "error": 0,
            "not_tracked": 0,
        }
        running_scans = []
        stale_or_missing = []
        stuck_scans = []

        for name, status in _scan_status.items():
            cache = _scan_cache_health(name, status)
            health_key = cache.get("cache_health", "not_tracked")
            health_counts[health_key] = health_counts.get(health_key, 0) + 1
            if status.get("running"):
                running_scans.append(name)
            if health_key == "stuck":
                stuck_scans.append(name)
            if health_key in ("stale", "missing", "error", "stuck"):
                stale_or_missing.append(name)
            effective_last_run, effective_next_run = _effective_scan_timing(status, cache)
            scan_health[name] = {
                "running": status.get("running", False),
                "last_run": effective_last_run,
                "last_attempt_at": status.get("last_attempt_at"),
                "next_run": effective_next_run,
                "interval_min": status.get("interval_min"),
                **cache,
            }

    api_keys = {
        "market_data": bool(POLYGON_KEY),
        "catalyst_data": bool(BPIQ_API_KEY),
        "ai_assistant": bool(ANTHROPIC_API_KEY),
    }
    email_alerts = _email_alert_status()
    email_pipeline = _email_pipeline_summary()

    warnings = []
    critical = []
    if not api_keys["market_data"]:
        critical.append("Market-Data-Zugang fehlt - Aktien-/ORB-/Marktdaten koennen nicht sauber laufen")
    if not email_alerts["configured"]:
        warnings.append("Email-Alerts sind nicht konfiguriert - GMAIL_USER/GMAIL_APP_PASSWORD fehlen")
    if not _scheduler_running:
        warnings.append("Background-Scheduler ist nicht aktiv")
    cache_problems = [name for name in stale_or_missing if name not in stuck_scans]
    if cache_problems:
        warnings.append(f"{len(cache_problems)} Scanner-Datenstaende sind alt, fehlen oder haben Fehler")
    if stuck_scans:
        warnings.append(f"{len(stuck_scans)} Scanner ueberschreiten ihr Laufzeitbudget")
    last_email_event = email_pipeline.get("last_event") or {}
    if str(last_email_event.get("status") or "").lower() == "error":
        warnings.append("Der letzte Mail-Versuch ist technisch fehlgeschlagen")

    overall = "critical" if critical else ("warning" if warnings else "healthy")
    return {
        "status": overall,
        "version": API_VERSION,
        "timestamp": datetime.now().isoformat(),
        "api_keys_configured": api_keys,
        "email_alerts": email_alerts,
        "email_pipeline": email_pipeline,
        "scheduler": {
            "running": _scheduler_running,
            "total_scans": len(_scan_status),
            "running_scans": running_scans,
            "stuck_scans": stuck_scans,
            "stale_or_missing_scans": stale_or_missing,
            "health_counts": health_counts,
        },
        "scans": scan_health,
        "calendar": {
            "official_sources": ["Federal Reserve", "BLS", "BEA", "Census", "ISM", "NYSE/Nasdaq", "LSE", "Deutsche Boerse", "JPX", "HKEX"],
            "official_event_families": ["FOMC/FED", "CPI", "NFP", "PPI", "GDP/PCE", "Retail Sales", "Advance Economic Indicators", "ISM PMI"],
            "exchange_calendars": ["NYSE/Nasdaq", "LSE", "Xetra/Frankfurt", "Tokyo", "Hong Kong"],
            "estimated_event_families": ["Earnings Season", "Initial Jobless Claims"],
            "quality": "official_core_macro_2026_plus_verified_exchange_hours_2026_2027_marked_estimates_remaining",
        },
        "risk_policy": RISK_POLICY,
        "market_context": _get_market_context_snapshot().get("summary"),
        "warnings": warnings,
        "critical": critical,
    }


