@app.get("/api/trade-reminders")
def get_trade_reminders(
    status: Optional[str] = Query(None, description="Filter: active, triggered, expired, cancelled"),
    authorization: Optional[str] = Header(None),
):
    """List trade reminders for browser polling and UI status."""
    owner_email, is_admin = _authenticated_request_identity(authorization)
    with _TRADE_REMINDER_LOCK:
        reminders = _load_trade_reminders()
    if not is_admin:
        reminders = [
            reminder for reminder in reminders
            if str(reminder.get("owner_email") or "").strip().lower() == owner_email
        ]
    if status:
        wanted = status.lower()
        reminders = [r for r in reminders if str(r.get("status", "")).lower() == wanted]
    now = _reminder_now()
    public = []
    for r in reminders:
        expires_at = float(r.get("expires_at", 0) or 0)
        last_check = dict(r.get("last_check") or {}) if isinstance(r.get("last_check"), dict) else r.get("last_check")
        trigger_result = dict(r.get("trigger_result") or {}) if isinstance(r.get("trigger_result"), dict) else r.get("trigger_result")
        if isinstance(last_check, dict):
            last_check.pop("row", None)
        if isinstance(trigger_result, dict):
            trigger_result.pop("row", None)
        public.append({
            "id": r.get("id"),
            "ticker": r.get("ticker"),
            "asset_type": r.get("asset_type"),
            "scanner": r.get("scanner"),
            "condition": r.get("condition"),
            "channel": r.get("channel"),
            "status": r.get("status"),
            "created_at": r.get("created_at"),
            "expires_at": r.get("expires_at_iso"),
            "triggered_at": r.get("triggered_at"),
            "last_check": last_check,
            "trigger_result": trigger_result,
            "remaining_seconds": max(0, int(expires_at - now)) if expires_at else None,
        })
    return {
        "status": "ok",
        "count": len(public),
        "reminders": public,
        "timestamp": datetime.now().isoformat(),
    }


@app.post("/api/trade-reminders")
def create_trade_reminder(
    request: TradeReminderRequest,
    authorization: Optional[str] = Header(None),
):
    """Create a temporary monitor for a ticker/coin trigger or retest."""
    owner_email, _ = _authenticated_request_identity(authorization)
    ticker = str(request.ticker or "").upper().strip()
    if not ticker:
        raise HTTPException(status_code=400, detail="Ticker fehlt")
    asset_type = str(request.asset_type or "crypto").strip().lower()
    if asset_type not in {"stock", "crypto"}:
        raise HTTPException(status_code=400, detail="Asset-Typ muss stock oder crypto sein")
    condition = str(request.condition or "trigger_or_retest").strip().lower()
    if condition not in {"trigger", "retest", "continuation", "trigger_or_retest"}:
        raise HTTPException(status_code=400, detail="Unbekannte Reminder-Bedingung")
    duration_hours = max(0.25, min(float(request.duration_hours or 6), _TRADE_REMINDER_MAX_HOURS))
    channel = str(request.channel or "email_browser").lower()
    if channel not in ("email", "browser", "email_browser"):
        channel = "email_browser"
    now = _reminder_now()
    row = request.row if isinstance(request.row, dict) else {}
    normalized_ticker = ticker[:-4] if asset_type == "crypto" and ticker.endswith("USDT") else ticker
    reminder = {
        "id": uuid.uuid4().hex[:12],
        "owner_email": owner_email,
        "ticker": normalized_ticker,
        "asset_type": asset_type,
        "scanner": str(request.scanner or "early_movers"),
        "condition": condition,
        "channel": channel,
        "status": "active",
        "row": row,
        "created_at": _reminder_iso(now),
        "created_at_epoch": now,
        "updated_at": _reminder_iso(now),
        "expires_at": now + duration_hours * 3600,
        "expires_at_iso": _reminder_iso(now + duration_hours * 3600),
        "last_checked_at": 0,
        "last_check": None,
    }
    with _TRADE_REMINDER_LOCK:
        reminders = _load_trade_reminders()
        # One active reminder per user and instrument avoids duplicate trigger/retest mails.
        for old in reminders:
            if (
                old.get("status") == "active"
                and str(old.get("owner_email") or "").strip().lower() == owner_email
                and str(old.get("ticker", "")).upper() == reminder["ticker"]
                and str(old.get("asset_type", "")).lower() == reminder["asset_type"]
            ):
                old["status"] = "cancelled"
                old["updated_at"] = _reminder_iso(now)
        reminders.append(reminder)
        _save_trade_reminders(reminders)
    public_reminder = {k: v for k, v in reminder.items() if k != "row"}
    public_reminder["expires_at"] = reminder["expires_at_iso"]
    public_reminder["remaining_seconds"] = max(0, int(reminder["expires_at"] - now))
    return {
        "status": "ok",
        "message": f"Reminder fuer {reminder['ticker']} aktiv",
        "reminder": public_reminder,
    }


@app.delete("/api/trade-reminders/{reminder_id}")
def cancel_trade_reminder(
    reminder_id: str,
    authorization: Optional[str] = Header(None),
):
    """Cancel a reminder."""
    owner_email, is_admin = _authenticated_request_identity(authorization)
    changed = False
    with _TRADE_REMINDER_LOCK:
        reminders = _load_trade_reminders()
        for r in reminders:
            reminder_owner = str(r.get("owner_email") or "").strip().lower()
            if (
                r.get("id") == reminder_id
                and r.get("status") == "active"
                and (is_admin or reminder_owner == owner_email)
            ):
                r["status"] = "cancelled"
                r["updated_at"] = _reminder_iso()
                changed = True
        if changed:
            _save_trade_reminders(reminders)
    if not changed:
        raise HTTPException(status_code=404, detail="Aktiver Reminder nicht gefunden")
    return {"status": "ok", "message": "Reminder deaktiviert"}


