@app.get("/api/penny-stocks-results")
def get_penny_stock_results(include_watch: bool = False):
    with _scan_lock:
        scan_state = dict(_scan_status.get("penny_stocks", {}))
    cached_rows, cached_at, metadata, is_partial = load_live_cache_file(
        PENNY_STOCKS_CACHE,
        running=bool(scan_state.get("running")),
    )
    monitor_rows, monitor_cached_at = load_cache_file(PENNY_STOCKS_MONITOR_CACHE)
    monitor_metadata = load_cache_metadata(PENNY_STOCKS_MONITOR_CACHE)

    def cache_age_seconds(value: Optional[str]) -> Optional[int]:
        if not value:
            return None
        try:
            parsed = datetime.fromisoformat(value)
            current = datetime.now(parsed.tzinfo) if parsed.tzinfo else datetime.now()
            return max(0, int((current - parsed).total_seconds()))
        except Exception:
            return None

    cache_age = cache_age_seconds(cached_at)
    monitor_cache_age = cache_age_seconds(monitor_cached_at)
    # During a running scan, expose already checked wait/trigger rows from the
    # isolated partial cache so the UI can show real progress. These rows never
    # enter the final cache or alert pipeline until final live revalidation.
    effective_include_watch = bool(include_watch or is_partial)
    discovery_visible = _penny_active_trade_rows(
        cached_rows,
        include_watch=effective_include_watch,
        cache_age_seconds=cache_age,
    )
    monitor_visible = _penny_active_trade_rows(
        monitor_rows,
        include_watch=include_watch,
        cache_age_seconds=monitor_cache_age,
    )
    # Monitor state is authoritative for a ticker already opened by a
    # successful Penny buy mail. Replacing the value preserves the original
    # discovery order while preventing duplicate or contradictory rows.
    merged_by_ticker: Dict[str, Dict[str, Any]] = {}
    for row in discovery_visible:
        symbol = str(row.get("ticker") or "").upper().strip()
        if symbol:
            merged_by_ticker[symbol] = row
    for row in monitor_visible:
        symbol = str(row.get("ticker") or "").upper().strip()
        if symbol:
            merged_by_ticker[symbol] = row
    action_rank = {
        "JETZT_VERKAUFEN": 0,
        "JETZT_KAUFEN": 1,
        "HALTEN": 2,
        "TRIGGER_WARTEN": 3,
        "BEOBACHTEN": 4,
    }
    rows = sorted(
        merged_by_ticker.values(),
        key=lambda row: (
            action_rank.get(str(row.get("trade_action") or "").upper(), 9),
            -(_alert_float(row.get("trade_score"), 0.0) or 0.0),
        ),
    )
    near_entries = _penny_near_entry_rows(
        cached_rows,
        cache_age_seconds=cache_age,
    )
    prep_rows = _penny_trigger_prep_rows(
        cached_rows,
        cache_age_seconds=cache_age,
    )
    auto_show_prep = bool(not rows and not include_watch and prep_rows)
    if auto_show_prep:
        rows = prep_rows
    requested_actions = _PENNY_VISIBLE_ACTIONS | (
        _PENNY_OPTIONAL_ACTIONS if (effective_include_watch or auto_show_prep) else frozenset()
    )
    raw_symbols = {
        str(row.get("ticker") or "").upper().strip()
        for source_rows in (cached_rows, monitor_rows)
        for row in (source_rows if isinstance(source_rows, list) else [])
        if isinstance(row, dict)
        and str(row.get("trade_action") or "").upper() in requested_actions
        and str(row.get("ticker") or "").strip()
    }
    raw_visible_count = len(raw_symbols)
    diagnostics = dict(metadata.get("diagnostics") or {})
    with _scan_lock:
        current_scan_error = _scan_status.get("penny_stocks", {}).get("last_error")
        current_monitor_error = _scan_status.get("penny_positions", {}).get("last_error")
    diagnostics.update({
        "signal_max_age_seconds": _PENNY_TRIGGER_MAX_AGE_SECONDS,
        "result_cache_max_age_seconds": _PENNY_RESULT_CACHE_MAX_AGE_SECONDS,
        "expired_or_stale_signals_suppressed": max(0, raw_visible_count - len(rows)),
        "signal_cache_expired": bool(
            cache_age is not None and cache_age > _PENNY_RESULT_CACHE_MAX_AGE_SECONDS
        ),
        "last_scan_error": current_scan_error,
        "position_monitor": {
            **dict(monitor_metadata.get("diagnostics") or {}),
            "cached_at": monitor_cached_at,
            "cache_age_seconds": monitor_cache_age,
            "last_error": current_monitor_error,
        },
        "combined_buy_now": sum(1 for row in rows if row.get("trade_action") == "JETZT_KAUFEN"),
        "combined_hold_now": sum(1 for row in rows if row.get("trade_action") == "HALTEN"),
        "combined_exit_now": sum(1 for row in rows if row.get("trade_action") == "JETZT_VERKAUFEN"),
        "trigger_prep_count": len(prep_rows),
        "auto_show_trigger_prep": auto_show_prep,
    })
    return {
        "status": "warning" if current_scan_error or current_monitor_error else "success",
        "data": rows,
        "near_entries": near_entries,
        "trigger_prep_rows": prep_rows,
        "cached_at": cached_at,
        "cache_age_seconds": cache_age,
        "monitor_cached_at": monitor_cached_at,
        "monitor_cache_age_seconds": monitor_cache_age,
        "scan_running": bool(scan_state.get("running")),
        "partial": is_partial,
        "checked": metadata.get("checked"),
        "total": metadata.get("total"),
        "progress_detail": metadata.get("detail"),
        "include_watch": include_watch,
        "auto_show_trigger_prep": auto_show_prep,
        "partial_watch_rows": bool(is_partial and not include_watch),
        "diagnostics": diagnostics,
        "policy": {
            "universe": f"active US common stocks ${PENNY_MIN_PRICE:.2f}-${PENNY_MAX_PRICE:.2f}",
            "discovery_interval_minutes": 30,
            "position_monitor_interval_minutes": 5,
            "live_signal_max_age_seconds": _PENNY_TRIGGER_MAX_AGE_SECONDS,
            "optional_row_limit": _PENNY_OPTIONAL_ROW_LIMIT,
            "near_entry_row_limit": _PENNY_NEAR_ENTRY_ROW_LIMIT,
            "buy_mail_requires": f"fresh closed 5m breakout/retest + live ask/spread <= {PENNY_EXECUTION_MAX_SPREAD_BPS:.0f}bps + 20d-median RVOL + SEC clear + structural stop/TP + trade score >= {PENNY_MIN_TRADE_SCORE:.0f}",
            "float_note": "Only reported free float is used. Missing float receives no score and is shown as unknown.",
        },
    }


@app.get("/api/penny-stocks/replay")
def replay_penny_stock_signal(
    ticker: str,
    trigger_timestamp: int,
    entry: float,
    stop: float,
    tp1: float,
    tp2: float,
    horizon_hours: int = 24,
    spread_bps: float = 80.0,
    slippage_bps: float = 15.0,
):
    """Replay an emitted Penny setup on bars strictly after its closed trigger."""
    symbol = str(ticker or "").upper().strip()
    if not re.fullmatch(r"[A-Z0-9.\-]{1,15}", symbol):
        raise HTTPException(status_code=400, detail="Invalid ticker")
    if trigger_timestamp <= 0 or not (0 < stop < entry < tp1 < tp2):
        raise HTTPException(status_code=400, detail="Invalid long trade levels or trigger timestamp")
    horizon = max(1, min(int(horizon_hours or 24), 120))
    trigger_dt = datetime.fromtimestamp(trigger_timestamp, tz=timezone.utc)
    end_dt = trigger_dt + timedelta(hours=horizon)
    url = (
        f"https://api.polygon.io/v2/aggs/ticker/{symbol}/range/5/minute/"
        f"{trigger_dt.strftime('%Y-%m-%d')}/{end_dt.strftime('%Y-%m-%d')}"
    )
    response = rate_limited_get(
        url,
        params={"apiKey": POLYGON_KEY, "adjusted": "true", "sort": "asc", "limit": 5000},
        timeout=20,
    )
    if response.status_code != 200:
        raise HTTPException(status_code=502, detail=f"Market data HTTP {response.status_code}")
    start_ms = (trigger_timestamp + 300) * 1000
    end_ms = end_dt.timestamp() * 1000
    future_bars = [
        {
            "open": raw.get("o"),
            "high": raw.get("h"),
            "low": raw.get("l"),
            "close": raw.get("c"),
            "volume": raw.get("v"),
            "timestamp": raw.get("t"),
        }
        for raw in (response.json().get("results", []) or [])
        if start_ms <= (_alert_float(raw.get("t"), 0.0) or 0.0) <= end_ms
    ]
    result = evaluate_penny_signal_outcome(
        entry,
        stop,
        tp1,
        tp2,
        future_bars,
        spread_bps=max(0.0, min(float(spread_bps), 500.0)),
        slippage_bps=max(0.0, min(float(slippage_bps), 250.0)),
    )
    if not result.get("valid"):
        raise HTTPException(status_code=404, detail="No valid post-trigger 5m bars for replay")
    return {
        "status": "success",
        "ticker": symbol,
        "trigger_timestamp": trigger_timestamp,
        "horizon_hours": horizon,
        "bars_replayed": len(future_bars),
        "result": result,
        "note": "Historical OHLC replay with costs; not tick-level execution and not a profitability guarantee.",
    }


VOLUME_SPIKES_CACHE = "/tmp/volume_spikes_cache.json"

def _volume_spikes_wrapper() -> None:
    """Find US stocks with unusual volume (RVOL > 3.0, price > $2)."""
    try:
        spikes = []
        tickers = []

        try:
            snap_resp = rate_limited_get(
                "https://api.polygon.io/v2/snapshot/locale/us/markets/stocks/tickers",
                params={"apiKey": POLYGON_KEY},
                timeout=30,
            )
            if snap_resp.status_code == 200:
                tickers.extend(snap_resp.json().get("tickers", []))
        except Exception:
            pass

        if len(tickers) < 250:
            for endpoint in ["gainers", "losers"]:
                snap_url = f"https://api.polygon.io/v2/snapshot/locale/us/markets/stocks/{endpoint}"
                snap_resp = rate_limited_get(snap_url, params={"apiKey": POLYGON_KEY, "limit": 250})

                if snap_resp.status_code != 200:
                    if snap_resp.status_code == 403:
                        print(f"[Warning] 403 Forbidden on {endpoint} endpoint - check API plan")
                    continue
                tickers.extend(snap_resp.json().get("tickers", []))

        common_stock_universe, common_stock_source = _load_common_stock_universe()
        volume_fraction = _us_equity_expected_volume_fraction(datetime.now(timezone.utc))
        seen_symbols = set()
        for t in tickers:
                try:
                    symbol = str(t.get("ticker", "") or "").upper().strip()
                    if not symbol or symbol in seen_symbols:
                        continue
                    seen_symbols.add(symbol)
                    if _stock_alert_asset_exclusion_reason(
                        symbol,
                        common_stock_universe=common_stock_universe,
                        universe_source=common_stock_source,
                        require_reference=common_stock_universe is None,
                    ):
                        continue
                    day = t.get("day", {})
                    prev = t.get("prevDay", {})

                    price = day.get("c", 0) or t.get("lastTrade", {}).get("p", 0)
                    if not price or price < 2:
                        continue

                    vol = day.get("v", 0)
                    prev_vol = prev.get("v", 0)

                    # Fix 2a: RVOL Baseline — use prevDay volume as quick baseline
                    # Snapshot only has day + prevDay; 20-day median would need extra API call per ticker
                    # For gainers/losers bulk scan, prevDay is acceptable (close enough to median for high-vol stocks)
                    if prev_vol > 0:
                        rvol_raw = vol / prev_vol
                        rvol = rvol_raw / max(volume_fraction, 0.01)
                    else:
                        continue

                    if rvol > 3.0:
                        prev_close = prev.get("c", 0)
                        chg = ((price - prev_close) / prev_close * 100) if prev_close else 0

                        # Fix 2b: Dollar Volume Minimum
                        dollar_volume = price * vol
                        projected_dollar_volume = dollar_volume / max(volume_fraction, 0.01)
                        if projected_dollar_volume < 1_000_000 or dollar_volume < 100_000:
                            continue

                        # Fix 2c: Breakout vs Absorption
                        price_change_pct = ((price - prev_close) / prev_close * 100) if prev_close > 0 else 0
                        if abs(price_change_pct) > 2:
                            signal_type = "BREAKOUT" if price_change_pct > 0 else "BREAKDOWN"
                        elif abs(price_change_pct) < 0.5:
                            signal_type = "ABSORPTION"  # High volume, no price move = accumulation/distribution
                        else:
                            signal_type = "NORMAL"

                        spikes.append({
                            "ticker": symbol,
                            "price": round(price, 2),
                            "change_pct": round(chg, 2),
                            "volume": vol,
                            "rvol": round(rvol, 2),
                            "rvol_raw": round(rvol_raw, 2),
                            "rvol_source": "prev_day_intraday_time_adjusted_proxy" if volume_fraction < 1.0 else "prev_day_completed_session_proxy",
                            "dollar_volume": round(dollar_volume, 0),
                            "projected_dollar_volume": round(projected_dollar_volume, 0),
                            "expected_volume_fraction": round(volume_fraction, 4),
                            "signal_type": signal_type,
                            "asset_class": "stock",
                            "trade_signal": "BEOBACHTEN",
                            "trade_action": "BEOBACHTEN",
                            "signal_label": "Achtung beobachten: Aktien-Volume-Spike, kein Crypto-Signal",
                            "execution_trigger_ok": False,
                        })
                except Exception as e:
                    print(f"[Warning] Error processing volume spike for ticker: {e}")
                    continue

        # Sort by RVOL descending
        spikes.sort(key=lambda x: x.get("rvol", 0), reverse=True)
        save_cache_file(VOLUME_SPIKES_CACHE, spikes[:50])  # Keep top 50
    except Exception as e:
        print(f"Volume spikes error: {e}")
        traceback.print_exc()
        raise


